window.LIAO=window.LIAO||{};LIAO.interp={"generated":"2026-08-27","stats":{"sessions":114,"skipped":3,"first":"2024-03-04","last":"2026-06-25","by_committee":{"社會福利及衛生環境委員會":102,"經濟委員會":5,"交通委員會":3,"教育及文化委員會":2,"內政委員會":1,"司法及法制委員會":1},"by_year":{"2024":56,"2025":37,"2026":21},"topics":[["職場霸凌",6],["食安",6],["護理人力",5],["碳費",5],["癌症篩檢",4],["就業安定基金",4],["缺工",4],["長照",3],["社會安全網",3],["身心障礙者權益保障法",3],["巴氏量表",3],["家庭照顧假",3],["空氣品質",3],["勞動部",3],["電價調漲",3],["健保點值",3],["育嬰留職停薪",2],["醫療暴力",2],["勞動權益",2],["職業訓練",2],["跨部會協調",2],["失智症",2],["外送專法",2],["社工人力",2],["兒少保護",2],["能源轉型",2],["移工",2],["急診壅塞",2],["預算編列",2],["合理調整",2],["垃圾山",2],["個人助理",2],["三班護病比",2],["青年就業",2],["健保給付",2],["外送平台專法",2],["勞保財務",2],["非洲豬瘟",2],["邊境查驗",2],["關稅衝擊",2]],"targets":[["衛生福利部",59],["勞動部",49],["環境部",34],["署",14],["經濟部",10],["內政部",7],["行政院",6],["法務部",5],["交通部",5],["教育部",5],["農業部",4],["食品藥物管理署",4],["部",4],["數位發展部",3],["衛福部",3],["司長陳美女",2],["勞工保險局",2],["司法院",2],["勞動力發展署",2],["食藥署",2],["健保署",2],["臺大醫院",2],["台灣電力股份有限公司",2],["疾管署",2],["國健署",1],["次長賴建信（與能源署",1],["保訓會",1],["職安署",1],["國防部",1],["關務署",1]],"demands":549,"followups":0,"faults":531,"chars":520625},"cards":[{"gz":"GZ-1155503_00002","date":"2026-06-25","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第16次會議一、審查及繼續審查「性別平等工作法部分條文修正草案」等117案：(一)審查行政院函請審議「性別平等工作法部分條文修正草案」案、(二)繼續審查委員范雲等17人擬具「性別平等工作法部分條文修正草案」案、(三)","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/55/LCIDC01_1155503.pdf","pages":"341-400","target":["司長陳美女"],"title":"育嬰留停補助百分之二十應入法 留停延長到八個月","topics":["育嬰留職停薪","育嬰留停津貼","就業保險","性別平等工作法"],"summary":"廖偉翔關心育嬰留職停薪的經濟保障。他查到主管機關在民國110年6月4號訂定育嬰留職停薪薪資補助要點，另外加給百分之二十，但這只是行政要點，不是法律。他要求說清楚為什麼不把這百分之二十入法、所謂要對齊的根本理由是什麼，並主張把育嬰留職停薪延長到八個月一併入法。","demands":["要求把民國110年6月4號訂定的育嬰留停薪資補助要點入法","要求說明加給百分之二十為何不入法","要求解釋所謂要對齊的根本理由是什麼","主張育嬰留職停薪延長到八個月，並且入法","要求再敘述一次不能入法的原因"],"faults":["育嬰留停加給百分之二十只訂在要點，沒有入法","不入法的理由講不清楚，委員聽完仍不了解","育嬰留職停薪延長到八個月的提案，未獲正面回應"],"reply":"司長說育嬰留停津貼參照就業保險標準，110年要點另加百分之二十已達八成，再加會接近在職薪水，主張維持失業給付標準。","quotes":["你剛剛提到百分之二十，但我還是不太了解","要對齊的根本理由是什麼？可否再解釋一下？"],"fixed":false,"chars":887,"followups":[]},{"gz":"GZ-1155003_00002","date":"2026-06-10","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第14次會議一、繼續審查委員柯志恩等17人擬具「醫療法第二十四條及第一百零六條條文修正草案」案；二、繼續審查委員林月琴等17人擬具「醫療法第二十四條及第一百零六條條文修正草案」案；三、繼續審查委員王育敏等16人擬具「","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/50/LCIDC01_1155003.pdf","pages":"125-360","target":["衛生福利部","衛生福利部石部長"],"title":"醫療暴力平均判2.9個月　要求刑度突破易科罰金","topics":["醫療暴力","醫療法修法","護理人力","刑度"],"summary":"廖偉翔關心醫療暴力。他說近年判決九成以上有罪，平均刑期只有2.9個月，超過99%易科罰金結案；衛福部通報從2022年264件增到2024年444件，約七成受害人是護理師。他認為不是法律不夠重，是制度讓法律重不起來，要求調整刑度、增訂警察協助制止法源，並把必要措施具體化。","demands":["衛福部調整醫療法第106條刑度結構，檢討酒後犯與累犯加重","讓宣告刑突破易科罰金門檻，刑罰才有牙齒","增訂警察到場前協助制止的法源，並明確化協助範圍","把第24條必要措施具體化：安全設備、通報蒐證、院方協助提告義務","上述措施要訂標準、罰則與中央預算，後續修法通盤考量"],"faults":["衛福部年年宣示醫療暴力零容忍，通報數字卻不減反增","2017年修法至今9年，通報從264件增到444件，創近5年新高","法定刑3年，實務平均只有2.9個月，超過99%易科罰金結案","通報最大宗的語言暴力多數進不了妨害醫療罪的門，只能自己提告公然侮辱","一邊立法保障三班護病比，一邊讓護理師值班時挨打挨罵"],"reply":"","quotes":["九成以上被告被判決有罪，但平均刑期只有 2.9 個月","國家至少要做到讓動手的人付出代價，不能只是一張罰單"],"fixed":false,"chars":974,"followups":[]},{"gz":"GZ-1154804_00002","date":"2026-06-03","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第13次會議一、審查「性別平等工作法」修正草案等100案：(一)委員范雲等17人擬具「性別平等工作法部分條文修正草案」案、(二)委員郭昱晴等17人擬具「性別平等工作法第十五條條文修正草案」案、(三)委員萬美玲等35人","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/48/LCIDC01_1154804.pdf","pages":"81-316","target":["勞動部","勞動部長洪申翰"],"title":"廖偉翔要求勞動部盤點AI高風險職務並建預警機制","topics":["AI衝擊就業","勞動權益","職業訓練","跨部會協調"],"summary":"廖偉翔關心AI對勞動市場的衝擊。他引用IMF警告全球約40%的工作會受AI影響、已開發經濟體可能高達60%，追問勞動部有沒有評估台灣哪些職務最容易被衝擊。部長說目前靠詢問產業、還要觀察，他批評這像鴕鳥心態，並指2024年底就提過動議要做研究報告，一年多還看不到。他要求提前盤點高風險職務、建立風險清單與預警儀表板，並比照新加坡引導企業成立培訓委員會。","demands":["勞動部兩個月內提供AI高風險職務追蹤計畫給廖偉翔辦公室","企業AI導入與勞工權益揭露指引，一個月內先提供規劃","研議台灣版企業AI培訓委員會，跨部會溝通後兩個月內給報告","政府AI補助案納入勞工影響評估與再培訓，兩個月內回報","風險清單要分類，如AI輔助型、流程重組型、高替代風險職務"],"faults":["勞動部只靠詢問產業掌握AI衝擊，拿不出量化數據","2024年底就提動議要研究報告，一年多仍沒有提出","監測計畫說已在執行，但第一期數據還沒出來","職訓已開AI課程，卻沒追蹤再就業率與實際成效"],"reply":"洪申翰說台灣目前沒有因AI出現大規模失業，要做滾動性監測、約半年發布一次；承諾兩個月內提供追蹤計畫，指引一個月內先給規劃。","quotes":["這樣子的回答我有點擔心，真的有點像鴕鳥心態","最後受到 AI 衝擊的勞工就是交給你們處理嘛，我覺得這個部分要提早因應"],"fixed":false,"chars":5473,"followups":[]},{"gz":"GZ-1154502_00001","date":"2026-05-28","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第12次會議審查一、國民黨黨團擬具「失智症基本法草案」案；二、台灣民眾黨黨團擬具「失智症基本法草案」案；三、委員林月琴等19人擬具「失智症基本法草案」案【詢答】","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/45/LCIDC01_1154502.pdf","pages":"1-252","target":["衛生福利部次長呂建德","勞動部","法務部","內政部"],"title":"失智症應立基本法，統籌層級拉到行政院長","topics":["失智症","失智症基本法","長照","跨部會統籌"],"summary":"審查失智症基本法草案。廖偉翔說65歲以上失智盛行率7.99%、85歲以上23.23%，現在約38萬個家庭，2041年逼近68萬。政策綱領2.0去年底到期，衛福部沒有獨立的3.0，降級成2.0 plus塞進長照3.0專章，只是行政命令，沒有法律位階也沒課責，指揮不動12個部會，他主張立專法。","demands":["衛福部6月底前公布獨立的失智症行動計畫3.0","認知功能檢測納入成人與老人健檢，兩個禮拜內給辦公室方向與報告","一個禮拜內提供與勞動部三次雙次長會議的時間、內容與結論","比照癌症登記，建立全國失智症登錄系統，掌握確診個案","衛福部支持失智症基本法立法，統籌層級拉到行政院長"],"faults":["衛福部：失智症政策綱領2.0去年底到期，至今沒有獨立的3.0","衛福部把失智症降級成2.0 plus，塞進長照3.0專章","只靠行政計畫沒有法律位階也沒有課責，預算說砍就砍","成人與老人健檢至今沒有常態納入認知功能評估","失智症只有流行病學推估，九個系統資料整合不好"],"reply":"呂建德說6月底前公布行動計畫3.0，認知檢測與跨部會會議資料會研議提供；勞動部說假別與就業支持帶回研議。","quotes":["行政計畫沒有課責，做不好沒有任何人要負法律的責任。","既然重視就要有行動表現，希望至少要由行政院長來統籌。"],"fixed":true,"chars":6157,"followups":[]},{"gz":"GZ-1154002_00002","date":"2026-05-11","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第10次會議一、審查中華民國115年度中央政府總預算案關於衛生福利部主管預算（公務及非營業特種基金預算案）；二、審查中華民國115年度中央政府總預算案直轄市及縣市政府一般性補助款衛生福利部主管部分預算（詢答）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/40/LCIDC01_1154002.pdf","pages":"65-256","target":["衛生福利部部長石崇良","國健署署長沈靜芬"],"title":"癌篩擴大到六癌預算卻短少11億，要檢討報告","topics":["癌症篩檢","衛福部預算","醫事人力","醫院評鑑"],"summary":"廖偉翔盯癌症篩檢預算。他算出114年公務預算加基金合計八十二億五千多萬，115年只剩71億900萬，短少11億5,000萬。部裡說少14億是改由公務預算辦理，公務預算卻只多三億多，差額說不清。他也指醫檢師、放射師人力短缺，醫院評鑑只看病床數，要求說明原因並改善人力。","demands":["衛福部說明癌篩短少11億的根本原因，並提檢討報告","提供114年篩檢酬金人次、各癌受理件數與最終執行預算","提供115年預估酬金人次與預計處理件數","攝護腺癌公費篩檢推動報告5月底提出，儘速推動","1個月內給辦公室檢討報告，並提前召開評鑑基準研商會議"],"faults":["國健署擴大到六癌篩檢，整體癌篩預算反而少11億5,000萬","說少14億是改由公務預算辦理，公務預算卻只增加三億多","癌篩執行狀況查不到，像黑箱，看不出成效","醫檢師人力評鑑只看病床數，忽略門診與急診檢驗量","承諾的評鑑基準研商會議還沒開，要等到明年"],"reply":"石崇良說會另外整理詳細執行情形給委員，健保支付制度會改善醫檢、醫放薪資，評鑑標準修訂下半年討論；國衛院說攝護腺癌報告5月底出。","quotes":["我們就擔心你像在沙灘上面蓋大樓，沒有好的基礎","因為當我要查這些資料時，我覺得滿黑箱的、看不到"],"fixed":true,"chars":3583,"followups":[]},{"gz":"GZ-1153802_00003","date":"2026-05-07","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議一、邀請勞動部部長列席報告業務概況，並備質詢；二、審查中華民國115年度中央政府總預算案關於勞動部主管預算（公務及非營業特種基金預算案）；三、審查勞動部函送財團法人職業災害預防及重建中心115年度預算書案【","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/38/LCIDC01_1153802.pdf","pages":"293-472","target":["勞動部","勞動部部長洪申翰"],"title":"勞保投保上限10年沒動，要求檢討級距與資遣費上限","topics":["勞保投保薪資上限","育兒減工時","資遣費上限","外送專法"],"summary":"廖偉翔關心勞保投保薪資上限自2016年調高到4萬5,800元後，10年沒再調整，高薪低報比比皆是。他指出2006年勞保天花板是基本工資的2.77倍，現在只剩1.55倍。他要求勞動部給出就保與勞保脫鉤時程、研議調高勞保級距，把育兒減工時補貼納入政策，並檢討資遣費6個月上限。","demands":["勞動部一個月內提出就保與勞保投保薪資上限脫鉤的具體想法","勞保級距調整兩個月內提供評估資料給辦公室與衛環委員會","把補貼育兒減工時納入勞動部政策計畫，並協助地方政府辦理","就安基金今年底現金上看440億，兩個月內提出具體做法","研議取消資遣費6個月上限，每多一年多半個月，兩個月內給評估"],"faults":["勞保投保薪資上限自2016年起10年未調，高薪低報比比皆是","20年來勞保上限只微調過一次，漲幅只有4.3%","育兒減工時補貼只說研議、配套，講不出完備時程","外送專法7月要上路，各部會定型化契約進度掌握不清"],"reply":"洪申翰說勞保財務壓力大所以謹慎，就保脫鉤一個月內提想法，勞保級距與資遣費兩個月內給評估資料，育兒減工時一、兩個月內提做法。","quotes":["基本上就是樓地板要撞到天花板","12年跟30年如果都一樣是6個月，其實是不公平的"],"fixed":false,"chars":5329,"followups":[]},{"gz":"GZ-1153501_00010","date":"2026-04-29","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第8次會議一、審查(一)委員羅廷瑋等43人擬具「空氣污染防制法第二十七條、第二十八條及第三十條條文修正草案」案、(二)台灣民眾黨黨團擬具「空氣污染防制法第三十條條文修正草案」案；二、繼續審查(一)委員柯志恩等17人擬","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/35/LCIDC01_1153501.pdf","pages":"337-468","target":["環境部","環境部長彭啓明","環境部司長黃偉鳴","次長賴建信（與能源署署長同組備詢，答中火老舊機組拆除，非環境部業務）"],"title":"麥寮燃煤重啟要環境部把關 另追中火老舊機組拆除","topics":["空污防制","燃煤機組重啟","三級防制區","淨零減煤"],"summary":"經濟部責成台電短期調度麥寮一、三號燃煤機組發電三個月。廖偉翔指出雲林是空品不達標的三級防制區，臺大公衛研究顯示六輕周邊高暴露居民癌症發生率是其他鄉鎮的1.29倍，重啟卻沒有法令依據，也沒問過環境部。他要求環境部別只被動監測，應訂老舊燃煤機組重啟的最低檢核機制，一個月內提報告。質詢最後換次長與能源署署長上台，他另外追問臺中電廠老舊一號、二號機組的拆除時程。","demands":["環境部一個月內給辦公室初步報告，說明重啟過程中的角色與檢核流程","環境部一個月內回報一級致癌物苯駢芘是否納入環評或空污排放標準","重啟機組要有健康風險與空污監測分析，重啟後再提環境影響回顧評估","老舊燃煤機組延役或短期調度，應訂最低環境檢核機制與替代調度方案","另向次長追問中火老舊一號、二號機組拆除，要求承諾2028年底前完成（此題不是對環境部）"],"faults":["環境部面對麥寮重啟只說會嚴格監督，被動等經濟部決定，沒有主動作為","重啟欠缺明確法令依據，與空污法、環境基本法環境優先的規定衝突","監察院去年已糾正麥寮1號機延役程序倉促，今年重啟又重蹈覆轍","我國至今未對一級致癌物苯駢芘訂排放標準，歐盟2004年就已納管","環境部對重啟與檢核機制一再回答會研議，說不出具體時程"],"reply":"彭啓明說已請經濟部與台電審慎評估重啟必要性，會責成雲林縣環保局嚴密監督排放，允諾一個月內給初步報告；苯駢芘排放標準由司長表示後續評估。","quotes":["調度能源是經濟部的權責，可是環境部的責任就是要幫我們把關環境和空污","環境評估不是一核定就是終身，你們也要適時介入、滾動調整"],"fixed":true,"chars":6198,"followups":[]},{"gz":"GZ-1153402_00002","date":"2026-04-23","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議邀請衛生福利部部長、教育部、法務部就「脆弱家庭兒少支持服務及兒少保護個案處遇之跨體系協作與銜接機制檢討」進行專題報告，並備質詢（115年4月22日、115年4月23日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/34/LCIDC01_1153402.pdf","pages":"219-300","target":["衛生福利部部長石崇良"],"title":"社安網2.0擴大服務卻缺人，KPI恐淪數字遊戲","topics":["社會安全網","社工人力","KPI考核","兒少保護"],"summary":"廖偉翔檢視強化社會安全網計畫2.0，指出社工進用率從89.7%掉到82.8%，地方為衝考核可能到職一天就離職、或被拜託撐過12月再走。計畫還要擴大服務對象，他推估第一線工作量至少增加20%，但支薪標準卡著、AI分案還在招標。他要求KPI回頭檢討，一個月內給辦公室具體做法。","demands":["衛福部查清每月社工人數變動，把離職潮資料提供給委員辦公室","衛福部回頭檢討社安網2.0的KPI指標，一個月內提出檢討","研擬一份完整的應對報告，一個月內交到委員辦公室","檢討支薪標準，考慮增加薪點或薪點折合率，才留得住人才","建立案件風險評估與分流分級機制，不要一味用數字壓服務比率"],"faults":["衛福部沒掌握地方把自聘人力轉入、到職一天就離職衝進用率的狀況","社工流動率最新統計只到114年12月底，115年第一季還在觀測","部長說再通報率已不當KPI，但2.0文件裡脆弱家庭三個月再通報率目標還在","自殺關懷訪視員平均每人74案，是原規劃的2倍，1：30的目標還沒開始就破功","數位與AI導入還在招標，第一階段系統要年底才完成"],"reply":"石崇良說進用率未達85%扣分的KPI今年已取消，再通報率不再拿來考核，服務比率是篩案後的比率，並承諾一個月內把KPI指標再檢討一次。","quotes":["社工不是神，有時候不是他們不想解決，而是他可能沒有能力解決","你如果錯誤的把它拿來作為績效的 KPI，你會導致所謂的數字遊戲"],"fixed":false,"chars":6573,"followups":[]},{"gz":"GZ-1153402_00001","date":"2026-04-22","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議一、邀請環境部部長、國家科學及技術委員會、交通部、經濟部、內政部、農業部、衛生福利部、國家發展委員會就「我國氣候變遷調適現況檢討與全球調適目標接軌之推動情形」進行專題報告，並備質詢；二、審查中華民國115年","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/34/LCIDC01_1153402.pdf","pages":"1-218","target":["環境部部長彭啓明","經濟部能源署副署長陳崇憲","農業部資源永續利用司"],"title":"漁電共生誠新案恐跳票 要求綠能目標說清楚","topics":["綠能目標","漁電共生","能源轉型","農地把關"],"summary":"廖偉翔盯2030綠能目標：光電20 GW、減碳25%到30%。他指漁電共生占4.4 GW，誠新集團就被報導接近1.5 GW、等於三成四，還跟台積電簽20年200億度電長約；如今案場出事，官員也承認達不到目標。他要求交代五大案場何時上線、20%綠能11月能否達標，別犧牲法制與農地。","demands":["要能源署講清楚2030年綠能目標到底會不會下修，別只說會努力。","要能源署交代五大漁電案場最快何時上線、20%綠能11月能否達標。","要能源署釐清誠新與新和能源的權責，說明會不會拖累綠能進度。","要農業部說明上百件已併聯漁電案場的回頭核查率與把關結果。","要求不要為保住併網目標犧牲法制與農地公道，不做毀農滅魚的假轉型。"],"faults":["誠新沒有單一案場120 MW的實績，是不同案場合併計算，能源署仍當成實績。","能源署承認這個案場跳票就達不到目標，卻只說用屋頂型案場彌補。","能源署稱個別案場財務狀況不再做了解，權責歸屬交代不清。","農業部漁電查核只說八成多、將近九成，具體數字答不出來。","委員問放養七成養殖達標的案場有幾個，能源署只答有一個不符規定被廢照，沒給出達標數字。"],"reply":"能源署說目標不下修、會以20 GW為目標努力，漁電缺口用屋頂型案場彌補；農業部強調漁電共生仍以養殖為本，綠能是加值。","quotes":["綠能不只是環境問題，其實也是貿易競爭力","我們支持這樣的能源轉型要發展好，可是絕對不支持毀農滅魚的假轉型"],"fixed":true,"chars":4912,"followups":[]},{"gz":"GZ-1153101_00004","date":"2026-04-15","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議一、邀請衛生福利部部長、行政院經貿談判辦公室、經濟部、農業部、教育部就「美國貿易代表署發布《2026年各國貿易評估報告》（2026NTE）提及技術性貿易壁壘或食品安全檢驗與動植物防疫檢疫（SPS）壁壘之豬肉","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/31/LCIDC01_1153101.pdf","pages":"203-308","target":["衛生福利部部長石崇良","農業部動植物防疫檢疫署署長杜麗華"],"title":"寵物用藥登錄拖11年，要求兩周內函釋解氧氣荒","topics":["寵物用藥","醫用氧氣","動保法","狗場超量收容"],"summary":"他關心7月1日上路的寵物用藥辦法。動保法2015年授權訂辦法，拖到2024年才發布，701項藥品只登錄144項、約2成，供應商怕違法不敢賣醫用氧氣。他要求兩周內函釋、一個月內解決氧氣。他也指高雄美濃狗園超量收容349隻、至少5死只罰四萬五，比桃園觀音案輕。","demands":["農業部、食藥署兩周內發函函釋，讓藥商供貨給獸醫院不觸法","一個月內解決醫用氧氣供應，確保各獸醫院急診夠用","會後提供高雄狗園自行減量80隻的去向與跨縣市流向","一個月內提出大量飼養的納管方案"],"faults":["動保法2015年授權訂辦法，農業部拖9年才發布，是行政怠惰","兩年緩衝期只讓701項藥品登錄144項，僅2成","辦法暫緩不等於解決，供應商怕違法已開始拒供醫用氧氣","高雄美濃狗園超量收容349隻、至少5死，只罰四萬五未移送","全國188間民間狗場合法家數是零，安置費443萬要民間募款"],"reply":"石崇良承諾農業部將發函註銷該辦法，食藥署再發函說明新辦法前藥商仍可供應701項藥品含醫用氣體；杜麗華說狗場屬動保司，會後提供資料。","quotes":["根本就是行政怠惰，或者是你行政無能","暫緩不等於解決啊！獸醫師每天在法律風險中救命"],"fixed":false,"chars":4034,"followups":[]},{"gz":"GZ-1152801_00006","date":"2026-04-09","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第5次會議邀請勞動部部長、經濟部、農業部就「防制強迫勞動與公平招募：台灣移工制度接軌國際人權與供應鏈治理」進行專題報告，並備質詢（115年4月8日、115年4月9日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/28/LCIDC01_1152801.pdf","pages":"465-532","target":["勞動部長洪申翰","勞工保險局局長白麗真"],"title":"外籍移工家屬死亡給付結構偏移，要求限期檢討","topics":["移工","勞保","家屬死亡給付","分配正義"],"summary":"廖偉翔盯外籍移工的勞保家屬死亡給付。他說107年至114年6月共給付6.1萬件、51.1億元，占外籍被保險人總給付75%，本國勞工只有49%，變成在臺繳費、全球提領。移工一入境加保，隔天家屬在母國死亡就能領，沒有等待期，死亡證明也難查核。他主張設門檻、資源精準使用，並限期提報告。","demands":["勞動部30天內提供外籍家屬死亡給付退件的統計報告","勞動部3個月內提出勞保跨境給付法規的影響評估","勞動部半年內啟動勞動力輸出國社安資訊交換的談判","研議家屬死亡給付設最低投保期間與居住門檻","研議讓勞保給付有不同選項，給負擔沈重家庭喘息空間"],"faults":["外籍給付75%集中在家屬死亡給付，本國僅49%，結構明顯偏移","死亡證明靠駐外單位驗證，勞保局難以實質查核跨國文件","移工一入境加保，隔天家屬在母國死亡即可請領，沒有等待期","家事移工不強制投保勞保，制度落差造成洗工，弱勢家庭被搶人","沒有社安協定與電子查核就開放跨境請領，國與國缺乏互惠"],"reply":"洪申翰說家屬死亡給付是社會保險不是社會福利，繳了保費就有權利；同意就駐外文件驗證能否更精準、各國制度差異回去研議並給資料。","quotes":["工傷保障由雇主負責，社會福利留給本國國民，資源要精準使用，保障真正該被保障的","全世界只有臺灣在沒有所謂的社安協定、電子查核系統的情況之下，單方面地讓外籍移工跨境請領家屬的死亡給付"],"fixed":false,"chars":6669,"followups":[]},{"gz":"GZ-1152801_00005","date":"2026-04-08","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第5次會議一、邀請環境部部長、經濟部、衛生福利部、農業部就「穩定供給與減塑並進：因應國際原物料波動之原物料穩定供應及我國減塑治理進程」進行專題報告，並備質詢；二、審查「廢棄物清理法條文修正草案」9案：(一)委員馬文君","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/28/LCIDC01_1152801.pdf","pages":"371-464","target":["環境部部長彭啓明","經濟部能源署"],"title":"綠色採購納庇護工廠，光電回收不能虧納稅錢","topics":["庇護工廠","綠色採購","太陽光電回收","循環經濟"],"summary":"他關心庇護工廠被淨零轉型邊緣化，發現綠色採購和弱勢優先採購各做各的、沒有整合，庇護工廠想引進黑水虻或碎紙壓磚設備轉型，卻卡在設備成本。他也質疑經濟部推光電汰舊換新，把舊模組提前送進回收，環境部卻沒盤點量能；每kW處理成本1,600到2,400元，徵收只收1,000元，一直在虧。","demands":["請環境部把綠色採購和弱勢優先採購系統串接，庇護工廠產品給更高權重","請部長跨部會研議，把庇護工廠的黑水虻、碎紙作業納入資源循環體系並給輔助機制","請彭部長一個月內給辦公室報告，說明跨部會討論的進展","請環境部盤點2026到2030年提前汰換的光電模組回收量能","請環境部與經濟部保證汰舊換新的回收成本不由納稅錢買單"],"faults":["環境部綠色採購沒把弱勢納入，和優先採購互相獨立，增加基層行政負擔","環境部說不出提前汰換模組的回收量能，卻說已經準備好","回收處理成本每kW 1,600到2,400元，徵收只有1,000元，收支不平衡","部長說量能要到127年才起來，但115年就有提前汰換的板要處理","上一年底就說要研議提高處理費率，卻一直沒處理"],"reply":"彭啓明說綠色採購確實沒考慮庇護工廠，會照委員意見跨部會研究；現有5家業者每月可處理5,000噸，提前汰換的回收費用由業者自己負擔。","quotes":["如果你都不知道量能有多少，你怎麼可以確定你準備好了？","我要說的事情就是這個費用，你要確保不會用到全民的納稅錢"],"fixed":false,"chars":5121,"followups":[]},{"gz":"GZ-1152601_00006","date":"2026-04-01","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議一、邀請勞動部部長、衛生福利部、原住民族委員會就「穩定原住民族就業、改善低薪與勞動權益保障，並縮小職業災害發生率及死亡率差距之執行現況與精進作為」進行專題報告，並備質詢；二、邀請勞動部、衛生福利部就「開放家","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/26/LCIDC01_1152601.pdf","pages":"285-390","target":["行政院","保訓會","勞動部長洪申翰","職安署"],"title":"從霸凌案追制度失靈：通報不敢實名、職災資訊查不到","topics":["職場霸凌","公務人員申訴","工安職災","資訊公開"],"summary":"廖偉翔從顏慧欣案追問行政院：2月19日辭職信已送進院長室，卻到3月24日媒體揭露、3月26日才啟動調查。他再推到制度面，質疑保訓會霸凌調查表逾期未收齊，通報平臺要實名、窗口看得到申訴人，基層不敢申訴。工安上，他指高雄同一工地兩年內4起事故、2人死亡，重大職災公開網卻查不到。","demands":["保訓會催回未繳的部會與地方政府霸凌調查資料，並追蹤到底","保訓會把申訴數、結案數、處分件數給辦公室，去識別化後定期公布","保訓會檢討通報平臺實名疑慮，提出保密或匿名的具體方案","勞動部督導高雄市勞檢處有無落實停工復工要點與減災計畫","勞動部會後給辦公室書面報告，說明資訊為何查不到"],"faults":["行政院2月19日就知道辭職信，拖到3月26日媒體揭露後才啟動調查","保訓會訂3月31日截止的霸凌調查表，到4月1日仍有機關未繳","通報平臺要實名，窗口看得到申訴人與被申訴人，基層不敢通報","重大職災公開網查不到這個工地的4起案件，資訊揭露失靈","1月11日天降鐵板後兩天就復工，3月24日再度砸死工人"],"reply":"行政院稱3月26日看到揭露才知情、隨即組專案小組；保訓會說申訴平臺建置中、依規須具名；洪申翰表示會重點關注並與地方政府加強督導。","quotes":["我去你們重大職災公開網查詢，結果發現一筆資料都沒有啊","從這個個案就凸顯出整個行政的失靈"],"fixed":false,"chars":9878,"followups":[]},{"gz":"GZ-1152301_00006","date":"2026-03-26","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議邀請衛生福利部部長及勞動部部長就「在職照顧者支持體系是否完善、長照3.0服務輸送與長照安排假評估」進行專題報告，並備質詢（115年3月25日、115年3月26日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/23/LCIDC01_1152301.pdf","pages":"313-394","target":["衛生福利部部長石崇良","勞動部部長洪申翰"],"title":"長照給付9年沒全面調整，裁罰平臺形同虛設","topics":["長照","照服員待遇","裁罰資訊透明","核能人才培訓"],"summary":"廖偉翔關心長照人力與服務品質。他說長照給付標準上路9年沒全面調整，物價漲了、照服員待遇卻沒跟上，要求依物價指數每兩年檢討一次。他也當場點開衛福部裁罰平臺，發現連結亂跳、屏東裁罰被寫成0件，臺南詐領5,400萬的廠商也沒公告，主張資訊透明是中央的督導責任，要限期補上漏洞。","demands":["衛福部：長照給付依物價指數每兩年檢討調整，一個月內提出時間表","衛福部：建立照服員分級與進修機制，鼓勵新人並留住資深人員","衛福部：一個月內上線可搜尋的全國裁罰平臺，三個月內建跨縣市預警通報","衛福部：本會期前提出長照稽核人力補足方案","勞動部：主動規劃核能級技術培訓與人才缺口補足，不要只被動配合"],"faults":["長照給付標準上路9年沒全面調整，照服員待遇沒跟著物價提升","衛福部裁罰平臺只掛地方連結，臺東點進去是新聞頁，不是裁罰網頁","高雄裁罰頁只有5筆，其中3筆是食安案件，長照相關只有2件","屏東近4年裁罰17件、2件、2件、7件，平臺上卻顯示0件","臺南詐領5,400萬與高雄AB班表詐領案，平臺完全沒有公告"],"reply":"石崇良就長照給付檢討機制與照服員分級答應研議，並說時間表「那就一個月」；裁罰平臺部分，他說今年年底之前完成系統開發、未來開發系統時會有標準格式，資訊揭露的部分會檢討改善。司長祝健芳說會要求地方政府更新連結。洪申翰說要看目的事業主管機關的需求，願意一起討論。","quotes":["裁罰是地方的權責，但是資訊透明是你的督導責任。","這顯示衛福部在資訊治理的能力是有待加強"],"fixed":true,"chars":7721,"followups":[]},{"gz":"GZ-1152102_00004","date":"2026-03-19","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議一、審查行政院函請審議「國民年金法部分條文修正草案」案；二、繼續審查(一)委員何欣純等17人擬具「國民年金法第五十四條之一及第五十五條條文修正草案」案、(二)委員邱鎮軍等17人擬具「國民年金法第十五條及第五","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/21/LCIDC01_1152102.pdf","pages":"237-342","target":["行政院"],"title":"國民年金三改：調高給付、放寬排富、刪配偶連帶罰","topics":["國民年金","年金給付","排富門檻","配偶連帶處罰"],"summary":"廖偉翔關心國民年金給付跟不上物價。他指出制度上路17年，給付四年才調一次，弱勢族群購買力嚴重縮水；長者只因土地公告現值調升就失去資格；被保險人沒繳費沒事，配偶反而要受罰。他主張老年年金調到8,000元、身障年金1萬2,000元、改成一年一調，排富門檻放寬，並刪掉配偶連帶處罰。","demands":["修第五十四條之一，老年年金給付基準調升至8,000元","身障年金保障至1萬2,000元，調整頻率縮短為一年檢討一次","修第三十一條，所得額門檻提高至60萬、土地房屋提高至1,025萬","排富門檻增訂動態調整機制，隨經濟現狀與時俱進","刪除第十五條、第五十條配偶強制處罰，改為正向鼓勵"],"faults":["現行四年調整一次，跟不上物價漲幅，弱勢購買力縮水","排富門檻沒隨經濟調整，長者因公告現值調升就喪失資格","被保險人未繳費無罰則，配偶卻要受罰，形同懲罰婚姻","配偶連帶繳費規定違背民法夫妻財產分離原則","制度實施17年未全盤檢討，貧富差距從75倍擴大到150倍"],"reply":"","quotes":["配偶卻要受罰，這不僅是違背了民法夫妻財產分離的原則","現行的制度下，許多長者僅因為土地的公告現值調升"],"fixed":false,"chars":1032,"followups":[]},{"gz":"GZ-1152102_00003","date":"2026-03-18","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請衛生福利部部長、勞動部、原住民族委員會、內政部、教育部、行政院人事行政總處、銓敘部及國家衛生研究院，就「如何精進偏鄉醫療與長照資源落差及落實《原住民族健康法》之困境，並對提升原住民族健康權益及強化原鄉照","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/21/LCIDC01_1152102.pdf","pages":"141-236","target":["衛生福利部部長石崇良"],"title":"健康幣延期又疊床架屋 要求整合進健保快易通","topics":["健康幣","健康促進","App整合","虛擬健保卡"],"summary":"廖偉翔追問健康幣細節。健康幣沒有基金、公務預算只做平台，合作商家和財務結構還在洽談，原本承諾4月上線確定延後。他指出篩檢換點只停在第二段第三級，應該往前做到第一級健康促進，並和運動幣、文化幣串聯讓幣能通用。他主張別再開新app，整合進健保快易通，也要檢討虛擬健保卡OTP驗證流程。","demands":["衛福部把健康幣往前拉到第一級健康促進，納入運動與生活型態","健康幣要能和運動幣、文化幣及地方政府的幣互通","健康幣別再開新app，直接整合進健保快易通","重新檢視健康存摺個資疑慮，思考哪些資料絕對不外傳","檢討虛擬健保卡OTP驗證流程，並提供辦公室書面報告"],"faults":["衛福部承諾健康幣4月上線，現在確定延後","合作商家、每年預算和財務結構都還停在洽談階段","健習生已下架，之前只有500人下載，推廣成效不佳","健康幣分散在健康存摺和Health Go，民眾要裝多個app","健保快易通OTP驗證還要另開瀏覽器，操作繁瑣"],"reply":"石崇良說公務預算只做平台維護、沒有基金，正與超商洽談；配合政院整合方案上線會延後，願朝通用性最大化，並請健保署研究虛擬健保卡驗證能否簡化。","quotes":["你們曾經承諾4月要如期上線","你是不是應該儘量整合到現在已經有最多人的地方？"],"fixed":false,"chars":4876,"followups":[]},{"gz":"GZ-1151501_00004","date":"2026-01-29","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第22次會議邀請衛生福利部就「春節急診醫療人力調度與跨院協調機制之現況與精進作為」暨「假日及連續假期急重症分級醫療政策之執行成效與改進方向」進行專題報告，並備質詢；審查一、委員何欣純等17人擬具「國民年金法第五十四條","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/15/LCIDC01_1151501.pdf","pages":"127-230","target":["衛生福利部","衛生福利部長石崇良"],"title":"醫師加班費免稅要定案，急診App更新別拖30分鐘","topics":["醫師加班費免稅","急診壅塞","WHO國際參與","傳染病監測"],"summary":"廖偉翔追問醫師加班費免稅何時定案，要部長過年前發函。他也關心美國退出WHO後的處境，主張兩邊平台都要爭取參與。他點出赴美人才把球黴菌症帶回來，2021年前只有一例、最近兩年多12例，要求加強監測與宣導。最後質疑春節急診App沒做壓力測試，資訊30分鐘才更新太慢，應縮到10分鐘內。","demands":["衛福部過年前發函，讓醫師加班費免稅定案","持續爭取實質參與WHO，美國若另組平台也要爭取加入","對赴美高風險地區返臺人才，建立通報SOP並加強宣導","急診資訊系統要做壓力測試，承諾不當機、不延遲","急診資訊更新從30分鐘縮短到10分鐘內"],"faults":["醫師加班費免稅追蹤很久，上次說今年可用卻還沒定案","球黴菌症最近兩年多12例，衛福部只講監測、缺邊境管控方案","衛福部沒說清楚基層診所快篩、診斷試劑夠不夠","急診資訊指標還在手動上傳，更新要30分鐘才一次"],"reply":"石崇良允諾過年前發函處理免稅，並會爭取參與WHO及美國新平台；劉越萍說指標仍手動、標準化後可10分鐘內更新。","quotes":["我們今天在講急診的血汗醫護，農曆年前給大家一個小紅包吧","你們可不可以承諾到時候這個app是不會當機、不會延遲"],"fixed":false,"chars":3750,"followups":[]},{"gz":"GZ-1151403_00002","date":"2026-01-22","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第21次會議一、繼續審查：(一)行政院函請審議「身心障礙者權益保障法部分條文修正草案」案、(二)委員范雲等17人擬具「身心障礙者權益保障法部分條文修正草案」案、(三)委員郭昱晴等19人擬具「身心障礙者權益保障法第十六","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/14/LCIDC01_1151403.pdf","pages":"295-502","target":["署長周道君","內政部","交通部"],"title":"通用設計光有計畫沒用　要求法條明定編列預算","topics":["身心障礙者權益","通用設計","無障礙環境","預算編列"],"summary":"審查身心障礙者權益保障法時，廖偉翔支持第五十二條之一加上各級主管機關要訂通用設計推廣及實施計畫、並編列預算支應。他說條文沒有罰則，若不寫預算就只剩訓示規定。他在第一線看到機關有了規範卻沒錢改善，要很用力爭取還拖兩、三年，因此要求至少做出附帶決議儘速推廣。","demands":["支持第五十二條之一加訂通用設計推廣及實施計畫並編列預算支應","要求行政部門說明是否加上編列相關預算的文字","請署長提附帶決議，要求儘速推廣通用設計並協助機關編經費","個人助理制度入法的相關條文先保留，再討論或直接送出委員會"],"faults":["條文沒有相對罰則，若不明定預算恐淪為訓示規定","機關只寫計畫不做修正，實際上無法落實通用設計","很多機關沒被編預算改善，要用力爭取還拖兩、三年","老舊機關環境如學校電梯、地下停車場改善經費難籌措"],"reply":"署長周道君說通用設計多整合在既有計畫，不一定單獨編列預算，建議文字保留彈性，願改以附帶決議要求各機關訂推廣獎勵措施。","quotes":["有預算才有可能真正的落實","沒有足夠的、沒有被編列預算去改善這件事，都要很用力去爭取"],"fixed":false,"chars":3966,"followups":[]},{"gz":"GZ-1151403_00001","date":"2026-01-21","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第21次會議一、繼續審查：(一)行政院函請審議「身心障礙者權益保障法部分條文修正草案」案、(二)委員范雲等17人擬具「身心障礙者權益保障法部分條文修正草案」案、(三)委員郭昱晴等19人擬具「身心障礙者權益保障法第十六","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/14/LCIDC01_1151403.pdf","pages":"1-294","target":["行政院"],"title":"身權法修法接軌CRPD 合理調整與司法事務入法","topics":["身心障礙者權益保障法","反歧視","合理調整","人口普查"],"summary":"廖偉翔審查身權法修正草案時，肯定行政部門採納原住民身心障礙者、支持人力、長期照顧等意見，但主張時程應改為三年。現行反歧視條文不足，沒明定拒絕合理調整就是歧視，也沒納入司法事務。他要求參酌CRPD第二條、第九條、第十三條，把合理調整與無障礙定義入法，新政策也應先做身心障礙影響評估。","demands":["要求行政部門把時程改為三年，質疑調查是否真需要5年","行政院每五年辦全國人口普查，應納入身心障礙者人口調查","新政策推動前應先經身心障礙影響評估，通過後才能實施","參酌CRPD第二條修正第一項，明定反歧視適用對象與行為樣態","依CRPD第十三條把司法事務列為須辦理合理調整的權益事項"],"faults":["現行身權法沒有明確規定拒絕合理調整就是歧視","行政院版合理調整只寫在第二項，適用範圍太窄","院版第三項列舉事項沒有包含司法事務","現行第二項無障礙規範內容不足，未明定無障礙定義","政府只發指引，沒提供資源協助提供方克服阻礙"],"reply":"","quotes":["可是是不是真的需要到 5 年？","而不是只有發布指引說必須要怎麼做或應該怎麼做而已"],"fixed":false,"chars":1777,"followups":[]},{"gz":"GZ-1151102_00003","date":"2026-01-19","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第20次會議一、審查(一)行政院函請審議「藥事法部分條文修正草案」案、(二)委員羅廷瑋等20人擬具「藥事法第五十五條條文修正草案」案、(三)委員羅廷瑋等17人擬具「藥事法第二十七條之二、第四十八條之二及第九十六條之一","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/11/LCIDC01_1151102.pdf","pages":"157-306","target":["衛生福利部次長林靜儀","食品藥物管理署署長姜至剛"],"title":"ADHD用藥告知不足　安置兒少口腔照護應主動納入","topics":["ADHD用藥","醫病共享決策","兒童口腔醫療","安置機構兒少"],"summary":"廖偉翔問食藥署仿單電子化成效，指出資訊看得到不等於看得懂。他擔心學校把篩檢工具誤用為診斷依據，孩子還沒查清原因就被送醫用藥，而利他能、專思達都是三級管制藥品，仿單載明曾有自殺念頭的不良反應通報。他也點出114年兒童醫療優化政策漏掉安置機構的弱勢童，要求主動納入並加強醫病共享決策。","demands":["衛福部提出ADHD診斷與用藥的檢討書面報告，說明精進作為與問題","把兒童ADHD的診斷與治療列為醫病共享決策優先推動項目","醫師開藥前應與家長、老師充分討論，並說清楚藥品重大副作用","社家署與口腔健康司加強橫向聯繫，主動把安置機構兒少納入專案","口腔親善之家相關報告兩個禮拜內送到辦公室"],"faults":["食藥署仿單電子化目前只有約250個藥品，還沒有很普及","兒童醫療優化政策漏掉受虐兒少、安置機構的弱勢童","政策預設有家長帶孩子就醫，安置機構兒童等於被排在外面","衛福部與地方社政橫向聯繫不清，第一線醫師找不到這些孩子","所謂高風險的定義與定位不清楚，第一線無所適從"],"reply":"食藥署說仿單先做結構化，預計今年年底完成。次長說尊重兒心醫師診斷，會與社政單位溝通，並把現有方案與ADHD相關資訊提供給委員。","quotes":["這個東西既然是你們的責任，你們要去聯繫吧","將兒童 ADHD 的診斷跟治療列為醫病共享決策的優先推動項目之一"],"fixed":false,"chars":4683,"followups":[]},{"gz":"GZ-1151201_00003","date":"2026-01-19","committee":"社會福利及衛生環境委員會","agenda":"司法及法制、社會福利及衛生環境委員會第2次聯席會議一、繼續併案審查(一)行政院函請審議「衛生福利部組織法第二條、第五條及第八條條文修正草案」案、(二)委員何欣純等19人擬具「衛生福利部組織法第二條條文修正草案」案、(三)委員林月琴等20人擬","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/12/LCIDC01_1151201.pdf","pages":"85-346","target":["衛生福利部"],"title":"兒家署別只做業務整併　要當政策創新引擎","topics":["兒少政策","衛福部組織法","兒家署","跨域治理"],"summary":"衛福部組織法修正，把12年前裁撤的兒童局重新納入體制，設立兒少及家庭支持署。廖偉翔擔心兒家署定位在三級機關，跨部會、跨體系整合做不起來，政策各自為政、資源零碎分散。他主張兒家署要以跨域治理為核心，串聯醫療、社福、教育與司法，並講清楚人力與預算，訂出兒少預算的成長目標與期程。","demands":["衛福部：兒家署要建立制度化橫向協調機制，串聯醫療、社福、教育與司法","衛福部：說明兒家署正式編制人力與年度預算規模","衛福部：訂出兒少預算占中央政府總預算與GDP比例的成長目標與期程","衛福部：醫療與社福整合的預算和人員要到位，落實早期介入與預防","衛福部：青少年政策涵蓋身心健康、風險行為預防與社會參與","衛福部：家庭支持與育兒支持要回應不同生命階段與多元家庭型態，提供連續且可近的支持服務"],"faults":["衛福部：兒家署定位為三級機關，跨部會、跨體系整合功能能否發揮有疑慮","衛福部：組織成立不等於治理轉型，難回應少子化與兒少結構性挑戰","衛福部：政策容易各自為政，資源零碎分散","衛福部：兒家署恐淪為既有業務整併，缺少政策創新"],"reply":"","quotes":["建立制度化的橫向協調機制，實質的串聯醫療、社福、教育與司法體系","在醫療與社福的整合上，相關的預算當然也必須要足夠和到位"],"fixed":true,"chars":791,"followups":[]},{"gz":"GZ-1150201_00003","date":"2025-12-15","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第16次會議邀請環境部部長、衛生福利部、經濟部、農業部、交通部、國防部及內政部國土管理署就「全臺垃圾山危機與事業廢棄物去化」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/115/02/LCIDC01_1150201.pdf","pages":"133-230","target":["環境部部長彭啓明","環境部化學署","國防部軍備局","交通部"],"title":"垃圾山清除進度落後 高爆炸藥採購把關不足","topics":["垃圾山","事業廢棄物","RDX炸藥採購","化學物質列管"],"summary":"廖偉翔關心垃圾山清理與高爆炸藥採購的公共安全。他指出竹東垃圾山今年5月號稱清完，實際只是縮水，污水仍滲入頭前溪流域；監控平臺寫115年6月歸零，實際進度只有百分之二十七點多，全國還剩60萬噸。他也質疑國防部RDX標案只要求國際貿易業資格，讓室內裝修公司得標，環境部又未把RDX列管。","demands":["請環境部信守承諾，垃圾山依平臺目標明年6月歸零","請環境部催行政院，廢棄物修法最晚1月初送出","國防部高風險巨額採購應訂危險品運輸實績、防爆倉儲資格","請環境部長跨部會溝通，把RDX納入監控與洩漏通報配套","儲存RDX的兵工廠周邊應做地下水與土壤背景值調查"],"faults":["環境部：竹東垃圾山5月號稱清理完畢，現場仍有垃圾未清完","環境部：平臺目標115年6月歸零，實際進度僅百分之二十七點多","國防部：標案只要求國際貿易業資格，讓室內裝修公司得標","國防部：審標未查廠商危險品運輸實績與防爆倉儲資格","環境部：RDX未列管、未申報，運輸過程沒有通報機制"],"reply":"彭啓明說原訂年底剩40萬噸，因天災增為六十多萬噸，仍有信心完成；修法最晚1月初送出；RDX部分會研議並了解美國環保署作法。","quotes":["我想問的是，所以現場不是完全沒有垃圾，還是有垃圾的。","還是國防部覺得看到貨送到就好，過程中的公共安全風險全由全民負擔？"],"fixed":false,"chars":6546,"followups":[]},{"gz":"GZ-11410603_00001","date":"2025-12-10","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第15次會議一、邀請衛生福利部部長、勞動部及教育部就「身心障礙者特教融合、就業服務及自立生活現況」進行專題報告，並備質詢；二、繼續審查(一)委員范雲等17人擬具「身心障礙者權益保障法部分條文修正草案」案、(二)委員郭","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/106/LCIDC01_11410603.pdf","pages":"1-418","target":["衛生福利部部長石崇良","勞動部","教育部"],"title":"行政院版身權法遲未送進立法院　要求合理調整入法","topics":["身心障礙者權益保障法","個人助理","身障就業","合理調整"],"summary":"他審身心障礙者權益保障法，指出委員版本大概有21個，卻不見行政院版本，上屆111年底之後也沒再排審。他點出身心障礙者勞動參與率只有21.9%、失業率7.1%，每月主要工作收入平均約3.1萬，32.5%低於基本工資。主張個人助理與合理調整入法，重度以上障礙者55歲可提前退休。","demands":["要衛福部盡快把行政院版身權法草案送進立法院，並排定逐條審查","要衛福部、勞動部把合理調整入法，並研議對拒絕調整雇主的罰則","要勞動部兩個禮拜內提出提高身障勞參率、轉全職的政策工具給辦公室","主張重度及極重度身心障礙者年滿55歲可以提前退休","要衛福部一個月內提報方案，讓長期治療的孩子不中斷學習"],"faults":["衛福部拖延，委員版本大概有21個，就是不見行政院版本","身權法上屆111年底以後沒再排審，最終無疾而終","勞動部就業調查不夠詳盡，沒細分工作配置不公平是什麼樣態","勞動部7月1日公布的職場合理調整行政指導沒有強制性","衛福部與教育部互推，長期治療學童的就學銜接沒人接手"],"reply":"部長說行政院版本這個月底或下個月初送到立法院，支持合理調整入法、罰則較保守；教育部允諾找學者專家研議檢查表；部長承諾一個月提出報告。","quotes":["支持擴大自立生活其實不僅是人權問題","我要回過頭來說你的調查就是不夠詳盡"],"fixed":false,"chars":4893,"followups":[]},{"gz":"GZ-11410101_00005","date":"2025-11-26","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第13次會議一、邀請衛生福利部部長、財政部及環境部就「蘇丹紅化學原料竄臺，政府如何強化進口把關及後市場查驗，以維護國人健康安全」進行專題報告，並備質詢；二、邀請衛生福利部部長、司法院、法務部、勞動部及內政部警政署就「","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/101/LCIDC01_11410101.pdf","pages":"221-314","target":["衛生福利部部長石崇良","司法院"],"title":"護理執業率不升反降　要求修法加重醫療暴力刑責","topics":["護理人力","三班護病比","醫療暴力","修法加重刑責"],"summary":"他質疑護理留才成效：三班護病比上路後，扣除65歲以上的執業率反而從62.72%掉到62.36%，新進護理師首年離職率高達30到35%，要求衛福部做系統性調查。醫療暴力去年443件創十一年新高，判決刑期中位數僅兩個月，他主張修法提到六個月以上，急診醫院不分規模都要設24小時保全。","demands":["要求衛福部對護理師首年離職率做系統性調查，找出真正原因。","要求衛福部回應護理全聯會四項訴求：合理薪資、培訓補助、臨床護理專家、久任獎金。","提案修法，醫療暴力刑期至少六個月以上。","修正醫療機構設置標準，開放急診的醫院不分規模都設24小時保全或駐衛警。","評估在健保卡註記醫療暴力紀錄者，參考英國、澳洲、美國作法。"],"faults":["衛福部推三班護病比後，執業率反而從62.72%掉到62.36%。","衛福部沒做過首年離職率偏高的系統性調查，部長當場承認沒有。","衛福部現行只要求百床以上醫院設24小時保全，九十九床以下不在內。","醫療暴力兩度修法加重刑度，案件仍未下降，去年443件創十一年新高。","司法院判決刑期中位數只有兩個月，罰鍰只有3到5萬，嚇阻力不足。"],"reply":"部長石崇良說今年10月護理人力較去年同期增加約4,900位，但還不滿意；同意做系統性調查，久任獎金可用護病比獎勵支應，健保卡註記再研究。","quotes":["你們應該要去做系統性的調查，才能知道","是不是都應該要設置24小時的保全或駐衛警？"],"fixed":false,"chars":4516,"followups":[]},{"gz":"GZ-11410004_00005","date":"2025-11-24","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第12次會議一、邀請環境部部長列席報告業務概況，並備質詢；二、邀請環境部部長就「聯合國第30屆氣候峰會之後台灣氣候治理方向與如何提升台灣『氣候變遷績效指標』名次，落實2050淨零排放路徑策略」進行專題報告，並備質詢【","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/100/LCIDC01_11410004.pdf","pages":"113-194","target":["環境部","部長彭啓明","署長顏旭明"],"title":"垃圾暫置場失火，要求管理前置與有毒物質檢測","topics":["廢棄物暫置場","火災管理","有毒物質檢測","光電環評"],"summary":"臺南後壁烏樹林廢棄物暫置場起火，質詢當下還在悶燒。廖偉翔說這不是單一事件，是結構性的制度問題：2019到2023年全國49處暫置場五年發生72起火災，仁德掩埋場火災只罰5,000元，去年答應的移動式滅火水塔也沒進度。他要求暫置場一設立就同步管理，火災時要檢測戴奧辛等有毒物質。","demands":["要求環境部在暫置場設立當下就同步做好管理，不要等出事才補","要求環境部檢測戴奧辛、呋喃、氯化氫，不能只公布PM2.5、PM10","要求環境部說清楚災後廢棄物何時清完，別讓短期暫置變永久暫置","要求署長把月世界這類觀光景點納入全國2,000點智慧圍籬布建","要求環境部尊重大院光電環評修法，報告與執行都照三讀內容"],"faults":["環境部：2019到2023年全國49處暫置場，五年發生72起火災","環境部：臺南仁德掩埋場火災只依空污法罰5,000元，不痛不癢","環境部：去年備詢答應增設移動式滅火水塔，至今沒有新進度","環境部：新設暫置場當時沒要求做管理，流程和管理都有疏忽","環境部：今天委員會發的報告第18頁，內容和大院修過的法不一樣"],"reply":"部長說火已停仍有悶燒，火因待消防鑑定，會遵照大院修法；署長說12月起減量外運，可加紅外線感應，2,000點智慧圍籬會涵蓋月世界。","quotes":["我要講的事情是結構性、系統性在管理上面、制度上面，到底要怎麼精進？","應該是要要求暫置的時候就要趕快把相關的管理放上去"],"fixed":false,"chars":4450,"followups":[]},{"gz":"GZ-1149801_00001","date":"2025-11-17","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第11次會議一、審查(一)委員黃健豪等16人擬具「勞工保險條例第六十三條條文修正草案」案、(二)委員陳瑩等19人擬具「勞工保險條例第五十八條條文修正草案」案、(三)委員許宇甄等19人擬具「勞工保險條例第六十六條及第六","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/98/LCIDC01_1149801.pdf","pages":"1-86","target":["勞動部長洪申翰","勞動力發展署署長黃齡玉"],"title":"懷孕歧視罰兩萬不痛不癢 青年訓練成效只有五成","topics":["懷孕歧視","友善職場","青年就業","家事移工"],"summary":"新北一名劉姓女子與6個月大孩子遭丈夫殺害的滅門悲劇，廖偉翔指出她懷孕時被雇主以不適任資遣、求職處處碰壁。他說懷孕歧視的違法裁罰遍布全臺，有醫院只罰兩萬塊，不痛不癢。他也質疑青年職前訓練訓後三個月全職就業僅五成，青職中心指標寬鬆、服務對象與學校重疊，並要求家事移工政策評估完再推出。","demands":["要勞動部兩個禮拜內提懷孕歧視的具體精進作為給辦公室","青職中心產出型指標要改成成果型指標，實質評估就業成效","重新界定青職中心優先服務對象，別與在學青年高度重複","職涯諮詢人力流動與經驗傳承，兩個禮拜內給檢討報告","家事移工政策要務實評估完再推出，不要像試水溫"],"faults":["懷孕歧視裁罰太輕，有醫院案例只罰兩萬塊，不痛不癢","投資青年就業方案第二期成效看不到，失業率曲線都是平的","職前訓練訓後三個月全職就業比率僅五成，落後旗艦計畫逾九成","監察院指青職中心目標值寬鬆，達成率破千，形同虛假KPI","青職中心服務對象與大專院校學生輔導中心高度重疊"],"reply":"洪申翰說會落實裁罰並與地方討論金額，加強懷孕歧視宣導、與法扶團體合作，違法事業單位專案揭露，11月底提計畫；青職資源可再向弱勢青年傾斜。","quotes":["我們到底要怎麼樣讓雇主在看到孕婦跟懷孕員工的時候，是看到寶，不是看到鬼","相關評估要很務實的做完之後再推出這個政策"],"fixed":false,"chars":5413,"followups":[]},{"gz":"GZ-1149601_00003","date":"2025-11-13","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第10次會議一、邀請衛生福利部部長及行政院主計總處就「癌症新藥暫時性支付及罕見疾病藥物專款預算運用成效及政策檢討」進行專題報告，並備質詢；二、審查(一)委員羅廷瑋等16人擬具「癌症防治法第十三條及第十六條條文修正草案","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/96/LCIDC01_1149601.pdf","pages":"125-214","target":["衛生福利部部長石崇良","署長陳亮妤"],"title":"攝護腺癌篩檢延遲近30年，百億癌症基金別再拖","topics":["癌症篩檢","罕見疾病藥物","百億癌症新藥基金","健保給付"],"summary":"廖偉翔指出攝護腺癌個案從2022年9,062人增到2024年9,858人，發生率是子宮頸癌的5.5倍，卻到現在都沒納入公費篩檢，比子宮頸抹片晚近30年。他也質疑115年罕藥專款推估改變，比需求少18億，衝擊1萬7,627位罕病家庭；百億癌症基金遲遲湊不到百億，要求儘速達標。","demands":["要求衛福部加速訂出攝護腺癌篩檢的國家政策，半年內給時間表","要求即使工具不夠精準，數值異常者也要促成進一步檢查","要求健保署把改公式的計算方式向罕病基金會說清楚並提供說明","要求罕藥公務預算20億確實補進去","要求部長儘速讓癌症新藥基金達到百億水準，不要一直延後"],"faults":["衛福部至今未把攝護腺癌納入公費篩檢，比子宮頸抹片晚近30年","健保署改以醫令推估罕藥專款，與基金會認知落差達18億","罕藥專款只編136億，與153.97億的需求推估有明顯短缺","百億癌症基金分年編列，先50億再爭取50億，形同先畫大餅"],"reply":"石崇良說攝護腺癌國家政策正委託學者評估，約半年提出；罕藥推估已納入等候中藥品，另編20億公務預算；癌症基金明年約70億、後年達百億。","quotes":["攝護腺癌篩檢到現在都沒有納入全民篩檢","所以是先畫一個大餅說我們會到百億，但是時間就是後面再來推這樣子。"],"fixed":true,"chars":3845,"followups":[]},{"gz":"GZ-1149501_00003","date":"2025-11-12","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議邀請勞動部部長列席報告業務概況，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/95/LCIDC01_1149501.pdf","pages":"131-236","target":["勞動部","勞動部長洪申翰"],"title":"追外送專法最低報酬 要勞動部拿出成本數據","topics":["外送平台專法","勞保財務","跨國勞動力精進方案","最低報酬"],"summary":"廖偉翔追勞保由政府負最終支付責任入法，要部長把五月承諾的研議結果講清楚。再追外送平台專法：他自己算外送員一年成本約11萬、每小時五、六十塊，平台每單約300塊，卻有外送員20分鐘送3單只拿45塊。他要專法儘快預告、最低報酬方向講明白，並說明精進方案怎麼防假加薪。","demands":["勞動部對勞保最終支付責任入法要講更明確，並配合往前推進","勞動部外送平台專法版本，最晚不超過下個禮拜五預告","勞動部本週提供外送員成本與平台每單金額等數據給辦公室","勞動部去了解紐約模式的外送員時薪保障做法","勞動部提供精進方案背後數據：各產業缺多少工、受惠多少人"],"faults":["勞動部對入法的說法，跟五月講的差不多，不夠明確","外送專法已到最後階段，勞動部仍講不出最低報酬要走哪個方向","部長談四方平衡只給大方向指引，比較空泛、缺細節","平台向店家抽30%到35%，外送員被夾單20分鐘送3單只拿45塊","民團質疑勞動部沒有全面詳細盤點，拿不出具體數字"],"reply":"洪申翰說最終責任是明確政策立場、法制化不反對；外送專法這一、兩週預告，最低報酬仍在評估；假加薪會用勞保資料查核、撤銷名額。","quotes":["所以部長不反對入法？如果委員會有排，您也算是不反對、就會支持？","其實一年下來，他的所有費用大約是 11 萬左右"],"fixed":false,"chars":5771,"followups":[]},{"gz":"GZ-1149201_00003","date":"2025-11-05","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第8次會議一、邀請環境部部長、經濟部、內政部、農業部、交通部、行政院公共工程委員會就「非法棄置到城市採礦：檢討環境部環境管理署執法痛點與城市採礦推動策略」進行專題報告，並備質詢；二、繼續審查(一)委員賴瑞隆等16人擬","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/92/LCIDC01_1149201.pdf","pages":"211-324","target":["環境部部長彭啓明","署長顏旭明","署長賴瑩瑩"],"title":"廚餘養豬漏傳、非法棄置罰太輕，要求學日本統一管理","topics":["廚餘養豬","非法棄置","城市採礦","裁罰標準"],"summary":"廖偉翔盯廚餘養豬與非法棄置。全國廚餘養豬場百分之百上傳只有151家，284家曾漏傳、占65.3%，一次沒蒸煮就可能爆發豬瘟；廚餘轉到別家豬場誰管、用什麼法罰，兩部會推來推去。他要求學日本統一集中處理，並加重裁罰：美濃大峽谷罰1,430萬，業者不到10萬元交保。","demands":["請環境部儘速評估統一集中處理廚餘要多久，把時程提供給辦公室","請環境部找行政院推動廚餘中長程規劃和相關預算","要求這次修法精進申報不實等裁罰標準，追回不法所得","請環管署說明強化全國廢棄物流向遠端數位管理智慧決策計畫有沒有行政院核定文號，為什麼明年預算書裡沒有這個計畫","請環境部把城市採礦的戰略評估與回收技術細節提供給辦公室"],"faults":["全國廚餘養豬場百分之百上傳只有151家，284家曾漏傳、占65.3%","廚餘轉給別家豬場誰管、用什麼法罰，環境部農業部推來推去答不出來","環管署把112年到117年的智慧執法計畫報請終止，明年預算裡看不到","美濃大峽谷罰1,430萬、業者不到10萬元交保，申報不實只罰6,000元","每年銷售540萬支手機，回收率只有5.2%，城市採礦報告仍空泛"],"reply":"彭啓明說中長程規劃還在跨部會研議、尚未定案，廚餘每天還缺500噸去化；法的部分會精進，不法所得一定要追回。","quotes":["殺頭的生意有人做，賠錢生意沒人做，現在的罰則跟不法獲利，你不覺得相差很大嗎","現在的美麗寶島已經被許多的非法棄置集團變成垃圾島，我覺得環境部也難辭其咎"],"fixed":true,"chars":5250,"followups":[]},{"gz":"GZ-1149002_00002","date":"2025-10-30","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議一、邀請衛生福利部部長、農業部、財政部、交通部、經濟部、數位發展部、海洋委員會海巡署就「如何精進海外小型包裹夾帶肉品之查緝與防堵，持續強化阻絕疫情於國門，同時優化國內後續對於非洲豬瘟防疫」提出專題報告，並備","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/90/LCIDC01_1149002.pdf","pages":"373-486","target":["衛生福利部部長石崇良","關務署","防檢署署長杜麗華","食藥署署長姜至剛","經濟部","數位發展部"],"title":"郵包夾帶肉品千件只罰九件，要求堵住免罰漏洞","topics":["非洲豬瘟","境外包裹","邊境查驗","電商平台"],"summary":"廖偉翔關心境外小包裹成為非洲豬瘟破口。關務署說郵包、快遞100% X光查驗，他推估10月24到26日三天人工開箱逾4,000件只查獲4件、6.7公斤，以2024年進口包裹5,847萬件計算，漏網恐有8萬件。他也指郵包查獲肉製品約1,000件只開罰9件，要求檢討首次非故意免罰。","demands":["衛福部年底前完成醫師加班費免稅，明年報稅適用，並送進度給辦公室","關務署精進查驗流程，在既有資源與科技應用下把查驗做得更嚴格","防檢署檢討首次非故意免罰，要電商平台勸阻並處罰違規商家","食藥署勾稽個人自用輸入，設進口頻率上限與總量管制","經濟部、數發部說明電商平台落地與強制下架的具體做法"],"faults":["關務署稱100% X光查驗，仍有物流業者說肉品大量流入","三天人工開箱逾4,000件只查獲4件，推估漏網恐達8萬件","防檢署郵包查獲約1,000件只開罰9件，只有千分之九","實名制上路後違規降低多少，現場答不出明確數字","先罰淘寶120萬限期撤資，現在又要它落地，政策初一十五不一樣"],"reply":"石崇良說加班免稅盼年底前完成；關務署稱100% X光、再提高開箱比率；防檢署稱已改實名制、正檢討；食藥署允積極修正個人輸入規定。","quotes":["1,000 件開罰 9 件其實是非常的低，只有千分之九","首次非故意免罰是不是可能變成一個有心人可以鑽的漏洞？"],"fixed":true,"chars":6258,"followups":[]},{"gz":"GZ-1149002_00001","date":"2025-10-29","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議一、邀請環境部部長、衛生福利部、農業部、經濟部、教育部、國防部就「防範非洲豬瘟疫情擴散，強化全國廚餘去化問題以及後續防疫、清消等作為」提出專題報告，並備質詢；二、繼續審查(一)行政院函請審議「職業安全衛生法","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/90/LCIDC01_1149002.pdf","pages":"1-372","target":["環境部部長彭啓明","農業部部長陳駿季"],"title":"廚餘養豬沒罰則　廖偉翔要環境部補上管理漏洞","topics":["非洲豬瘟","廚餘去化","廚餘養豬管理","豬肉價格"],"summary":"農業部宣布10月22日起禁止廚餘養豬，廖偉翔追問政府長期方向。他指出禁餵前每日2,115噸廚餘有62.6%進養豬體系，禁餵後仍短缺495噸；蒸煮申報系統只是輔助工具，77家申報率低於90%遍布各縣市，沒上傳卻沒罰則，形成系統性風險。他要求環境部訂罰則補漏洞，農業部提補貼穩定豬價。","demands":["環境部：沒上傳蒸煮照片要有明確罰則和強制力，並防翻拍偽造。","環境部：通盤檢視輔助管理系統漏洞，說明精進方案何時提出。","環境部：評估補助家戶、機關學校裝廚餘處理機，從源頭減量。","農業部：本週五前提出黑豬改飼料價差的完整補助方案。","農業部：做好豬肉價格透明與管理，優先供應團膳、自助餐、賣場。"],"faults":["環境部：申報系統只當輔助工具，沒上傳沒罰則，管理無法落實。","環境部：77家申報率低於90%分布全臺各縣市，卻只指向臺中市。","環境部：長期政策方向不明，共同烹煮場只有嘉義一處。","環境部：對家戶廚餘機沒有補助構想，源頭減量沒有進展。","環境部：禁餵後仍短缺495噸廚餘要靠焚化掩埋，去化配套不足。"],"reply":"彭啓明說會提出精進方案，強調重點在有沒有蒸煮；陳駿季說本週內提出豬產業完整補助方案，冷凍豬肉庫存可供應約一個月。","quotes":["他們上不上傳的一些細節都沒有辦法落實的情況之下，這會造成系統性的風險","其實每一個環節都有關係，你不能一味地只說這個是地方稽查有問題"],"fixed":false,"chars":6587,"followups":[]},{"gz":"GZ-1148801_00003","date":"2025-10-22","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議審查一、委員洪孟楷等21人擬具「外送平台管理暨從業人員權益保障法草案」案；二、台灣民眾黨黨團擬具「外送平台管理暨從業人員權益保障法草案」案；三、委員羅廷瑋等20人擬具「外送平台管理暨從業人員權益保障法草案」","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/88/LCIDC01_1148801.pdf","pages":"111-206","target":["勞動部長洪申翰"],"title":"外送專法確認勞動部主責，三個月太久要求儘速提出","topics":["外送平台專法","外送員權益","勞動關係認定","官方數據"],"summary":"審查外送平台專法草案，廖偉翔追問部長前一天總質詢只說會有指引，今天怎麼突然改口支持專法。他要部長當場講清楚主管機關，確認由勞動部承擔主責，並指行政院六年多來用權責不明推諉，害立法延宕。他追問進度，發現開過幾次會算不出來、條文還留在部裡，數據也沒掌握好。","demands":["要部長當場確認外送專法主管機關由勞動部承擔主責推動","草案不要拖到三個月，要求儘速完成並說明預告時程","會後提供外送員全職與兼職比例等官方研究數據給辦公室","明確界定平台與外送員的勞動關係，回應法院實質從屬判決","把外送員基本費用保障講清楚，回應不低於時薪三分之一的訴求"],"faults":["勞動部說上半年就開始研議，卻算不出總共開過幾次會議","條文說已到最後階段，實際還留在部裡，尚未報行政院","全職與兼職比例只答兼職約七成，其他說法不一，掌握不足","對平台宣稱時薪高達270元，勞動部說不出計算基礎","行政院六年多來以權責不明為由推諉，造成立法延宕"],"reply":"洪申翰說五、六月起研議，條文到最後階段仍在部裡，法的主管機關由勞動部承擔，希望三個月內推出，相關資料會後提供。","quotes":["三個月真的太久了，本席希望你們儘速，因為這樣，大家才可以共同一起來討論。","對，所以我要表達的是，你們掌握的數據要很精準、公開、透明。"],"fixed":false,"chars":4437,"followups":[]},{"gz":"GZ-1148601_00003","date":"2025-10-20","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第5次會議一、邀請環境部、經濟部、農業部、內政部就「太陽能光電板案場環評機制與保護區廢棄物管理之檢討」進行專題報告，並備質詢；二、審查(一)委員賴瑞隆等16人擬具「噪音管制法第二十六條及第二十八條條文修正草案」案、(","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/86/LCIDC01_1148601.pdf","pages":"129-214","target":["環境部長彭啓明","署長李君禮","經濟部"],"title":"保護區倒廢瀝青與光電板清運，要環境部一個月內給報告","topics":["保護區廢棄物","光電板回收","災後清運","跨部會協調"],"summary":"廖偉翔從垃圾車停靠區只能暫置、要照程序切入，點名高雄大坪頂保護區倒廢瀝青，高雄市府自認合法卻沒申請，等於違法亂倒，要環境部別只用地方自治打發。他接著追嘉義風災光電板序號比對不出來、流程沒有即時公開透明，並指回收基金預估收173億，遠不足397億處理成本，要兩部會提精進報告。","demands":["要環境部查高雄大坪頂保護區倒廢瀝青案，1個月內給報告","要環境部一併清查其他地方有無未申請就暫置廢棄物","要環境部、經濟部1個月內提光電板清運流程精進報告，跨部會協調","要建置公開透明平臺，即時追蹤光電板序號流向與處理狀況","要算清回收基金缺口，說明大量除役時錢不夠怎麼辦"],"faults":["環境部以地方自治為由，對大坪頂案實情不清楚","高雄市府用都計法細則放行，保護區倒廢瀝青未經申請","光電板序號原承諾9月中提供，至今仍拿不出來","災後光電板稱清理完99%，土裡仍挖出破損板","回收基金預估收173億，不足支應397億成本，差兩百二十幾億"],"reply":"彭啓明說保護區土地不宜倒這樣的廢棄物，但屬地方自治，願花1個月了解；李君禮說毀損約12萬片正清點，未繳費者催繳，不繳移送法院。","quotes":["而且他沒有合法申請，所以也不能夠叫做暫置，等於是違法亂倒嘛","這代表現在的流程沒有即時公開透明"],"fixed":false,"chars":4638,"followups":[]},{"gz":"GZ-1148502_00001","date":"2025-10-15","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議一、邀請勞動部、交通部、衛生福利部就「長榮空勤人員因病延誤就醫，應立即檢討航空業職場健康保障飛行安全」進行專題報告，並備質詢；二、審查(一)行政院函請審議「職業安全衛生法部分條文修正草案」案、(二)委員廖先","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/85/LCIDC01_1148502.pdf","pages":"1-204","target":["勞動部長洪申翰","交通部民航局長何淑萍"],"title":"長榮企業文化該查，就安基金人事費不該暴增","topics":["職場健康","公司治理","就業安定基金","預算監督"],"summary":"廖偉翔關心長榮空服員猝逝案。他舉出一名空服員讓不適的學妹休息，反而被公司懲處，質疑是企業文化與公司治理出問題，要求民航局調查、勞動部加重裁罰。第二題問就業安定基金，勞動部說要檢討人事費，外國人聘管用人費卻從2,900萬元、4,300萬元編到6,000萬元，承諾等於沒做到。","demands":["交通部民航局要啟動調查長榮猝逝案與懲處個案","勞動部視情節加重對長榮的裁罰，不能讓它罰不怕","交通部要說清楚在公司治理上可以要求長榮什麼","勞動部依承諾把正式編制人事費回編公務預算","勞動部依當初精進作為重新檢討就安基金編列"],"faults":["長榮讓不適同事休息的空服員反遭懲處，企業文化有問題","勞動部承諾檢討人事費，外國人聘管用人費卻編到6,000萬元","促進國民就業計畫用人費從900萬元編到3,000萬元","勞動部把沒回編推給財劃法，但115年主管預算增加四十三億多","民航局要等質詢點出才說會看個案，未主動調查"],"reply":"洪申翰說會與地方勞檢討論是否加重裁罰，並要公司與工會協商；人事費依比例分擔，已爭取回編公務預算二點多億。何淑萍說會就個案調查。","quotes":["這樣的公司治理是不是出了問題？","你的精進作為和你現在編出來的預算是不一樣的"],"fixed":true,"chars":4178,"followups":[]},{"gz":"GZ-1148201_00004","date":"2025-10-13","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議邀請衛生福利部部長及行政院食品安全辦公室就「重大食安事件處理之檢討與食安稽核人力不足問題」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/82/LCIDC01_1148201.pdf","pages":"189-260","target":["衛生福利部部長石崇良","食品藥物管理署署長姜至剛","行政院食品安全辦公室主任許輔"],"title":"食安稽查人力不足　要求風險導向分配與源頭介接","topics":["食安","稽查人力","化學雲源頭管理","毒大腸事件"],"summary":"廖偉翔關注食安稽查人力不足。他指出邊境稽查人力有限，每年卻有超過76萬批進口食品要查；114年補助地方45名稽查人力，22個縣市均分等於各只增加2人。他要求人力改用風險導向分配，也質疑逾期食品偵測模組算出77家風險業者卻只查了17家。他還要求食安辦一個月內提出化學雲介接的進程。","demands":["要求食藥署稽查人力改以風險導向分配，不要22縣市均分","要求食安辦會後提供10億食安補助計畫的績效指標","要求食藥署把77家風險業者查完，並滾動檢討偵測模組","要求食安辦一個月內提出化學雲介接的後續進程","要求部長不要為配合檢調而延後該有的行政稽查"],"faults":["行政院10億食安補助計畫，報告未見稽查人力報表與績效指標","食藥署耗資近2,800萬的偵測模組，77家只查了17家","模組僅查獲8家不符GHP，同期人工查獲逾期食品違規73家","食藥署6月接獲檢舉卻未積極調查，被指是推卸責任","化學雲到113年8月底仍未克服與勞動部平台介接的欄位缺漏"],"reply":"石崇良說人力已按人口與專案件數分配、邊境導入AI，並承諾不為配合檢調延遲行政作為；許輔允諾一個月內提報進程，並研議將雙氧水納管。","quotes":["不要說你產出了 77 家，結果你自己只看了 17 家","我認為這是一個推卸責任的說法，這部分要請部長積極主動"],"fixed":false,"chars":5186,"followups":[]},{"gz":"GZ-1148201_00006","date":"2025-10-09","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請勞動部部長針對「因關稅造成我國市場就業及勞動環境衝擊之影響及因應對策」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/82/LCIDC01_1148201.pdf","pages":"361-428","target":["勞動部部長洪申翰"],"title":"關稅衝擊減班休息創高　要勞動部提出低中高推估","topics":["關稅衝擊","減班休息","青年就業","職業訓練"],"summary":"廖偉翔關心美國關稅對勞工的衝擊。他指出全國398家事業單位實施減班休息、影響8,505人，大臺中就有117家、2,598人，占30.5%，是重災區。他要求勞動部做出低、中、高三種推估，說清楚年底和明年可能的人數，但部長答不出來。他也點出小廠黑數沒被統計、僱用安定只開放9個業別、充電再出發參與率只有6%。","demands":["要勞動部做低、中、高三種推估，講清楚年底與明年可能人數","會後把樂觀與悲觀兩種推估數字送到廖偉翔辦公室","提供初次尋職青年穩定就業計畫的改善檢討報告","僱用安定業別再評估納入鋼鐵、水泥、造紙、玻璃陶瓷、化工","檢討充電再出發參與率低，評估放寬條件或提高補助額度"],"faults":["勞動部報告寫較上一期平緩，像粉飾太平，恐低估衝擊","部長花了8分鐘仍講不出年底與明年的推估數字","5到10人小廠不列入通報，減班休息統計恐失真","僱用安定只公告9個業別，傳統產業仍有不少被遺漏","青年就業計畫花超過3億，就業比率卻從67%降到52%"],"reply":"洪申翰說評估不一定是一個數字，會設想相對嚴峻情境；薪資差額補貼從五成拉到七成、可與再充電併領，業別滾動檢討。","quotes":["我覺得這的確是讓人家有一種喪事喜辦的感覺","結果很遺憾，我問了 8 分鐘，居然講不出來"],"fixed":false,"chars":7437,"followups":[]},{"gz":"GZ-1148201_00005","date":"2025-10-08","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請環境部部長、勞動部部長及衛生福利部部長針對「災後復原重建及清理因應作為」進行專題報告，並備質詢，另邀請國防部、經濟部、內政部、賑災基金會列席備詢（114年10月8日、114年10月9日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/82/LCIDC01_1148201.pdf","pages":"261-360","target":["環境部部長彭啓明","勞動部部長洪申翰","衛生福利部部長石崇良"],"title":"災後清淤估算落差大　志工安全與慰問金都要補上","topics":["災後復原重建","災害廢棄物清運","志工安全","慰問金"],"summary":"樺加沙颱風堰塞湖溢流後，光復、鳳林、萬榮泥沙滿地。廖偉翔追問環境部清運量，部長從十幾萬噸一路講到100萬噸，落差好幾倍；泥土暫置在臺九線和台糖土地，風乾後塵土飛揚。他也點出三天湧入十二萬多名志工卻沒有統一調度和教育訓練，出現熱衰竭、手指壓斷、傷口感染。他要求各部會把這次經驗寫成檢討報告，訂出清運和志工安全的SOP，讓韌性不只是口號。","demands":["環境部提出客觀的清運量估算，別十幾萬噸跳到100萬噸。","環境部訂出災害廢棄物清運SOP，並規劃暫置泥土的中長期去處。","勞動部儘速確認罹難挖土機老闆是志工或受雇，並訂志工安全指引。","衛福部儘速訂出志工職前教育訓練指引，並納入健康防護。","衛福部研議20萬元慰問金能否比照災民以專案處理。"],"faults":["環境部清運量估算從十幾萬噸跳到100萬噸，差好幾倍。","環境部把泥土暫置在臺九線、台糖土地，暫置恐變永久擱置。","志工沒有統一指揮調度和教育訓練，專業與非專業人力錯置。","勞動部事前未做足安全宣導，志工熱衰竭、手指壓斷、感染。","衛福部拍宣導影片時機太晚，事前宣導不夠充分。"],"reply":"彭啓明估約100萬噸、側溝盼10月18日通；洪申翰請職安署訂志工安全指引；石崇良說80萬元慰問金不符條件，心理支持方案本週提出。","quotes":["我們不希望看到暫置變成永久擱置在那裡","沒有客觀的估算，怎麼真正設計未來整個工作流程？"],"fixed":false,"chars":6932,"followups":[]},{"gz":"GZ-1147502_00002","date":"2025-08-20","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第25次會議一、邀請勞動部部長、衛生福利部就「就業服務法第46條，80歲以上長者聘請外籍看護免巴氏量表上路，對重症家庭的衝擊與配套措施」進行專題報告，並備質詢；二、繼續審查(一)委員王育敏等18人擬具「病人自主權利法","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/75/LCIDC01_1147502.pdf","pages":"127-220","target":["勞動部","勞動部長洪申翰"],"title":"就安基金開口契約成效差 外籍看護量能拿不出數據","topics":["就安基金","開口契約","巴氏量表","外籍看護"],"summary":"廖偉翔追問就安基金2022年到2024年補助羅景壬團隊2,872萬元，質疑媒宣用開口契約發包等於空白支票、驗收難核，成效也差，要勞動部交代誰簽准並給驗收報告。第二題談巴氏量表新制，他指到8月17日只有1,450人申請，業界推估一年2萬到3萬人，要勞動部做高中低推估並說明量能。","demands":["要勞動部查明並回報是誰簽准這件媒宣的開口契約","要勞動部把三支影片的驗收報告給廖偉翔辦公室與委員會","要勞動部就圖利疑慮請政風移送檢調進行刑事調查","要勞動部做高推估、中推估、低推估，說明能滿足哪一級","要勞動部書面說明7個月準備成果與未來一年量能"],"faults":["勞動部媒宣用開口契約，廠商不必列計畫與成效，形同空白支票","2022年單支影片補助1,069萬，按讚數只有488，成效難以交代","部長答不出誰簽准開口契約，也說不清要懲處誰","契約原訂三十五式、兩場記者會，最後只有一部影片、一場記者會","專題報告沒放申請件數，質詢時才講出1,450人"],"reply":"洪申翰說去年底已把114年開口契約廢標停下檢討，影片與活動不再納入；就安基金案檢調已立案調查，量能會全力以赴，並提供說明。","quotes":["這麼糟糕的成效為什麼可以連續三年拿到標案？","勞動部應該做好高預估、中預估、低預估"],"fixed":false,"chars":8631,"followups":[]},{"gz":"GZ-1147202_00006","date":"2025-08-14","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第24次會議邀請衛生福利部、經濟部、財政部就「美國針對進口藥品、原料藥課稅對我國產業造成影響」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/72/LCIDC01_1147202.pdf","pages":"267-328","target":["衛生福利部部長邱泰源","食藥署署長姜至剛","健保署署長石崇良"],"title":"藥品關稅衝擊評估要做足 特別預算挹注健保應再拉高","topics":["藥品關稅","缺藥風險","健保藥價","特別預算"],"summary":"川普宣布對進口藥品最高課250%關稅，廖偉翔指出臺灣2024年對美藥品出口達10億美金，要求衛福部提出全面性衝擊評估，不能只看出口。他更怕最惠國藥價政策推升藥價、造成缺藥。附帶決議挹注健保不得低於各期預算總數12%，換算654億，他認為第一期200億太少，應拉高到250億。","demands":["要求衛福部準時提出藥品關稅的全面性衝擊評估，不能只看出口","要求部長把特別預算第一期挹注健保拉高，或許250億，回去精算","要求必要藥品安全存量從6個月提高到1年，或由政府補助倉儲與行政管理費","要求部長提醒談判團隊務實面對美國藥價政策，避免國內缺藥","要求衛福部設定學名藥使用率目標，並多跟行政院爭取特別預算"],"faults":["衛福部上週承諾一週給評估報告，質詢當天仍答不出能否準時提出","部長先前說還沒發生、不一定會發生的事先不要擔心，現在看來太樂觀","部長答覆多在講周邊，像在打太極，沒說清楚缺藥與藥價的解方","今年4月26號公告的支付標準新制，遇上關稅衝擊效果很有限、幾乎沒有","健保署學名藥占率目標訂3年內70%，仍低於日本已達到的79%"],"reply":"邱泰源說先穩定國內供藥，第一期估算200億可因應，依立法院通過編列；姜至剛說修藥事法增訂缺藥調控機制；石崇良說學名藥3年內到70%。","quotes":["我覺得還是比較像是在打周邊的太極","對於這件事情希望你們可以嚴陣以對，不要用喪事喜辦的方式"],"fixed":false,"chars":5247,"followups":[]},{"gz":"GZ-1147201_00001","date":"2025-08-06","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第23次會議一、邀請衛生福利部部長、司法院、法務部、教育部、內政部警政署就「因應近期多起社會重大事件，檢討家庭暴力防治法民事保護令制度及執行缺失，強化保護令之作為」進行專題報告，並備質詢；二、(一)繼續審查行政院函請","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/72/LCIDC01_1147201.pdf","pages":"1-444","target":["衛生福利部部長邱泰源","法務部","內政部警政署"],"title":"保護令非萬能 要求一個月內敲定電子監控執行單位","topics":["家庭暴力","民事保護令","電子監控","警察人力"],"summary":"廖偉翔盤點家暴數據：108年到113年通報從16萬件增到22.2萬件，違反保護令從110年1,758件增到113年2,389件，成長超過35%，顯示保護令嚇阻力不足。他追問電子監控討論過卻沒做，卡在沒人願意執行，要求衛福部一個月內找出執行單位並修法。他也質疑基層員警被調去拔香菇。","demands":["衛福部一個月內召開會議，找出電子監控到底要由誰來執行","衛福部把卡住的根本問題攤開解決，並具體推動修法","警政署查明是誰下令基層員警去高雄路邊拔香菇並回報","衛福部說明對地方家暴受理中心、庇護所人力與床位不足有無規劃和精進改善作為","行政機關正視民眾覺得刑法保護不了人身安全的怒吼"],"faults":["違反保護令件數從110年1,758件增到113年2,389件，成長逾35%","電子監控過去討論過卻沒推動，卡在沒單位願意執行","信義區家暴殺人案，被害人已遠離同居處仍被追堵，沒能預防","地方家暴受理中心與庇護所人力、床位不足，被害子女無法同住","基層員警被叫去拔香菇，耽誤詐騙等真正該辦的案件"],"reply":"邱泰源說會有擔當，一個月內與司法院、法務部、警政署研商電子監控並取得共識；警政署表態支持科技警示；法務部說涉及人力經費。","quotes":["我覺得保護令不是萬能符咒","這樣讓基層員警去做拔香菇的事情"],"fixed":true,"chars":4689,"followups":[]},{"gz":"GZ-1146901_00005","date":"2025-07-31","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第22次會議邀請衛生福利部部長就「因應2026失智症防治照護政策綱領2.0升級3.0，盤點、檢討及精進台灣失智症預防、照護、用藥等政策」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/69/LCIDC01_1146901.pdf","pages":"253-324","target":["衛生福利部","衛生福利部次長林靜儀","健保署署長石崇良","司長祝健芳"],"title":"拔管獎勵成效差 要求納入住宿機構、點數加倍","topics":["失智症","拔管獎勵","長照3.0","攝護腺癌篩檢"],"summary":"他盯健保署的拔管獎勵：每人次3,000點，三年只有579人成功拔管，不到原估的2%，長照住宿機構鼻胃管使用率卻高達50%。他要求把照護之家、養護機構納入獎勵，點數提高1.5至2倍。他也指失智資料統計有漏洞、據點量能不足，輕度失智18萬人只有約1萬人用據點，並主張把攝護腺癌納入癌篩評估。","demands":["健保署年底前把照護之家、養護機構納入拔管獎勵","今年底前完成住宿型機構人員訓練課綱，發給各機構","115年度拔管獎勵點數提高1.5至2倍","衛福部到第一線了解個管員負荷，別只看給付數據","攝護腺癌先給50到69歲或有家族史者公費PSA，研議報告送辦公室"],"faults":["健保署拔管獎勵三年累計579人，不到原評估值的2%","長照住宿機構鼻胃管使用率高達50%，沒有以病人為中心","衛福部說要把移除鼻胃管列為長照3.0重點，半年多沒提出計畫","失智流病調查漏算社會照顧成本，身障調查漏掉沒有證明的失智者","失智據點10縣市未成長、3縣市減少，近2年撤點率12%、7%"],"reply":"健保署說計畫執行得不好已檢討，插管三個月改一個月、住宿型機構要納入，年底前開專家會議；次長說長照3.0明年開始推動，PSA篩檢再研議。","quotes":["我們就是要爭取納入，那什麼時候要納入？","為了避免過度醫療，也要把經費花在刀口上"],"fixed":false,"chars":6780,"followups":[]},{"gz":"GZ-1146701_00003","date":"2025-07-16","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第20次會議邀請環境部部長、經濟部部長、海洋委員會、農業部、內政部、國防部、金融監督管理委員會針對「光電設施對環境影響情形」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/67/LCIDC01_1146701.pdf","pages":"145-238","target":["環境部部長彭啓明","署長謝燕儒"],"title":"電池廠大火測站卻全正常，要求檢討空品監測公信力","topics":["空污監測","化學工廠","毒化災應變","資訊揭露"],"summary":"高雄三元超級電池廠大火，證實有毒的氫氟酸外洩。廖偉翔發現環境部空氣品質測站當天數值全部正常，連他特別查的鳳山測站也一切正常，質疑測站數據的真實性。他也指出環境部和毒化署網頁完全沒有說明，民眾只被通知待在家裡，卻不知道何時解除。他要求檢討測站、建立高風險工廠周邊的預防性監測，並與地方共同制定通報和安全流程。","demands":["請環境部回頭確認測站當天有沒有出狀況，檢討數據公信力","請環境部提出高風險化學工廠周邊監測策略的改善方向","研議專屬事故監測點或微型感測網路，做事前預防","請與地方政府檢討，明確告知居民處理進度和可做的事","加強演練與設備檢查、每小時公告空氣監測，中央地方共訂安全流程"],"faults":["大火嚴重到航班延誤，測站數據卻全都合標準，無法讓居民安心","環境部與毒化署網頁對火災和毒物外洩沒有任何說明","只通知民眾待在家裡，結束了民眾也一無所知，資訊不同步","高風險工廠是災害發生才處理，缺少主動的預防機制"],"reply":"彭啓明說是煙流往上擴散，不一定經過地面測站，該廠已開罰；謝燕儒說當天接獲環保局通報後到場監測，訊息由當地指揮官發布，會再檢討。","quotes":["顯然客觀事實就是沒有測到","兩邊的溝通不夠同步，對民眾的資訊交代也不夠負責"],"fixed":false,"chars":3897,"followups":[]},{"gz":"GZ-1146302_00001","date":"2025-06-23","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第18次會議一、審查(一)委員劉建國等17人擬具「老人福利法第四十八條條文修正草案」案、(二)台灣民眾黨黨團擬具「老人福利法第四十八條條文修正草案」案；二、審查(一)委員許宇甄等18人擬具「身心障礙者權益保障法第五十","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/63/LCIDC01_1146302.pdf","pages":"1-118","target":["衛生福利部","衛福部長邱泰源","衛福部次長呂建德"],"title":"個人助理應入法 用專章專條落實自立生活","topics":["身心障礙","個人助理","CRPD","自立生活"],"summary":"廖偉翔關心重度障礙者的自立生活，指出個人助理是障礙者留在社區最關鍵的支持，我國卻只用授權命令的子辦法規範，法律層級落後。他舉打贏行政訴訟的玉姐為例，說核定時數根本不夠，衛福部報告第12頁卻建議無須納入本法。他主張比照長照，以專法或專章專條把個助制度入法，並要行政院交出身權法版本。","demands":["要求衛福部以專章或專條把個人助理制度納入身權法","比照長照制度，用專法或專章建立完整個人助理制度","要行政院交出身權法修法版本，承諾去年5月前提出已過一年半","個助試辦方案不能只做玉姐一人，其他重度障礙者也要處理","不要再用需要時間研議共識為理由拖延"],"faults":["衛福部報告第12頁稱專章專條多屬執行面、建議無須納入本法","個人助理制度僅以授權命令的子辦法訂定，法律層級與規範密度落後","2017年、2022年兩度國際審查都建議改進個助制度，至2025年無明顯進展","2023年只把個助時薪從200元提高到250元，不足以吸引人投入","個助人數2022年625人、2023年748人，去年反而降到733人"],"reply":"邱泰源說目標可用多元方式達成，現行個助依自立生活計畫提供，仍要凝聚共識；呂建德說已兩度到新莊看玉姐，將與新北市合作辦試辦方案。","quotes":["但是個人協助制度其實是其中最關鍵的機制","漠視障礙團體的需求，甚至背離自己的同志嗎？"],"fixed":false,"chars":2945,"followups":[]},{"gz":"GZ-1146001_00017","date":"2025-06-18","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第17次會議邀請勞動部部長就「營造友善職場育兒環境，落實照顧不離職政策規劃」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/60/LCIDC01_1146001.pdf","pages":"443-516","target":["勞動部","勞動部長洪申翰"],"title":"育嬰津貼別拖到2026，家照假應增至14天並有薪","topics":["育嬰留停","家庭照顧假","就業保險法","少子化"],"summary":"他關心低生育率下的育兒。勞動部研議雙親各領滿6個月後再加1個月津貼，最快2026年上路，他批緩不濟急、要求提前。他指非典型就業者被6個月年資門檻漏接，一般勞工只有7天無薪家庭照顧假形同虛設；育嬰留停試辦單位約89家，其中只有24家事業單位、182人申請。他主張家照假增至14天並有薪，育嬰假彈性擴大到6歲。","demands":["請勞動部加速就保法修法，育嬰留停加發津貼別拖到2026年才實施","請勞動部研議放寬育嬰留停6個月工作門檻，例如降到3個月","請勞動部參考國際經驗，研議家庭照顧假由7天增為14天並有薪化","請勞動部研議彈性育嬰假適用對象由3歲擴大到6歲，並先了解家長需求","請勞動部提出育嬰留停試辦的精進配套，把措施做得更普及"],"faults":["勞動部就保法修法草案排到今年底才送行政院，緩不濟急","契約工、臨時工等非典型就業者無法申請育嬰假，被制度漏接","一般勞工7天家庭照顧假併入事假且無薪，形同虛設，不如軍公教","育嬰留停試辦只有24家事業單位、182人申請，普及度不足","部長一再以財劃法削弱財政為由回應，被批搪塞、不負責任"],"reply":"洪申翰說就保法修法牽涉面向多，今年底才送行政院；家照假有薪化1天要上百億，財劃法後財政吃緊；願參考國際經驗，先做不修法的育嬰留停彈性化。","quotes":["照顧工作是很沉重，父母親的身分不要成為職場身分的緊箍咒","你就用這個東西來搪塞，我覺得是不負責任的"],"fixed":true,"chars":6096,"followups":[]},{"gz":"GZ-1145902_00001","date":"2025-06-09","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第16次會議審查一、行政院函請審議「全民健康保險資料管理條例草案」案；二、委員林月琴等21人擬具「全民健康保險資料管理條例草案」案（114年6月9日、114年6月11日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/59/LCIDC01_1145902.pdf","pages":"1-188","target":["衛生福利部","衛生福利部部長邱泰源"],"title":"健保資料專法授權過寬　要求諮議會議事全公開","topics":["健保資料","資訊隱私","健保總額","立法程序"],"summary":"廖偉翔先問明年健保總額推估是否要漲保費，要求把總額內非醫療項目移出。回到健保資料管理條例草案：憲判字第 13 號 111 年宣判、限 3 年內修法，行政院版拖到上個月中才送院。他指草案概括授權過寬，重大公益沒界定、回饋金沒訂比率、公聽會只開一次，要求補配套並讓諮議會議事公開。","demands":["要求衛福部就健保總額做通盤檢討，並提供辦公室一份報告和資料","要求衛福部承諾健保資料諮議會議事公開、決議結果書面揭露","要求每年舉辦公開聽證，讓公民團體檢視資料使用狀況與政策方向","要求明確界定重大公益與學術必要性，並補上請求停止利用的配套","要求就草案第十五條明確規範產業利益的認定與回饋金比率"],"faults":["憲判字第 13 號 111 年宣判，行政院版本上個月中才送立法院，拖了 3 年","行政院版沒明確揭示實質審核標準與行政透明機制，裁量空間過大","草案第十六條到第十九條的例外情況未實質界定，恐成資料庫濫用漏洞","草案第十五條未定產業利益認定與比率，回饋機制恐形同虛設","立法院只開過一次公聽會，社會溝通與各界意見聽取不足"],"reply":"邱泰源說推估不必調漲保費，公務預算部分會繼續爭取；第十九條、第十條已有配套，審查小組有 24 位專家委員，會議紀錄公開沒問題。","quotes":["憲判字第 13 號在 111 年就宣判了，而且揭示 3 年內應該要修法","不是到逐條審查就真的叫做周全"],"fixed":false,"chars":4779,"followups":[]},{"gz":"GZ-1145601_00007","date":"2025-06-04","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第15次會議邀請勞動部部長就「勞工退休金制度改革，含勞保、勞退執行現況」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/56/LCIDC01_1145601.pdf","pages":"377-444","target":["勞動部長洪申翰","局長蘇郁卿"],"title":"勞動基金虧損擴大 要求政府最終支付責任入法","topics":["勞保財務","勞動基金績效","減班休息","就學補助"],"summary":"他盯勞保勞退財務。勞退基金4月單月帳面虧損約1,300億，今年到4月損失1,990億、收益率負2.9%。勞保短絀2024年擴大到655億創歷年新高，精算負債三年增加3兆、來到14兆1,000億。他說光靠投資補不了缺口，要求政府最終支付責任入法，並把就學補助擴大到減班休息家庭。","demands":["要求勞動部說明匯率衝擊的風險控管與解套評估","要求部長明確表態支持政府負最終支付責任入法","要求勞動部不因短期虧損調低保證收益率","要求勞動部研議擴大就學補助到減班休息勞工子女","要求一個月內把研議方向和報告送到辦公室"],"faults":["勞動部只說政府負最終責任，卻遲遲沒有入法","勞保短絀連年擴大，2024年655億創歷年新高","勞保精算負債三年增加3兆，攀到14兆1,000億","失業勞工子女就學補助沒涵蓋減班休息家庭","勞動基金今年到4月損失1,990億、收益率負2.9%"],"reply":"部長說保證收益率不會調整，不論入法與否都支持政府負財務最終責任；並允諾一個月內研議給減班休息勞工更多支持。","quotes":["你也知道股市不可能一直這樣","沒有入法的話，沒有辦法讓百姓安心"],"fixed":false,"chars":4286,"followups":[]},{"gz":"GZ-1145001_00016","date":"2025-05-15","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第11次會議處理或審查114年度中央政府總預算決議有關勞動部主管預算凍結報告案76案（含報告事項59案及討論事項17案）（114年5月14日、114年5月15日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/50/LCIDC01_1145001.pdf","pages":"447-560","target":["勞動部長洪申翰","勞動部勞動基金運用局長蘇郁卿","司長陳美女"],"title":"關稅匯率雙殺　自營作業者被漏接　要一個月內提方案","topics":["關稅衝擊","自營作業者","勞動基金匯損","預算凍結"],"summary":"面對關稅和匯率衝擊，他最在意自營作業者和無一定雇主。到臺中考察時，一位整復師說4月起客人少了七成，他指出現有補助多半只給有雇主的勞工，這群人被漏接。他要勞動部一個月內提出協助方案並開始推動，也把他們納入訓練轉型計畫。另要求勞動基金運用局補提美債持有比率與匯損數字。","demands":["要勞動部一個月內提出協助自營作業者、無一定雇主的方案報告並開始推動","要求把自營作業者和無一定雇主納入充電再出發等訓練與補助方案","要勞動基金運用局會後提供美債持有比率與未實現匯損資料","要勞動部說明勞保宣導的量化目標與實際成效","要求會費預算精準編列，不要寬列"],"faults":["勞動部制定政策的感受與第一線落差大，自營作業者被漏接","現有補助方案多只給企業或有一定雇主者，自營作業者原本沒有方案","勞動基金運用局說不出美債比率和匯損，只講分散風險的官方說法","勞動基金運用局說凍結1萬元就影響入會，一千二百分之一的比例說不通","勞保宣導只拿滿意度九成當成果，沒有量化評估；預算中心也指媒宣費過度集中部分媒體"],"reply":"洪申翰說方案研擬中，6月前完成準備、協助方案盼6月下旬提出，上路時機看關稅情境；蘇郁卿說月底才評價，已投資的國家有七十幾個，靠分散配置降風險；陳美女說勞保宣導每年到各縣市辦，滿意度問卷大概都有到九成。","quotes":["部長，這些人是被漏接的一群","我只是要告訴你，這1萬塊、一千二百分之一搞得好像是沒有辦法加入"],"fixed":true,"chars":9191,"followups":[]},{"gz":"GZ-1144701_00004","date":"2025-05-08","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第10次會議一、邀請衛生福利部部長就「長照2.0執行情形檢討及3.0未來規劃」進行專題報告，並備質詢；二、邀請衛生福利部部長就「澳洲進口豬腳驗出含萊克多巴胺，如何加強肉品食安查驗，讓民眾放心」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/47/LCIDC01_1144701.pdf","pages":"163-256","target":["衛生福利部部長邱泰源","衛生福利部次長呂建德","衛生福利部食品藥物管理署署長姜至剛"],"title":"長照3.0人力缺口未解、萊豬零檢出雙標","topics":["長照3.0","長照人力","萊克多巴胺","食安查驗"],"summary":"廖偉翔問長照2.0接3.0的財源和人力。經費從47.97億漲到828億、約17倍，卻看不到未來10年財務規劃；2023年每位照服員平均服務10.8位長輩，平均年齡超過50歲，人力只成長1.3%。食安上，他質疑儀表板進口占比24%、官方卻說10%，進口容許萊劑、本土零檢出是雙標。","demands":["請衛福部說明未來10年的長照財務規劃與財源","請衛福部把長照人力的檢討與具體做法寫成報告送辦公室","請衛福部提供醫療照顧整合的推動進度與KPI","請衛福部檢討食安雙標，並落實今天的臨時提案","請部長、署長想清楚怎麼做才能讓民眾食在安心"],"faults":["長照3.0資料裡看不到未來10年的財務規劃","長照人力沒盤點清楚缺多少，做法偏口號式","調高居服員待遇後，住宿型與醫療機構人才流失","豬肉儀表板進口占24%，與進口只占10%的說法落差大","進口豬容許萊劑、本土卻要零檢出，標準雙標"],"reply":"次長呂建德說長照基金已累積2,036億、10年內財源無虞；署長姜至剛說儀表板的24%是抽驗比例，對進口抽驗比例較高。","quotes":["如果你覺得都沒影響的話，法規上為什麼本土的要零檢出？","不是透過一句科學檢驗就能當作免死金牌，其實安心與安全一直是兩回事"],"fixed":false,"chars":5204,"followups":[]},{"gz":"GZ-1144501_00007","date":"2025-05-01","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議審查：一、委員王育敏等18人擬具「病人自主權利法部分條文修正草案」案；二、委員劉建國等16人擬具「病人自主權利法部分條文修正草案」案；三、委員邱志偉等19人擬具「病人自主權利法第八條、第九條及第十五條條文修","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/45/LCIDC01_1144501.pdf","pages":"359-422","target":["衛生福利部","部長邱泰源","司長劉越萍"],"title":"預立醫療成效不佳　要求納健保並訂全民適用時程","topics":["病人自主權利法","預立醫療","健保給付","偏鄉醫療"],"summary":"廖偉翔關心預立醫療的推動成效。他指出2023年簽署預立醫療決定的人只占成年人口0.35%，主因是諮商採自費、收費2,000到8,000元，加上宣導不佳與國人觀念。他要求衛福部提出擴大全民的具體規劃與時程，不要用通盤檢討拖延；偏鄉要設行動諮商站，也要改善宣導人才待遇。","demands":["衛福部提出ACP擴大全民的具體規劃，說明2026或2027年達成","把團體諮商的檢討報告與具體文字建議送到廖偉翔辦公室","偏鄉結合長照或銀髮關懷據點，開設行動諮商站","修法讓獨居者經社工評估後免除親屬參與諮商","改善醫療體系行政與宣導人才待遇，避免人才流失"],"faults":["ACP採自費，收費2,000到8,000元，成本轉嫁民眾形成經濟篩選","全臺77%鄉鎮市區沒有諮商據點，分布不均","AD簽署量六都就占72%，其中臺北市占36%，城鄉資源差距明顯","書面報告說要擴大ACP規模，卻沒寫出具體措施","曾宣示2026年擴大全民，書面報告改口要通盤檢討","衛福部臉書衛教宣導只有1.9萬、3,208、1.6萬次瀏覽"],"reply":"部長邱泰源說預立醫囑是愛家人的表現，會循序漸進推動，行動諮商站可以研議，並承諾提供報告、珍惜人才。司長劉越萍說團體諮商指引今年下半年討論。","quotes":["不要用還要再討論、還要再通盤檢討當理由拖延時間","要改善他們的待遇，這才是今天質詢最重要的意義"],"fixed":true,"chars":3939,"followups":[]},{"gz":"GZ-1144301_00003","date":"2025-04-28","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第8次會議邀請環境部部長列席報告業務概況，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/43/LCIDC01_1144301.pdf","pages":"69-174","target":["環境部部長彭啓明","署長賴瑩瑩"],"title":"小油坑火警敲警鐘 全面體檢一萬多個空品感測器","topics":["空品感測器安全","電子廢棄物回收","廢手機回收","拾荒者權益"],"summary":"陽明山小油坑火警燒掉30至50公頃林地，初步研判是監測儀器裡的鋰電池起火。廖偉翔指出環境部跟地方合作設置大概一萬座空品感測器，比較便宜、安全規範和巡檢制度都不明確。他也發現回收統計沒有廢手機欄位，列冊拾荒者7,283人只有2,370人參加資收關懷計畫。他要求儀器盤點列冊、新增廢手機統計、提高拾荒者誘因。","demands":["請環境部一個月內啟動專案，重新檢討一萬多個儀器的安全風險","儀器要列冊管理、定期巡查汰換，訂過充保護與過熱斷電標準","回收統計新增廢手機欄位，才能追蹤多少手機進到拆解","環境部主動找手機與電信業者開會提高誘因，並回報開會進展","提高拾荒者回收費率，5,000元誘因上限應調高並加強宣導"],"faults":["跟地方合作的一萬多個感測器比較便宜，安全規範還沒重新檢視","手機回收被盜刷十萬多塊，環境部只打算做手冊指引，不夠具體","回收統計沒有廢手機欄位，無法精確知道多少量進到拆解","列冊拾荒者7,283人只有2,370人參加關懷計畫，只占三成","報告第17頁提到循環率，卻沒寫明循環率115年才開始實施"],"reply":"部長彭啓明承諾一個月內處理儀器安全檢討，也認同城市採礦；署長賴瑩瑩說去年已公告手機回收規定，會做手冊指引提醒第一線照SOP。","quotes":["但是部長千萬不要過於自信，任何一個發生狀況都有問題","因為你們造冊的跟真正參與的、實地調查的差距很大，大概是二、三十倍。"],"fixed":false,"chars":4303,"followups":[]},{"gz":"GZ-1144101_00004","date":"2025-04-23","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議邀請衛生福利部部長、財政部次長就「國家社會福利政策財源檢討及偏鄉兒童發展篩檢執行情形」進行專題報告，並備質詢（114年4月23日、114年4月24日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/41/LCIDC01_1144101.pdf","pages":"287-370","target":["衛生福利部部長邱泰源","衛生福利部處長李建璋"],"title":"食安不能對美方退讓 醫療資安要有軟體物料清單","topics":["食安","美豬美牛","醫療資安","軟體物料清單SBOM"],"summary":"他關心美方施壓下的食安底線：美方質疑我方豬肉原產地標示與萊克多巴胺容許值，食藥署又預告開放全牛齡日本牛肉，要求部長向國人宣示絕不退讓。他再問醫院資安，發現部長不知道什麼是軟體物料清單SBOM，資訊處也說那是FDA業管，主張從源頭盤點醫療設備軟體供應鏈，並限一個月內提檢討報告。","demands":["要求衛福部一個月內提出導入FDA SBOM基準可行性評估與檢討報告","要求部長公開向國人宣示，食安標準絕不對美方退讓","要求部長宣示至少產地一定要標示清楚","要求衛福部從源頭盤點醫療設備與系統的軟體供應鏈安全","要求衛福部輔導醫療機構重視軟體供應鏈漏洞掌控"],"faults":["衛福部長不知道什麼是軟體物料清單SBOM","資訊處稱SBOM是FDA業管，未採用該標準","衛福部資安作為多是事後補救，事前預防老調重談","食藥署預告取消30個月齡限制，擬開放全牛齡日本牛肉","次世代數位醫療平台計畫承諾執行好，仍每月出資安事件"],"reply":"邱泰源說食安優先、不能退讓，原產地標示國產與進口一體適用；資訊處稱SBOM是FDA業管，會檢討精進，部長允諾一個月內提報告。","quotes":["國人的食品安全不能被出賣","我們是不是應該要從源頭把這個東西盤點好？"],"fixed":true,"chars":4439,"followups":[]},{"gz":"GZ-1143801_00007","date":"2025-04-17","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議一、邀請環境部部長、經濟部、外交部就「因應美國退出巴黎氣候協定並提出對等關稅，對國內產業淨零轉型造成衝擊」進行專題報告，並備質詢；二、邀請環境部部長、勞動部、教育部、經濟部針對「國內校園、賣場及工作場域之室","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/38/LCIDC01_1143801.pdf","pages":"427-512","target":["環境部部長彭啓明"],"title":"關稅衝擊淨零轉型，要環境部拿出量化分析","topics":["淨零轉型","碳費","關稅","核能"],"summary":"美國退出巴黎氣候協定又課關稅，出口產業被關稅壁壘和碳邊境調整機制夾擊，40%的出口企業說可能放緩碳減排投資。廖偉翔發現政府拿不出細緻量化評估，自願減量說明會去年只辦5場、908人參加，註冊申請63案只通過16案。他要求按不同關稅情境算清楚衝擊、擴大說明會場次，並協助中部企業轉型。","demands":["要求環境部依10%、20%、32%不同關稅情境，做細緻的量化衝擊分析","要求環境部評估對特定企業降低減碳目標或暫緩收碳費的可行措施","要求環境部說明專案補助輔導的具體內容，優先協助中部中小企業","要求環境部說明新的一年自願減量說明會要辦幾場，並擴大辦理","要求部長針對非核家園修法表態，並了解手機回收遭盜刷案後回復"],"faults":["環境部只做滾動式調整，對關稅衝擊拿不出細緻的量化分析","環境部去年自願減量說明會只辦5場、908人參加，場次明顯不足","截至今年4月11日受理63案專案註冊申請，只通過16案","部長不願明確表態支不支持修法，只說做起來很困難","能源部門燃料燃燒排放超過50%，淨零進度落後"],"reply":"彭啓明說關稅版本每天在變，還沒做到這麼細緻；說明會預計辦30、40場以上；核能他開放討論但執行困難；盜刷案今天才知道，會了解後回復。","quotes":["所以部長還是不願意表態支持不支持，如果立法院修法通過之後，你會支持嗎？","民眾響應環保回收，即便已經遵照了步驟來操作，卻仍遭到盜刷"],"fixed":true,"chars":3661,"followups":[]},{"gz":"GZ-1143801_00006","date":"2025-04-16","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議邀請衛生福利部部長就「面對國際經貿情勢瞬變，我國如何因應並確保藥品、醫療器材等各面向供應正常，保障國人權益。」進行專題報告，並備質詢（114年4月16日、114年4月17日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/38/LCIDC01_1143801.pdf","pages":"347-426","target":["衛生福利部","衛生福利部部長邱泰源"],"title":"藥價改革一拖再拖，要求4月27日前公告","topics":["藥品供應鏈","藥價改革","原料藥","癌症篩檢"],"summary":"他要部長當場宣示，美國關稅談判不會拿國人食品安全當籌碼。接著追藥價改革：11月19日才預告，1月20日預告截止後又拖三個月，質疑雙標，要求4月27日健康臺灣論壇前公告。他還要求對藥品原料啟動國安調查、用藥價誘因鼓勵藥商找第二來源國，並爭取明年把胃癌列為第六種公費篩檢。","demands":["請部長宣示，關稅談判不犧牲國人食品安全","藥價改革辦法4月27日健康臺灣論壇前公告，至遲4月底","比照美國，對藥品與原料藥啟動國安調查","用藥價政策給實質誘因，鼓勵藥商開拓第二原料藥來源國","明年把胃癌列第六種公費篩檢，比照大腸癌補助45到74歲"],"faults":["衛福部藥價改革預告截止後又過三個月，遲遲沒公告","共擬會辦法不到一個月就公告，藥價改革卻拖，形同雙標","健康臺灣喊國藥國用，對原料藥只有口頭鼓勵","衛福部對第二來源國只答在地優先，沒提具體誘因"],"reply":"邱泰源承諾藥價改革盡量4月27日前完成、至慢4月底公告；石崇良說用臺灣原料藥可加10%藥價；胃癌篩檢明年全國開辦。","quotes":["為什麼這件事情是一拖、二拖、三拖？","我講的就是要積極鼓勵，但能不能不要只是口頭的鼓勵？"],"fixed":false,"chars":4858,"followups":[]},{"gz":"GZ-1143301_00001","date":"2025-03-27","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議邀請衛生福利部、勞動部、國家發展委員會、教育部、法務部針對「少子女化衝擊，如何營造友善托育環境」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/33/LCIDC01_1143301.pdf","pages":"1-120","target":["勞動部次長李健鴻","衛生福利部"],"title":"育嬰假試辦只有89家參加，要求津貼一次給到有感","topics":["少子女化","育嬰留職停薪","家庭照顧假","長期照顧"],"summary":"廖偉翔關心托育與照顧政策做得夠不夠。彈性育嬰假試辦去年只有63家參加、今年89家，對照全國163萬家中小企業幾乎看不到。育嬰留職停薪津貼只研議多給1個月，他認為不夠，主張加到2個月、從6個月延到8個月，並讓雙親各領滿6個月。他也點出家庭照顧假併在事假、7天為限太少。","demands":["要求勞動部檢討彈性育嬰假試辦成效，有結論就通知委員辦公室","育嬰留職停薪津貼別只加1個月，應加2個月、從6個月延到8個月","放寬到雙親都能各領滿6個月育嬰留職停薪津貼","要求勞動部在勞基法單獨列出長期照顧安排假或增加家庭照顧假","家庭照顧假研議要給出完成時間，並回報委員辦公室"],"faults":["彈性育嬰假試辦去年僅63家參加、今年89家，對照163萬家中小企業差距懸殊","勞動部拿82%回歸職場率當理由不敢加碼，數字關聯性沒說清楚","兩性申請育嬰留職停薪仍差3倍，性別不平等問題還是嚴重","家庭照顧假併在事假裡又以7天為限，明顯不夠用","因家庭照顧離職的人數沒有精確統計，只有考慮離職六成的調查"],"reply":"勞動部次長李健鴻說試辦採自願參加，已用座談、問卷、拜訪三管道蒐集意見；就保法研議多給1個月，家庭照顧假將朝更彈性方向研議。","quotes":["我認為既然要給可能就要一次給到有感，延長1個月不夠，可能要增加2個月","顯然是不夠、顯然是不夠，因此我才會提出是否可以將它單獨列出來"],"fixed":false,"chars":3058,"followups":[]},{"gz":"GZ-1142901_00005","date":"2025-03-19","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議一、處理113年度中央政府總預算附屬單位預算決議有關勞動部預算凍結報告案19案；二、邀請勞動部部長列席報告業務概況，並備質詢；三、繼續審查114年度中央政府總預算案附屬單位預算關於勞動部主管部分（114年3","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/29/LCIDC01_1142901.pdf","pages":"285-536","target":["勞動部","勞動部長洪申翰"],"title":"工時全球第5高 要勞動部表態支持還勞工7天假","topics":["工時","7天假","過勞","同工不同酬"],"summary":"他關心勞工工時過長。勞動部2024年勞動統計年報顯示，臺灣勞工平均年工時2,030小時，OECD平均1,713小時，等於每年多做約一個月；加班的勞工中有15%領不到加班費。他認為勞工要的是加薪不是加班，要勞動部長表態支持還勞工7天假，並跟內政部溝通，也追問同工不同酬的案件數字。","demands":["要勞動部長洪申翰明確表態，支持還勞工7天假","要勞動部主動跟內政部長溝通，替勞工爭取還假","要勞動部提出過去三年同工不同酬案件數與違法比例","要勞動部落實釋字807號，積極推動修法保障性別平等","要勞動部拿統計數字推動，讓每年同酬日往前縮短"],"faults":["勞動部次長李健鴻說很多勞工希望多加班賺錢，說法不負責任","勞動部對釋字807號只發布函釋，沒有積極推動修法","勞動部答不出過去三年同工不同酬的案件數與違法比例","內政部長劉世芳說7天假不是真正的議題、不宜倉促立法","每年過勞相關疾病死亡超過500人，政府作為不夠積極"],"reply":"洪申翰說次長原意是希望協助勞工加薪，勞動部推動最低工資上漲與薪資透明化；國定假日主管機關是內政部，勞動部認為有正向討論空間。","quotes":["勞工要的是加薪，不是加班","政府的責任是解決勞工的低薪，也不是鼓勵他們加班"],"fixed":false,"chars":3544,"followups":[]},{"gz":"GZ-1142901_00004","date":"2025-03-17","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議邀請環境部部長、衛生福利部、教育部、經濟部、台灣電力公司、台灣中油公司就「氣象變異致國內空品惡化，精進預報與跨部會應變作為」進行專題報告，並備質詢（114年3月17日、114年3月19日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/29/LCIDC01_1142901.pdf","pages":"199-284","target":["環境部長彭啓明","經濟部"],"title":"七座接收站該做政策環評，空品數據別只挑手動測站","topics":["天然氣接收站","政策環評","空氣品質","PM2.5監測"],"summary":"全臺已規劃7座天然氣接收站，政府只做個案審查，沒做上位的政策環評。廖偉翔指出西部海岸約460公里就有7座，平均每65公里一座，累積性生態衝擊沒被評估，要求做全臺接收站與儲氣場的累積性環評和總量管制。他也質疑手動測站31處、自動測站78處，環境部只採手動數據，恐低估PM2.5。","demands":["要求環境部與經濟部針對全臺7座天然氣接收站做政策環評","要求提出全臺接收站與儲氣場的累積性環評報告與總量管制方案","要求經濟部說明再生能源未達36%時是否還要增建接收站","要求環境部公布空品時併用自動測站數據，真實呈現"],"faults":["經濟部只做逐案審查，未提政策環評，區域累積衝擊沒評估","環境部沒去要求經濟部提政策環評，兩部會都是鴕鳥心態","環境部公布PM2.5只採手動測站，排除78處自動測站數據","說自動測站不可靠卻仍投入資金升級設備，前後自相矛盾"],"reply":"環境部長彭啓明說政策環評須目的事業主管機關提出，環境部不能直接提，但樂見更多溝通；手動測站是國際認可標準，手動與自動會同步參考。","quotes":["我覺得你們真的要認真考慮去做政策環評、做比較上位的政策環評","代表不一樣，但你公布的數據還是只選擇手動測試？"],"fixed":false,"chars":4121,"followups":[]},{"gz":"GZ-1142701_00005","date":"2025-03-13","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請衛生福利部部長就「有關全國急重症醫療量能」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/27/LCIDC01_1142701.pdf","pages":"227-314","target":["衛生福利部部長邱泰源"],"title":"護理離職海嘯 要求編專項預算拉高薪資","topics":["護理人力","急診壅塞","三班護病比","護理薪資"],"summary":"廖偉翔說急診塞爆的根源是護理人力不足。全國持照 30 萬 9,410 人，實際執業僅 19 萬 3,503 人，執業率 62.5%，今年 1、2 月已有超過 550 位護理師離職。他也質疑衛福部公告平均薪資 7 萬，和主計處 5.9 萬差太多。他要求編專項預算提高待遇、發久任獎金，並訂出三班護病比時間表。","demands":["要求衛福部編專項預算，讓新進護理人員年薪達 70 萬以上","要求三班護病比訂出明確時間表、罰則與責任追究","要求另覓財源發久任獎金，留住資深護理師並鼓勵回任","要求回頭查清公告護理平均薪資 7 萬的算法並改進","要求建立護理人員勞動權益保障機制，確保合理工時與工作負荷"],"faults":["衛福部今年開 5 場因應會議，只有 1 場找護理團體參加","公告護理平均薪資 7 萬，和主計處 5.9 萬、勞動部 4.98 萬差太多","三班護病比原訂兩年入法、四年達標，部長答不出能否達成","中長程計畫只做新手臨床教師，沒有留住資深護理人員的措施","應急措施要到 5 月才上路，緩不濟急"],"reply":"邱泰源說薪資網站是各醫院自行填報、含非固定收入，造成困擾他道歉，會再釐清；並稱會全力增加待遇與環境，久任獎金與吸引回流都可研議。","quotes":["現在不只是離職潮而已，更是一個離職海嘯","一定要先面對問題才能夠解決問題"],"fixed":false,"chars":6540,"followups":[]},{"gz":"GZ-1141701_00002","date":"2025-01-02","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第17次會議邀請勞動部、衛生福利部、教育部就「推動友善職場、校園性騷擾與霸凌防治及長照悲歌並檢討現行長照制度缺失與長照3.0規劃」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/17/LCIDC01_1141701.pdf","pages":"87-384","target":["衛生福利部部長邱泰源","衛生福利部次長呂建德","臺大醫院院長吳明賢","臺大醫院副院長高淑芬","臺灣大學主任秘書王大銘"],"title":"臺大權威教授性騷案：跨身分通報漏洞要補齊","topics":["性騷擾防治","職場霸凌","醫界文化","身心障礙者權益保障法"],"summary":"廖偉翔追問臺大醫院權威教授性騷擾案，被害人是住院醫師、沒有學生身分，醫院與校方就沒人通報，這種跨身分、跨法規競合的案子最常出在實習生身上，是法律漏洞。他強調涉案教授任職二十多年，沉痾不會今年才有，要求建立通報管道、讓受害人敢申訴。另問身權法為何還不送立法院。","demands":["臺大醫院與校方建立跨身分案件的即時通報管道","補齊跨身分、跨法規競合案件沒人有義務通報的法律漏洞","臺大醫院把申訴管道做到透明又有保障，讓受害人敢申訴","臺大痛定思痛檢討制度與文化，做出全國的典範","衛福部儘速把身權法版本送到立法院，個人協助制度要入法"],"faults":["臺大醫院：涉案教授任職二十多年，性騷沉痾到今年才曝光","臺大醫院與校方分屬兩套規定，被害人非學生就沒人通報","現行法規對跨身分案件沒有通報義務，是明顯的法律漏洞","臺大醫院只用雇主主動調查，管道不安全讓被害人不敢具名","衛福部身權法草案拖過前院長陳建仁承諾的520期限仍未送院"],"reply":"臺大校方允諾建立通報管道；院方稱預防勝於治療，已在院內宣導性騷防治；衛福部說部內法規會後約1月底、可能2月上旬送行政院。","quotes":["還有管道的安全性，你們的管道要讓受害人信任，可以去申訴","希望你們儘速將這個版本送到立法院"],"fixed":false,"chars":4384,"followups":[]},{"gz":"GZ-1141406_00001","date":"2024-12-25","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第16次會議繼續審查中華民國114年度中央政府總預算案關於衛生福利部主管公務預算部分（113年12月25日、113年12月26日為一次會）（前接第五冊）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/14/LCIDC01_1141406.pdf","pages":"1-436","target":["衛生福利部","衛生福利部長邱泰源"],"title":"醫療AI與電子病歷預算 廖偉翔要求先報告再動支","topics":["醫療AI","電子病歷","預算凍結","衛生福利部"],"summary":"衛福部114年度預算審查。廖偉翔針對醫療新興科技委辦費、次世代電子病歷和AI導入的預算，一連提了多案。他要求醫療業務委辦費凍結1,000萬、電子病歷相關預算維持凍結100萬，這兩類都要先提書面報告、經同意才能動支；另有一案凍結2,000萬元，也是經報告後同意才能動支。國外差旅費則凍20萬元。其他多案改主決議。","demands":["衛福部醫療業務委辦費凍結1,000萬，提書面報告經委員會同意才能動支","次世代電子病歷相關預算維持凍結100萬，報告經同意後才解凍動支","第164案凍結2,000萬元，經報告後同意才能動支","國外差旅費凍結20萬元"],"faults":["衛福部導入AI要有配套處理，不能囫圇吞棗","次世代電子病歷的AI導入方式是否合理、有利業務，說明仍不夠"],"reply":"衛福部說新興科技需委外協助智慧審查與數位治理，電子病歷與工研院合作，AI導入採負責任框架，願提書面報告或改主決議。","quotes":["這個我照舊凍100萬，提書面報告，經同意後始得解凍、始得動支。","對，要同意，始得動支。"],"fixed":true,"chars":3828,"followups":[]},{"gz":"GZ-1141002_00002","date":"2024-12-19","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第15次會議一、繼續審查中華民國114年度中央政府總預算案關於勞動部主管預算；二、繼續審查勞動部函送財團法人職業災害預防及重建中心114年度預算書案（113年12月18日、113年12月19日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/10/LCIDC01_1141002.pdf","pages":"507-544","target":["勞動部","勞動部長洪申翰","勞保局"],"title":"勞動基金要先有檢討報告才審　水電費凍結逼節能","topics":["勞動基金","水電費預算","加班費免稅","中高齡就業"],"summary":"廖偉翔盯勞動部預算。他要求勞動基金要等勞動部檢討報告送出、和審計部審核報告交叉比對，經委員會同意後才審，並要部長守住一個月內交報告。水電費他質疑說明欄今年增列110萬、112到113年度卻減列170萬，邏輯不通，主張凍結施壓節能。另要求勞動部跟財政部協商，把伙食費3,000以上要課稅的門檻往上拉。","demands":["勞動部檢討報告送出、與審計部審核報告交叉比對，經委員會同意才審基金預算","部長守住委員會一個月內提檢討報告的決議，不能只講一個月左右","水電費併凍10%，提出節能精進報告經委員會同意後才解凍","勞動部去跟財政部協商，把伙食費3,000以上要課稅的門檻往上拉","加強違法加班稽查，合法又必要的加班要確保不會被課稅"],"faults":["勞動部電費說明欄今年增列110萬，112到113年度卻減列170萬，邏輯不通","部長早上對媒體說等審計部報告就審基金，和委員會的決議不同","部長把一個月內提檢討報告說成一個月左右，講法模糊","中高齡就業推動效果不夠好，高齡者感受職場年齡歧視比例達百分之六十幾","中分署因應貿易自由化措施執行率偏低，中部無薪假情形掌握不足"],"reply":"洪申翰同意水電費併凍10%，會儘快提節能精進報告；檢討報告一個月內提出；中分署部分尊重委員凍結，書面報告會儘快提供。","quotes":["我們要審這個基金預算，還是要知道貓膩到底在哪？","總不能夠在各個方面一直拿人民的納稅錢"],"fixed":true,"chars":18147,"followups":[]},{"gz":"GZ-1140804_00002","date":"2024-12-19","committee":"經濟委員會","agenda":"經濟委員會第20次會議繼續審查114年度中央政府總預算案附屬單位預算營業部分關於經濟部主管：台灣自來水股份有限公司、台灣電力股份有限公司（處理）（113年12月18日、113年12月19日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/08/LCIDC01_1140804.pdf","pages":"103-366","target":["經濟部","台灣電力股份有限公司"],"title":"中火二期留6座燃煤機組 質疑能源配比犧牲中部健康","topics":["能源配比","中火燃煤","空污健康","能源安全"],"summary":"廖偉翔關心能源政策配比，認為現在的配比犧牲了健康，也帶來能源安全問題，連美國商會都擔心我們的能源自主。他質疑中火二期改天然氣後，為什麼還要留下6座燃煤機組，做不到拆一減一。電若真的夠就不該開，一旦電不足就重啟，等於讓中部人用肺發電。他支持張啓楷委員的提案。","demands":["要求台電說明中火二期為何做不到拆一減一","要求台電回去問經濟部長為何仍留6座燃煤機組","要求檢討能源政策配比，別再犧牲中部人健康","表態支持張啓楷委員就本案提出的提案"],"faults":["中火二期改天然氣後仍留6座燃煤機組，未做到拆一減一","台電以國安危機為由保留燃煤機組，說法讓人難以理解","能源配比失衡，犧牲中部人健康也影響能源自主","電不足就重啟多的2支機組燃煤，等於讓中部人用肺發電"],"reply":"","quotes":["為什麼最終結束還要留下 6 座燃煤機組","多的 2 支機組繼續燃煤，讓臺中人來用肺發電"],"fixed":false,"chars":508,"followups":[]},{"gz":"GZ-1141002_00001","date":"2024-12-18","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第15次會議一、繼續審查中華民國114年度中央政府總預算案關於勞動部主管預算；二、繼續審查勞動部函送財團法人職業災害預防及重建中心114年度預算書案（113年12月18日、113年12月19日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/10/LCIDC01_1141002.pdf","pages":"1-506","target":["勞動部","勞動部長洪申翰","勞工保險局"],"title":"就安基金五千多萬用途不符，主張暫緩審預算","topics":["就業安定基金","預算審查","審計","缺工"],"summary":"他認為就業安定基金弊端太多，審計部指出五千多萬用途不符，勞動部卻還沒說要不要追償、提告。他指出這個基金30年來收取近千億，支出明細從未公布，近五年細目也沒釋明，謝宜容的送禮名單同樣不公開。他主張先把帳算清楚，暫緩處理勞動部114年度基金預算，否則審了就是替濫用公帑的人背書。","demands":["要勞動部說清楚就安基金要不要追償、要不要提告，何時做","暫緩處理勞動部114年度基金預算，待檢討報告比對審計報告、委員會同意再處理","要求公開謝宜容的送禮名單","要勞動部說明何時召開全國缺工會議，報委員會同意後才解凍","勞保局的媒體宣傳經費他不減列、只凍結，要求兩個月內提出專案報告，經同意才解凍"],"faults":["勞動部至今未對外釋明近五年就安基金的相關細目","就安基金30年來收取近千億，卻未公布支出明細","審計部指就安基金五千多萬用途不符，勞動部仍未說明是否追償","謝宜容的送禮名單至今未公布","農保逾180日才取消資格，清查作業不夠主動、結果也未公開"],"reply":"洪申翰說審計部正式報告還沒拿到，拿到後會依法處置、絕不迴避；缺工評估希望年後有初步結果；勞保宣傳費細目願意提供委員參閱。","quotes":["立法院不應該成為濫用公帑的共犯","就是在幫這些濫用公帑的人背書"],"fixed":true,"chars":14027,"followups":[]},{"gz":"GZ-1140602_00002","date":"2024-12-16","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第14次會議一、邀請衛生福利部部長列席報告業務概況，並備質詢；二、邀請衛生福利部部長、考試院、行政院人事行政總處針對「所屬機關有關霸凌事件之調查檢討」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/06/LCIDC01_1140602.pdf","pages":"143-284","target":["衛生福利部部長邱泰源","衛生福利部次長呂建德","國民健康署署長吳昭軍"],"title":"霸凌報告避重就輕，要衛福部重啟調查、查清性騷關說","topics":["職場霸凌","性騷擾","電子煙","地下醫美"],"summary":"廖偉翔質疑衛福部霸凌調查草率：8個案子只訪談96人，問卷回收率25%，主管要員工深蹲、伏地挺身卻不算霸凌，次長也說管理不當，報告該重新深究。他接著追問臺大C教授性騷案，6名受害醫師申訴屬實，當事人搶先請退，還傳出找總統府資政壓案。最後點名地下醫美與電子煙管制執行不力。","demands":["衛福部再生醫療雙法子法與施行日期，114年第一季預告不得再拖","衛福部霸凌調查報告要回去深究、重啟重寫","衛福部深入調查臺大C教授性騷案，受害者恐不只6位","查清是哪位總統府資政施壓壓案，給社會一個交代","國健署把民眾檢舉的300個違法電子煙販售網站禁掉"],"faults":["衛福部8案只訪談96人、問卷回收率25%，等於1案約12人","次長已說司長管理行為不當，卻認定不構成霸凌","部長對臺大C教授性騷案事前完全不知情，只從媒體得知","地下醫美恐占醫美市場近61%，衛福部查緝執行很差","300家電子煙網站沒被停止解析，警語反成購買推薦清單"],"reply":"次長呂建德說祝姓司長的管理行為不當、也已經記過，但要尊重學者專家的事實調查，霸凌認定得符合法院判決的要件；部長說再生醫療子法114年第一季預告、性騷案一定依法辦理；國健署說會盡力處理電子煙網站。","quotes":["叫人家深蹲做伏地挺身，這根本就已經上升到體罰的層次","本來是禁止名單，現在變成購買推薦清單耶"],"fixed":true,"chars":8596,"followups":[]},{"gz":"GZ-1140403_00001","date":"2024-12-09","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第13次會議一、邀請勞動部部長列席報告業務概況，並備質詢；二、審查中華民國114年度中央政府總預算案關於勞動部主管預算（公務及基金預算）；三、審查勞動部函送財團法人職業災害預防及重建中心114年度預算書案【所列預算案","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/114/04/LCIDC01_1140403.pdf","pages":"1-196","target":["勞動部","勞動部長洪申翰"],"title":"工時世界第二、就安基金遭濫用　要求審議公開錄影","topics":["過勞工時","就業安定費","就業安定基金","身心障礙權益"],"summary":"廖偉翔關心過勞。他指勞動部公布2023年年總工時2,020小時、世界第2，25萬人週工時超過60小時，比前一年多15小時。他也批評身心障礙者自費請看護移工還要繳就業安定費，形同障礙稅。就業安定基金宣導費從1.09億漲到2.17億，他要求不相干支出改回公務預算，審議會議錄影公開。","demands":["勞動部三個月內就身心障礙者免繳就業安定費給出具體正面回應","就業安定基金審議會議錄音錄影上網公開，比照立法院公開審查","與就安基金使用目的無關的預算，改編入勞動部公務預算","一個月後提出機制檢討結果，並看到資訊公開的決定","勞動部應積極向內政部爭取還給勞工七天假，不能只是反映"],"faults":["勞動部：2023年年總工時2,020小時、世界第2，比前一年多15小時","七天假只做到向內政部反映，勞動部提不出更積極作為，也不願強硬要求","身心障礙雇主聘看護移工仍要繳就業安定費，違反CRPD公約精神","就安基金宣導費111年1.09億、114年編列2.17億，成長將近兩倍","就安基金支應裝修辦公空間、設備升級、垃圾清運、網路行銷等雜項"],"reply":"黃維琛說工時回到疫情前的狀況、慢慢復甦回來；洪申翰說低薪讓勞工靠加班增加收入，正推動薪資透明化、調高基本工資，並希望建立勞資協商機制、跟工會簽團體協約。就業安定費部分他說有討論與檢討空間，已請發展署研議，三個月內回應；他也承認部分項目不宜由就安基金支付，會爭取擴大公務預算，資訊公開可以再做更多。","quotes":["這項規定其實被身心障礙族群稱之為障礙稅","就安基金濫用了所謂的併決算的方式，併決算等於是編列不實"],"fixed":true,"chars":6089,"followups":[]},{"gz":"GZ-11311102_00001","date":"2024-12-04","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第12次會議邀請勞動部部長針對「勞動部勞動力發展署北基宜花金馬分署事件及如何完善申訴管道之具體策進作為及期程」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/111/LCIDC01_11311102.pdf","pages":"1-222","target":["勞動部長洪申翰","勞動部"],"title":"就安基金淪小金庫 要求三個月內澈查五年支出","topics":["就業安定基金","職場霸凌","勞動部","疲勞駕駛"],"summary":"廖偉翔質疑就業安定基金變成勞動部的小金庫。他查到3,000萬補助高雄市政府辦活動的案子，是靠臨時動議先過關，隔年才由就業平等司補提4,000萬經費，形同先上車後補票；他也指出運用辦法第十二款「其他有關支出」，依大法官解釋不是空白支票，必須跟前面十一款相當，質疑辦演唱會、買咖啡這類用法完全在法之外。他要求三個月內澈查五年內支出，修法強化監督，並向全國勞工道歉。","demands":["勞動部三個月內澈查五年內就安基金用途，並公開每一筆支出明細","追究相關人士責任，該送政風送政風、該送檢調法辦絕不寬貸","修法強化就安基金的監督機制，避免再被濫用","勞動部向全國勞工和雇主道歉，並提出具體方案","重啟調查報告最晚下週五前公開；霸凌立法要講清楚期程"],"faults":["就安基金3,000萬補助案用臨時動議先過，隔年才補提4,000萬經費","「其他有關支出」依大法官解釋不是空白支票，必須跟前面十一款相當，質疑辦演唱會、買咖啡這類用法在法之外","何佩珊前部長允諾兩週內提出重啟調查報告，至今還沒出爐","政風處被反映霸凌案時回嗆對方不懂部門職掌，態度消極","霸凌專法與就安基金改革一再研議，講不出明確時程"],"reply":"洪申翰允諾澈查、配合檢調，一個月內提出就安基金把關強化方案，重啟調查報告下週公開，霸凌修法盼下會期有清楚路徑，但不道歉。","quotes":["但是現在看起來這個就安基金就變成所謂勞動部的小金庫","沒有時程就會是空話嘛"],"fixed":true,"chars":5888,"followups":[]},{"gz":"GZ-11310902_00001","date":"2024-11-28","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第11次會議一、繼續審查中華民國114年度中央政府總預算案關於環境部主管預算（公務及基金預算）；二、繼續審查環境部函送財團法人環境資源研究發展基金會等4家財團法人114年度預算書案（113年11月27日、113年11","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/109/LCIDC01_11310902.pdf","pages":"1-130","target":["環境部","環境部長彭啓明"],"title":"環境部AI與委辦費三案 要成效報告才准解凍","topics":["空氣品質","AI應用","委辦費","政策宣導預算"],"summary":"審查環境部預算，廖偉翔盯住三塊錢：空氣品質保護項下導入AI，他說聽起來好像是為了做而做，要求交代導入之後的實際成效；環境部升格後委辦費比例太高，卻又增加156名約聘人力；環境保護基金的媒體政策及業務宣導費，他指出限制型招標居多、得標廠商集中度甚高。三案他都改成凍結加報告，講清楚才准動支。","demands":["空氣品質保護AI經費凍600萬，專案報告經委員會同意後始得動支","環境部須說明導入AI與空品監測後的實際改善成效","人事與委辦費凍200萬，明確報告156人業務與委辦比例如何下降","要求環境部提出5年目標計畫與報告，通過後才解凍","環境保護基金宣導費900萬凍300萬，提成效報告書後解凍"],"faults":["空氣品質保護項下導入AI，聽起來好像是為了做而做，要求說明導入後的實際成效","升格後委辦費比例太高，同時又增加156名約聘人力","宣導費限制型招標居多、得標廠商集中度甚高"],"reply":"官員說AI只是輔助工具，希望改書面報告；部長稱人力嚴重不足、宣導費是各部會最少，凍結或送協商會影響碳費宣傳推動。","quotes":["AI 聽起來好像是為了做而做","所以如果你們的人員多了，委辦的比例就可以下降？"],"fixed":true,"chars":4327,"followups":[]},{"gz":"GZ-11310501_00008","date":"2024-11-21","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第10次會議審查中華民國114年度中央政府總預算案關於衛生福利部主管預算（公務預算及基金）（僅詢答）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/105/LCIDC01_11310501.pdf","pages":"55-140","target":["衛生福利部","部長邱泰源","署長莊人祥","署長莊聲宏"],"title":"左流右新風險要說清楚 反對放寬6項農藥標準","topics":["疫苗混打","食安","農藥標準","職場霸凌"],"summary":"廖偉翔關心左流右新混打的安全。他說施打依據是111年2月25日訂的，但國外後來的研究指混打會提高中風風險，基隆、臺東也有接種後死亡案例，疾管署卻只認接種一小時內的副作用。他要求疾管署和ACIP重新檢討，把風險講清楚，也追問衛福部霸凌案調查，並反對食藥署放寬6項農藥標準。","demands":["疾管署與ACIP的會議重新檢討左流右新","衛福部把混打風險講清楚，讓民眾自己評估要不要打","部長澄清並保證推左流右新不是為雙效疫苗做人體試驗","霸凌調查委員會組成要合理，提高外部委員比例、該迴避的人要迴避","約談主管與基層並查核LINE、mail，確認有沒有人吃案壓案"],"faults":["衛福部審議疫苗受害案，每個案例只花80秒，過程狹隘","衛福部兩招迴避責任：拿特定文獻說無關、扣潛在慢性病帽子","疾管署只認接種一小時後的副作用，等於保固只有一小時","整備組異動37%偏高，也高於疾管署13%，霸凌案原本說要查兩個月","食藥署放寬6項農藥標準，有的高於歐盟3倍、5倍"],"reply":"邱泰源說疫苗怎麼打由ACIP專家決定，保證不是為雙效疫苗做試驗，霸凌案一週內完成報告；莊人祥說會蒐集文獻再與ACIP釐清。","quotes":["我要提醒你們，不應該把人民的健康、把人民的食安放在風險之中","我想這個該辦就要辦，公務體系不應該成為官場現形記的舞台"],"fixed":true,"chars":3811,"followups":[]},{"gz":"GZ-11310201_00012","date":"2024-11-20","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議邀請勞動部部長、銓敘部、國防部、內政部警政署、內政部消防署、行政院人事行政總處、考試院、公務人員保障暨培訓委員會、教育部及國家科學及技術委員會就「職場霸凌防治與處理作業」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/102/LCIDC01_11310201.pdf","pages":"231-360","target":["勞動部部長何佩珊"],"title":"勞動部霸凌案拖4天才查，要求重做調查並嚴格迴避","topics":["職場霸凌","勞動部","調查公信力","吃案爭議"],"summary":"勞動部吳姓同仁輕生，廖偉翔追問11月4號出事、為什麼拖到11月8號才從社群媒體得知，中間4天沒啟動調查，是不是在壓新聞。他也質疑調查報告寫「目的良善」，卻沒查謝姓長官知不知道吳員加班；調查小組只有2位外部委員、占九分之二，難以取信社會。他要求重做調查、提高外部委員比例並嚴格迴避。","demands":["勞動部重做調查報告，改掉「目的良善」的錯誤用語","調查小組提高外部委員比例，外部人員也要嚴格迴避","查清謝姓長官知不知道吳員加班、工作是不是他交辦","說明為何透過黨的系統請副秘書長何博文聯絡李宇翔議員","說明現場疑似遺書的內容與霸凌有沒有關係"],"faults":["勞動部11月4號出事，拖到11月8號才從社群媒體得知","得知後拖到12號、14號才訪談，啟動調查太慢","調查沒問謝姓長官知不知道吳員加班，沒查清楚","調查小組只有2位外部委員、占九分之二，公信力不足","部長透過黨的系統聯繫爆料議員，形同間接施壓"],"reply":"部長何佩珊承認「目的良善」用語寫錯、會依委員會決議重做調查報告，也承認啟動調查太慢並道歉，但否認吃案或施壓。","quotes":["拖了4天不啟動調查原因是什麼？","這次霸凌申訴調查小組只有2位外部委員加入、只占小組的九分之二"],"fixed":false,"chars":4187,"followups":[]},{"gz":"GZ-11310001_00002","date":"2024-11-14","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第8次會議一、繼續處理中華民國113年度中央政府總預算有關衛生福利部主管預算凍結報告案2案；二、邀請環境部部長列席報告業務概況，並備質詢；三、審查中華民國114年度中央政府總預算案關於環境部主管預算（公務及基金預算）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/100/LCIDC01_11310001.pdf","pages":"85-348","target":["環境部","環境部部長彭啓明"],"title":"水質2.0編26億9,000萬　要求先講清具體目標","topics":["水質整治","氨氮削減","川廢海廢","減塑"],"summary":"廖偉翔盯河川水質治理。第1期氨氮削減計畫108到112年編約20.2億、聚焦7條河川，但嚴重污染河川從6條變9條、10條、6條又回到9條，環境部仍自評99.82%優等。他要求2.0近26億9,000萬的具體目標，審預算時要先講清楚，並點出塑膠川廢占91%，減塑不能只靠禁止。","demands":["環境部：水質2.0近26億9,000萬的具體目標，審預算時要提供出來讓大家知道","環境部：講清楚未來4年這筆經費最終要達到的數值","環境部：想辦法要求飲料品牌廠商負起減塑責任","環境部：研議補助降低有機再生生質塑料的生產成本","環境部：減塑若有進一步研究或政策，提供委員辦公室參考"],"faults":["環境部：108到112年約20.2億整治7條河川，嚴重污染河川又回到9條","環境部：計畫自評99.82%、優等，但嚴重污染程度從2.58升到3.31","環境部：懸浮固體從135.7提高到183，等於越整治越差","環境部：水質2.0不再聚焦原本這7條河川，也沒說明原因","環境部：明年減塑目標明顯達不到，傳統市場、零售商限塑遇到強力挑戰"],"reply":"環境部說治理有延續，同意提供目標；南崁溪、二仁溪工程今年上半年啟用後濃度大降；減塑推循環杯與綠色製造，生質塑料受限於價格與產量。","quotes":["這樣子經費算不算真的丟到水裡了呢？","有沒有什麼能夠提供具有誘因的政策，讓廠商也願意進行改善呢"],"fixed":false,"chars":4034,"followups":[]},{"gz":"GZ-1139301_00003","date":"2024-11-04","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議一、繼續處理中華民國113年度中央政府總預算有關衛生福利部主管預算凍結報告案1案；二、邀請衛生福利部部長針對「社區精神病患照護優化」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/93/LCIDC01_1139301.pdf","pages":"199-272","target":["衛生福利部","衛生福利部長邱泰源"],"title":"社安網預算不足、健保攤扣沒有法源","topics":["社會安全網","精神衛生","健保攤扣","人工生殖法"],"summary":"廖偉翔指出社安網二期上路後，這三年自殺人數反而節節攀升；明年總預算歲出3兆1,325億，社安網二期只有75億，不到0.24%。精神衛生法第三條沒定義心理健康促進，自閉症、情緒障礙學生畢業後未做鑑定就會被社政漏接。他也認為健保攤扣沒有法源，害醫院經營困難。","demands":["請衛福部修正精神衛生法施行細則，把心理健康促進納入並儘速列出","請衛福部研究並加強對在校輔導對象畢業後的宣導與追蹤","請衛福部提供攤扣前的健保結算資料給委員","請部長深入了解攤扣的法律授權，提出書面報告說明依據","請衛福部全面了解攤扣對醫院經營、獎金、設備與人員進用的影響"],"faults":["社安網二期編列預算後，這三年自殺人數反而節節攀升","明年歲出3兆1,325億，社安網二期只有75億，不到0.24%","精神衛生法第三條沒有定義心理健康促進，只談治療末端","衛福部公開的總額結算只有攤扣後數據，看不到真實點值","立法院主決議要達0.95，衛福部卻以提高攤扣金額處理"],"reply":"部長邱泰源說人工生殖法草案11月底送行政院，施行細則會納入心理健康促進；攤扣是各區自主管理，攤扣前資料可提供，法律授權會回覆委員。","quotes":["部長，這個問題其實也蠻久的，你們嘴巴上都一直說很重視，可是完全沒有解方。","這群人如果沒做鑑定的話，除了無法獲取福利外，更重要是社政單位會漏接"],"fixed":false,"chars":4865,"followups":[]},{"gz":"GZ-1139201_00004","date":"2024-10-30","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議邀請勞動部部長就「我國全時職位缺工概況」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/92/LCIDC01_1139201.pdf","pages":"199-276","target":["勞動部部長何佩珊"],"title":"彈性育嬰假七成六掛零 促放寬育嬰留停到6歲","topics":["缺工","育嬰留停","家庭照顧假","女性勞參率"],"summary":"廖偉翔從缺工切入，先指出實務上有雇主要求用職工福利金付員工健檢費，這已違法，要勞動部發函提醒並加強檢查。他認為女性勞參率偏低來自照顧與家務分工，但勞動部彈性育嬰留停試辦計畫有七成六單位掛零。他主張修性平法，育嬰留停從3歲放寬到6歲、家庭照顧假從7天放寬到14天，產假一併評估。","demands":["請勞動部發函提醒雇主，健檢費不得由職工福利金負擔，並加強檢查","請勞動部評估性平法第十六條育嬰留停由3歲放寬到6歲","家庭照顧假比照評估，由第二十條的7天放寬到14天","產假、育嬰假、家庭照顧假一條龍合併評估，2個月內回覆","評估後提報行政院版本，以示行政部門決心"],"faults":["勞動部彈性育嬰留職停薪試辦計畫，七成六試辦單位掛零","長照、0到6歲國家一起養等政策執行上看得到吃不到、很難用","部分雇主拗職工福利金付健檢費，勞動部檢查不夠","短期彈性育嬰假只適用0到3歲，不符家長實際需求"],"reply":"部長何佩珊承認以職工福利金付健檢費違法，坦言彈性育嬰留停成效不好，同意育嬰留停年齡、家庭照顧假與產假合併評估，2個月回覆。","quotes":["七成六的試辦單位掛零，對不對？部長。","女性不是不願意就業，而是這些牽絆跟責任導致她無法就業"],"fixed":false,"chars":3799,"followups":[]},{"gz":"GZ-1138702_00001","date":"2024-10-23","committee":"經濟委員會","agenda":"經濟委員會第7次會議一、邀請經濟部首長、環境部首長就「我國碳費徵收機制對產業衝擊之影響評估，及政府協助企業因應之配套措施」進行報告，並備質詢；二、邀請經濟部首長、環境部首長、財政部首長就「我國碳邊境調整機制（CBAM）推動規劃」進行報告，並","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/87/LCIDC01_1138702.pdf","pages":"1-52","target":["環境部次長施文真","經濟部次長連錦漳"],"title":"碳費高洩漏認定太慢 中小企業減碳協助不具體","topics":["碳費","高碳洩漏","中小企業減碳","增一氣拆一煤"],"summary":"碳費就要上路，廖偉翔追問高洩漏事業的認定準則何時公布，環境部說要等產業關聯表，明年上半年才有，他認為太慢，中間還有審查和企業配套要跑。他也問每噸300元合不合理，要經濟部講清楚中小企業的減碳協助，不要只有大方向，並要求落實臺中增一氣拆一煤的承諾。","demands":["要環境部加速公布高洩漏事業的認定準則與作業標準","要經濟部提出中小企業減碳的具體協助方案，不要只有大方針","要經濟部會後把中小企業協助的全部資料送到辦公室","要經濟部說明高碳排產業外移，資金人才外流如何因應","要經濟部落實臺中增一氣拆一煤承諾，並送台電規劃資料"],"faults":["環境部還在等主計總處產業關聯表，高洩漏認定拖到明年上半年","經濟部對中小企業只講輔導、診斷、培訓，企業還是不知道怎麼被幫","經濟部對每噸300元合不合理不表態，只說是共識決要尊重","臺中2025增氣、2026才拆機組，2031才拆三、四號燃煤，不是增一氣拆一煤"],"reply":"環境部說高碳洩漏看排放密集度與貿易密集度，準則盼明年上半年公布；經濟部說先做500家自主減量計畫，中小企業有輔導、碳盤查與培訓。","quotes":["明年上半年會不會太晚了？","現在還是很多中小企業不知道你到底要怎麼幫他們，他們也很擔心"],"fixed":false,"chars":2115,"followups":[]},{"gz":"GZ-1138901_00001","date":"2024-10-23","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第5次會議邀請衛生福利部部長、法務部、內政部、財政部、教育部列席就「有關新興煙毒品防制及強化虐童防治作為」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/89/LCIDC01_1138901.pdf","pages":"1-104","target":["衛生福利部部長邱泰源","衛生福利部國民健康署"],"title":"電子煙裁罰遠少於警方查緝，要求跨部會整合權責","topics":["電子煙","新興毒品","校園毒品","醫事機構電價"],"summary":"電子煙全面禁止一年多，街頭、校園卻到處看得到，載具和煙油都很好買。他比對數字：今年前九月衛生單位依菸害防制法裁罰電子煙違規約639件，警方7到9月光查獲喪屍煙油就有681件，是衛福部同期的2.3倍。他認為執法不力，載具和煙油的權責又在衛福部與經濟部之間推來推去，要求跨部會整合，並向委員會說清楚權責怎麼分。","demands":["衛福部給委員會一份報告，說明電子煙權責究竟怎麼分","衛福部跨部會整合加熱菸與電子煙管理，不要部會互推","衛福部加強查緝電子煙，讓學生使用比例不再上升","衛福部替諮商所、物療所、驗光所等醫事機構爭取電價凍漲","部長不要只轉函，要主動向經濟部說明醫事機構處境"],"faults":["衛福部今年前九月裁罰電子煙約639件，平均一天不到2件","警方7到9月查獲喪屍煙油681件，是衛福部同期的2.3倍","加熱菸載具歸經濟部、菸品歸衛福部，權責模糊不清","國中生、高中職生電子煙使用率2021年升到3.9%與8.8%","衛福部報告稱加強查緝就能避免電子煙彈成毒品載具，與現況不符"],"reply":"部長說菸害防制法行政程序較長，會請健康署研議改善，並跨部會合作；電價已把陳情轉給經濟部，會給業者專業指導。","quotes":["我想執法不力是最大的一個原因之一。","我希望你不要成為一個總機，不要只是轉過去就好"],"fixed":false,"chars":4352,"followups":[]},{"gz":"GZ-1138501_00002","date":"2024-10-17","committee":"經濟委員會","agenda":"經濟委員會第6次會議邀請農業部部長就「農業部對於立法院決議提高公糧收購價格之評估與執行方案」進行報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/85/LCIDC01_1138501.pdf","pages":"107-192","target":["農業部部長陳駿季"],"title":"班班有鮮乳招標價過低，飼料抗生素該跟上歐盟禁用","topics":["班班有鮮乳","酪農產業","抗生素抗藥性","飼料添加物"],"summary":"廖偉翔追問班班有鮮乳會不會轉向停辦，要農業部把話說清楚。他指出鮮乳生產排程至少一年，政策卻想兩、三個月內上路，冷鏈配套不足；保久乳每瓶14元、鮮乳每瓶16元的招標價偏低，業界認為一瓶至少19元，小酪農和羊乳產業先受害。他也質疑抗生素減用目標一年拖一年，要求跟上歐盟並送檢討報告。","demands":["農業部說清楚班班有鮮乳未來會不會持續執行，別讓校長猜。","農業部與教育部一併檢討招標價格與冷鏈等配套。","農業部輔導不含乳糖的乳品，國人乳糖不耐比例高達88%。","農業部研議牛奶兌換券並配合超商通路。","農業部檢討飼料抗生素減用年度目標，報告送一份到辦公室。"],"faults":["農業部：鮮乳生產排程至少一年，卻想在兩、三個月內完成。","農業部：保久乳每瓶14元、鮮乳每瓶16元，低於業界認為的19元。","農業部：政策沒嘉惠酪農，小酪農和羊乳產業反而先被弄死。","農業部：說班班喝鮮奶不及年產量5%、與去化生乳無關，避重就輕。","農業部：歐盟2006年全面禁用，我國飼料仍有19種抗生素可用。"],"reply":"陳駿季說會規劃好的方案跟院報告，價格與配送方式會統一完整處理；抗生素要有替代方式並與衛福部協調排序，允諾檢討衡量標準與年度目標。","quotes":["反倒是小酪農跟羊乳產業先被這個政策弄死","而是一年拖一年，你們這些年度目標其實是非常的緩慢"],"fixed":false,"chars":2316,"followups":[]},{"gz":"GZ-1138601_00006","date":"2024-10-17","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議一、邀請勞動部部長就「如何提升移工問題諮詢與申訴處理效能，並重視與建立移工的社會支持系統」進行專題報告，並備質詢；二、邀請勞動部部長、行政院人事行政總處就「如何有效提升國內薪資水準，落實保障政府機關單位內勞","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/86/LCIDC01_1138601.pdf","pages":"363-430","target":["勞動部長何佩珊"],"title":"移工障礙稅與加班免稅　要勞動部替勞工爭取","topics":["移工","身心障礙","加班費免稅","低薪"],"summary":"廖偉翔關心兩件事。一是身心障礙者聘僱家庭看護移工仍要繳每月2,000元就業安定費，被稱為障礙稅，不合CRPD公約精神，要求以子法或函釋免繳或減繳。二是加班費免稅只到46小時，加班超過46小時的人口將近3%、大約33萬勞工，要求勞動部向財政部爭取放寬，並把伙食費免稅額提高到3,000元。","demands":["請勞動部會同衛福部評估身心障礙雇主免繳或減繳每月2,000元就業安定費","評估結果要送到廖偉翔服務處","請勞動部代勞工向財政部爭取放寬46小時加班費免稅範圍","請勞動部一併反映伙食費免稅額從每月2,400元提高到3,000元","請勞動部持續追蹤電價調漲後的薪資與CPI變化及修法加薪成效"],"faults":["勞動部忽略藍領製造業這群確實需要加班的勞工，他們想多賺錢卻還被多課稅","勞動部拿免稅上限抑制加班，卻不敢修法直接禁止超過46小時","勞動部只看今年1至8月薪資數據，忽略經常性薪資已連3年負成長","就業安定費未依CRPD精神考量身心障礙者處境，只看家庭收入"],"reply":"何佩珊允諾會同衛福部評估身心障礙者免繳就業安定費，加班費與伙食費免稅額向財政部反映研議，並會持續追蹤薪資與CPI數據。","quotes":["這些障礙者自力救濟聘僱移工的時候，卻反而被國家收障礙稅","我要請部長正視這個需求的存在、這個群體的存在"],"fixed":true,"chars":3835,"followups":[]},{"gz":"GZ-1138401_00017","date":"2024-10-16","committee":"經濟委員會","agenda":"經濟委員會第5次會議邀請經濟部部長率台灣電力股份有限公司董事長就「我國電力能源配比執行現況與未來規劃」進行報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/84/LCIDC01_1138401.pdf","pages":"209-304","target":["經濟部部長郭智輝","台灣電力股份有限公司"],"title":"批能源配比打假球，要求務實調整拚企業競爭力","topics":["能源配比","碳費","電價","核能"],"summary":"廖偉翔質疑經濟部的能源配比像打假球，硬撐天然氣50%卻說不出何時會改變，能源發展綱領8年都沒調整。他指出碳費範疇二算的是間接能源，錯誤的配比會削弱國內廠商的國際競爭力。他也追問藥廠因電價調漲把所有藥乘以1.1賣給藥局，衛福部長到底有沒有來溝通，並要求部長務實幫企業解決問題。","demands":["要求經濟部務實調整能源配比，別讓企業在國際上失去競爭力","要求部長說明天然氣50%的配比到底何時會改變","要求經濟部說明衛福部長有沒有就藥廠電價問題來溝通","要求部長把赴菲律賓、日本設電廠的說法講清楚，別讓人民恐慌"],"faults":["經濟部：能源發展綱領8年沒調整，只拿滾動式調整當答案","經濟部：碳費範疇二受錯誤能源配比拖累，削弱國內廠商競爭力","經濟部：藥局陳情電價問題，衛福部長並沒有直接跟部長溝通","經濟部：菸草和醫療診所新聞一爆出來就馬上轉彎","部長在這個時間點拋出赴菲律賓、日本設電廠，讓人民恐慌"],"reply":"郭智輝說政策會隨時間改變、會滾動式討論；藥局沒有漲價，赴菲設廠與國內綠電無關，並為自己言語不夠精準道歉。","quotes":["現在的能源配比就好比在打棒球賽一樣，根本就是硬要堅持這樣做，是打假球的行為","目前沒有辦法讓這些企業在國際上有競爭力，單就範疇二的部分"],"fixed":false,"chars":2638,"followups":[]},{"gz":"GZ-1138401_00018","date":"2024-10-16","committee":"教育及文化委員會","agenda":"教育及文化委員會第4次會議一、邀請教育部部長鄭英耀列席報告業務概況，並備質詢；二、審查113年度中央政府總預算有關教育部主管預算解凍案11案","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/84/LCIDC01_1138401.pdf","pages":"305-394","target":["教育部部長鄭英耀"],"title":"班班喝鮮乳僅7%喝到鮮乳，要求年底過半、檢討訂價","topics":["班班喝鮮乳","冷鏈物流","學童營養","老舊校舍"],"summary":"廖偉翔追問班班喝鮮乳的成效。他指出大臺中只有7%選鮮乳、93%喝保久乳，卡在冷鏈與物流不足；中央又訂保久乳14元、鮮乳16元，低於18元行情，怕廠商供應低品質乳品。他要求結合超商賣場冷鏈，年底鮮乳過半、明年重簽約達70%，並重新檢討價格，也追問老舊校舍補強沒編預算。","demands":["教育部結合超商、賣場冷鏈，年底鮮乳比例拉過50%","明年重新簽約時，鮮乳比例要提高到70%","提供無乳糖鮮奶，照顧乳糖不耐體質的學童","會後把這些新措施的評估報告送給委員","說明50年以上校舍重建經費，及350億元何時核定"],"faults":["教育部：班班喝鮮乳落實度偏低，大臺中只有7%選鮮乳","冷鏈與物流不足，93%學童喝到的是保久乳","中央訂保久乳14元、鮮乳16元，低於18元的鮮乳行情","政策由農業部發起，教育部與農業部看起來互相甩鍋","2022年後中央沒提老舊校舍補強專案，也沒編相關預算"],"reply":"部長鄭英耀說會朝委員方向努力，價格與分裝配送成本一併檢討，無乳糖選項由農業部滾動式修正，校舍經費會後書面報告。","quotes":["我只是要說應該跟他們合作，想辦法努力在年底達成50%以上吧？","確實是它發起的，可是現在看起來好像在互相甩鍋。"],"fixed":false,"chars":1975,"followups":[]},{"gz":"GZ-1138501_00001","date":"2024-10-16","committee":"交通委員會","agenda":"交通委員會第6次會議邀請交通部部長陳世凱列席報告業務概況，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/85/LCIDC01_1138501.pdf","pages":"1-106","target":["交通部部長陳世凱","臺鐵董事長杜微"],"title":"臺鐵起薪三萬四留不住人 要求加薪基層優先","topics":["臺鐵","基層薪資","軌道安全","加蓋機車"],"summary":"廖偉翔關心臺鐵基層待遇。他指出臺鐵新進人員起薪只有三萬四，比不上中華郵政四萬一、港務公司四萬七，工作環境辛苦又缺裝備，造成新人招不到、舊人留不住，維修和安檢人力補不齊也會影響安全。他要求加薪以基層優先，改掉高層高薪、基層低薪。他也要求交通部盡快處理加蓋機車的分類與路權。","demands":["交通部盡快與人事總處敲定臺鐵從業人員加薪方案，基層優先。","臺鐵加薪方案定案後，把版本提供給委員。","交通部改善高層高薪、基層低薪，別讓軌道安全有嘴無心。","加蓋機車修法時考慮納為大型重機紅黃牌，比照汽車路權。","會後提供加蓋機車研議進度、方向與跟地方政府討論的要點。"],"faults":["臺鐵新進人員起薪三萬四，低於中華郵政四萬一、港務公司四萬七。","基層還沒加薪，臺鐵董事長就先調薪40%，影響基層感受。","臺鐵未滿十年年資員工長年在五成上下，人才留不住。","臺鐵說不清楚維修與安檢人員缺額多少、要多久才補得齊。","加蓋機車若只研議歐盟L5三輪，二輪加蓋機車恐無法可依。"],"reply":"部長說加薪基層優先，方案已擬好、正與人事總處溝通，定案後提供委員；加蓋機車建議列入討論，會後給資料。","quotes":["希望部長能夠改善高層高薪、基層低薪，千萬不要軌道安全有嘴無心","對於新興和有創意的產品，我都主張行政機關應該要鼓勵多元發展"],"fixed":false,"chars":2572,"followups":[]},{"gz":"GZ-1138601_00005","date":"2024-10-16","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議邀請勞動部部長列席報告業務概況，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/86/LCIDC01_1138601.pdf","pages":"265-362","target":["勞動部","勞動部部長何佩珊"],"title":"缺工結構化與年齡歧視，要勞動部一個月內提檢討報告","topics":["缺工","中高齡就業","技職教育","加班免稅"],"summary":"廖偉翔從勞動部人力需求調查切入，指出約6.6萬個職缺半年以上補不到人，製造業占2.1萬個，工業部門缺額46.2%，已經是結構問題。他要勞動部提出方向，包括提高婦女勞參率與中高齡者退休後就業，並指職場年齡歧視嚴重，有83%的人感受到差別待遇。他也批評技職選手被大小眼。","demands":["請勞動部一個月內提供中高齡年齡歧視的檢討報告與改進措施","勞動部應提高婦女勞參率、推動中高齡者退休後就業","技職選手出國與公開場合的接送、住宿待遇要比照辦理","請勞動部代表勞工與財政部協調，重新解釋加班免稅範圍","加班免稅的研議結果，一個月內以書面報告給委員"],"faults":["勞動部對半年以上的結構性缺工，只談個別職業放寬，缺整體方向","中高齡專法上路後，職場年齡歧視仍普遍，去年裁罰40件逾千萬元","國慶巡禮一開始不讓技職選手參加，散場還要他們自己搭捷運","選手出國比賽，單人房給行政人員，選手和翻譯住雙人房","工業部門缺額占46.2%，反映技職培育的重要性不夠受重視"],"reply":"何佩珊說缺的是中階技術人力，8月以來已放寬中階技術人才與僑外生；否認有大小眼；加班免稅部分承諾研議後書面回覆。","quotes":["口口聲聲說很重視，但是實際行為卻是這樣子","你們嘴巴上說的重視，請真的也落實到各個地方"],"fixed":false,"chars":3643,"followups":[]},{"gz":"GZ-1138201_00002","date":"2024-10-14","committee":"交通委員會","agenda":"交通委員會第5次會議邀請交通部、交通部鐵道局、交通部運輸研究所、國營臺灣鐵路股份有限公司、台灣高速鐵路股份有限公司及國家運輸安全調查委員會就「臺灣鐵道安全提升計畫」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/82/LCIDC01_1138201.pdf","pages":"31-98","target":["交通部次長伍勝園","國營臺灣鐵路股份有限公司董事長杜微"],"title":"臺鐵高層先漲40%基層沒漲，要求補基層薪資與安全數字","topics":["臺鐵公司化","基層薪資","鐵道安全","準點率"],"summary":"臺鐵新進人員起薪3萬4,221元，低於中華郵政4萬1,750元和港務公司四萬七千多元，高層卻先漲40%。廖偉翔說待遇差導致新人招不到、舊人留不住，未滿十年年資者長年五成上下，宜花東最高56%，也影響行車安全。他發現年報112年刪掉事故件數欄位，要求說明，並把各站準點率納入統計。","demands":["請交通部盡快想辦法幫臺鐵基層從業人員調薪","杜微回去查清楚，說明年報112年為何沒有事故件數","臺鐵把中途各站準點率也納入統計，作為改進參考","平交道事故要實質討論如何改善，讓未來數字下降","準點率95%到97%的目標不變，要努力達成、不要亂開支票"],"faults":["臺鐵高層漲40%，基層薪資沒漲，打擊基層士氣","臺鐵起薪3萬4,221元，落後中華郵政、港務公司","留不住人，未滿十年年資者長年五成上下，宜花東到56%","臺鐵年報112年刪掉事故件數欄位，過去幾年都有公布","平交道事故長期是日本JR的兩倍，次長卻先怪民眾闖越"],"reply":"杜微說高層依國營事業續薪要點辦理，年報沒有要隱瞞、回去查，願意加做各站準點率統計；伍勝園說營收有盈餘後就是加薪時機。","quotes":["你們自己高層漲了 40%，基層卻沒漲","在臺鐵公報、年報上居然在 112 年刪除了此欄，為什麼會這樣？"],"fixed":false,"chars":2849,"followups":[]},{"gz":"GZ-1138301_00001","date":"2024-10-14","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議邀請環境部部長、經濟部就「台灣的碳費收費標準決議」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/83/LCIDC01_1138301.pdf","pages":"1-132","target":["環境部部長彭啓明","經濟部"],"title":"碳費上路卻卡在CBAM折抵，要求碳費多分給地方","topics":["碳費","歐盟CBAM","能源轉型","地方補助"],"summary":"碳費上路，廖偉翔追問和歐盟CBAM怎麼接軌：折抵成數還沒談定，出口廠商可能得再向CBAM買憑證。他指能源結構碳排係數過高，天然氣拉到50%又排除核能，企業範疇二成本越背越重。他也質疑要企業明年6月30日前交自主減量計畫太趕，並要求碳費多分給承受污染的地方。","demands":["要求環境部和經濟部盡快訂出排放量調整係數與高洩漏係數","要求說明投入多少資源，協助企業達到每噸50元的A方案","要求盡快公告碳費支用辦法與獎補助地方政府的比例","要求碳費從寬補助地方，尤其碳排設施嚴重的台中","要求環境部帶回去做跨部會整合，輔導出口歐盟的廠商"],"faults":["環境部說CBAM折抵成數細節要等明年年中，廠商無法及早因應","能源政策天然氣拉到50%又排除核能，企業範疇二成本越背越重","要企業明年6月30日前提交自主減量計畫，時程壓縮太趕","溫管基金60億用B方案估算，和希望企業走A方案的目標矛盾","台電碳費轉嫁到消費者，中火所在地方只留一億多"],"reply":"彭啓明說CBAM細節明年年中才明朗，明年派駐人協商；燃煤改燃氣排碳減三分之一，企業有專線和巡迴說明會輔導，地方分配會列入考慮。","quotes":["可是你們要求企業在6月30日以前提交自主減量計畫，會不會有點太強人所難？","我們的能源政策不變，還是增加了它很多的成本和降低了它的競爭力"],"fixed":false,"chars":4013,"followups":[]},{"gz":"GZ-1138201_00005","date":"2024-10-09","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請衛生福利部部長就「我國人工生殖法制化作業進度」、「衛生福利部落實中央政府我國少子女化對策計畫之成效與未來規劃」及「衛生福利部本月因疏於督導地方評估特殊需求兒少利益所受監察院糾正之檢討」進行專題報告，並備","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/82/LCIDC01_1138201.pdf","pages":"257-346","target":["衛生福利部","衛生福利部部長邱泰源","疾管署"],"title":"藥價案久拖、電價漏掉藥局，疫苗救濟別再黑箱","topics":["藥價調整","電價調漲","疫苗救濟","福祉車免稅"],"summary":"廖偉翔盯三件事。一是藥價調整案，健保署共擬會議8月15日就通過，卻遲遲沒預告也沒公告，他要部長給時間點。二是電價調漲，醫院全額漲、菸草業卻凍漲或減半，製藥業和社區藥局又被漏掉，藥商10月起產品漲一成，最後轉嫁到用藥人。三是新冠疫苗救濟審查不錄音、不公開文獻，他要求公開透明。","demands":["衛福部把藥價調整案排入預告，一個月內完成","衛福部支持貨物稅條例第十二條修正，福祉車免稅延長5年","部長趕在10月16號新電價上路前，主動向經濟部反映","衛福部替製藥業、社區藥局爭取電價免漲或凍漲","疾管署疫苗救濟審查會議錄音保存並公開參考文獻"],"faults":["共擬會議8月15日通過藥價案，至今沒公告連預告都沒開始","電價調漲醫院全額漲，衛福部沒主動去跟經濟部協調","製藥業和藥局被遺漏，藥商10月起漲價10%轉嫁民眾","社區藥局疫情時發口罩快篩，主責機關這次卻沉默","疫苗救濟2個小時審完90件、平均80秒一件，還不肯公開錄音"],"reply":"邱泰源說沒感受到外界壓力，希望一個月內預告；福祉車免稅已簽請延長5年；願主動向經濟部反映；疫苗案會整理報告，能公開的儘量公開。","quotes":["為何遲遲沒有公布，是背後有什麼力量干預嗎？","我真的要強烈指責衛福部跟疾管署，如果連這麼基本的公開透明都做不到"],"fixed":false,"chars":4716,"followups":[]},{"gz":"GZ-1137901_00004","date":"2024-10-07","committee":"內政委員會","agenda":"內政委員會第3次會議一、殯葬管理條例：(一)審查委員丁學忠等16人擬具「殯葬管理條例第二十一條之一條文修正草案」案、(二)審查委員張嘉郡等29人擬具「殯葬管理條例第二十一條之一條文修正草案」案、(三)審查委員劉建國等16人擬具「殯葬管理條例","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/79/LCIDC01_1137901.pdf","pages":"87-164","target":["內政部","內政部長劉世芳","署長吳欣修"],"title":"租金補貼265億不等於社宅達標，實價登錄要真透明","topics":["居住正義","社會住宅","租金補貼","租屋實價登錄"],"summary":"廖偉翔追問租金補貼和社會住宅進度。他說租金補貼已核准將近66萬戶、今年超過265億元，未來每年恐怕都要編列近300億元，但這不等於50萬戶社會住宅達標。租屋實價登錄只有十萬四千多筆，又去識別化到看不出坪數、屋齡、電梯，資料形同無用。他要求補進問卷，也要部長承諾100萬戶政見。","demands":["要內政部把屋齡、有沒有電梯等欄位加進租屋實價登錄問卷","要租屋實價登錄繼續優化，真正做到租屋市場透明化","要部長簽下100萬戶承諾：50萬戶租金補貼、25萬戶包租代管、25萬戶社宅","要署方保證4年任期內完成25萬戶社宅並可以招租","他會持續追蹤內政部所謂務實推進的進度"],"faults":["內政部拿租金補貼戶數充當50萬戶社宅達標，數字混淆","租屋實價登錄只有十萬四千多筆，不到總量20%，資料庫不完備","去識別化後看不出坪數、屋齡、有無電梯，透明化目標落空","中央完工可招租的只有林口和龍岡好室，林口扣掉選手村約一千八百多戶","過去承諾的居住正義和社會住宅跳票，部長答不出中央完工戶數"],"reply":"劉世芳說承諾沒有廉價高價之分，會務實推進百萬戶租屋家庭扶助計畫；吳欣修說租金補貼不等於社宅，住都中心每年發包1萬5到2萬戶。","quotes":["基本上你去識別化等於這些數字根本沒什麼用","我會持續追蹤，看你們所謂的務實進度是怎樣。"],"fixed":false,"chars":8387,"followups":[]},{"gz":"GZ-1138001_00002","date":"2024-10-07","committee":"司法及法制委員會","agenda":"司法及法制委員會第3次會議邀請司法院秘書長、法務部部長、內政部警政署、衛生福利部率所屬相關單位列席就「憲法法庭113年度憲判字第8號判決宣示相關法令之檢討與修正」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/80/LCIDC01_1138001.pdf","pages":"89-156","target":["司法院","法務部","內政部警政署"],"title":"八道生死門形同實質廢死，要求說清最嚴重犯罪標準","topics":["死刑存廢","憲法法庭判決","治安","監所受刑人身心"],"summary":"針對憲法法庭113年度憲判字第8號判決，廖偉翔認為新增的八道條件等同實質廢死。他指出，只要被告在審判或服刑期間出現身心狀況就不能判死，而長期監禁本來就容易出狀況。他也追問「最嚴重犯罪情節」到底怎麼認定，質疑判決替犯罪成本設了上限、會讓治安變壞，並要求司法院說明報告所稱的共識何時形成。","demands":["要求司法院說明「最嚴重犯罪情節」到底怎麼認定、有無比較方法","要求司法院說明報告所稱的共識何時才會形成","要求警政署與法務部正視犯罪成本被設上限、治安敗壞的疑慮"],"faults":["司法院代理秘書長對受刑人出現身心狀況的比例避而不答","矯正署長答非所問，只談毒品犯與健保就診，未回應提問","憲判字第8號的八道條件形同實質廢死，一般民眾無法接受","判決可能製造檢警與司法院之間的矛盾"],"reply":"法務部長說死刑制度仍維持，現在也還是有判死刑；司法院代理秘書長說，所謂的共識是假設法務部訂定包含最嚴重犯罪要具體化的刑法第五十七條甚至第六十三條的規定，司法院會配合法務部去研究。","quotes":["這個憲法判決等於是讓犯罪的成本有上限","大法官滿紙的荒唐、人民一把心酸淚"],"fixed":true,"chars":2186,"followups":[]},{"gz":"GZ-1138201_00004","date":"2024-10-07","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請環境部部長針對「垃圾裸露堆置及災後垃圾妥善處理對策」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/82/LCIDC01_1138201.pdf","pages":"173-256","target":["環境部","環境部部長彭啓明"],"title":"垃圾山只是暫時處置，廖偉翔要求拿出完全去化路線","topics":["垃圾山","資源循環","減塑","颱風假"],"summary":"環境部報告，裸露垃圾掩埋場從112年的53場、84萬噸，降到今年8月的49場、72萬噸。廖偉翔說，這是靠掩埋覆土和篩分打包做到的暫時處置，不是完全去化。他要求部長把3年、也就是116年的目標往完全去化推進，也要限制國外垃圾以產業原料名義進口，兩個月內交資料。","demands":["要求環境部兩個月內把國外垃圾進口相關資料和報告交給他","要求環境部找經濟部討論，限制國外垃圾以產業原料名義進口","要求環境部盤點減塑政策，找民怨更少、更方便的做法","要求垃圾掩埋場加設移動式水塔，能快速撲滅垃圾山火災","要求部長不要停在3年妥善處理，要往84萬噸完全去化努力"],"faults":["環境部處理裸露垃圾只做掩埋覆土和篩分打包，不是完全去化","環境部的資源循環園區還只是想法，沒有具體規劃和細節","垃圾掩埋場的消防設備沒有全面設置，只有高風險場才有","減塑政策每次推廣都產生民怨，也讓店家多了無形負擔"],"reply":"部長說3年、也就是116年可讓84萬噸妥善處理完，已全面發包，完全去化要靠資源循環園區，還在構想階段要爭取預算；署長說未來3年投入12億。","quotes":["我希望部長可以再往未來完全去化的方向努力","我覺得不應該怪罪地方的首長或是民眾"],"fixed":false,"chars":3680,"followups":[]},{"gz":"GZ-1137901_00006","date":"2024-10-07","committee":"經濟委員會","agenda":"經濟委員會第3次會議一、邀請國家發展委員會主任委員列席報告業務概況，並備質詢；二、邀請國家發展委員會主任委員、經濟部次長就「我國政府對新創及中小企業扶植政策執行狀況與未來精進措施（含政策、人才、法制、稅制、資金、區域平衡等六大面向）」進行報","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/79/LCIDC01_1137901.pdf","pages":"237-290","target":["經濟部次長何晉滄","國家發展委員會主任委員劉鏡清"],"title":"電價漲14%恐轉嫁物價 要求重估衝擊並讓藥局凍漲","topics":["電價","物價通膨","中小企業與新創","社區藥局"],"summary":"工業電價調漲14%，波及的不只科技文創，還有零售、娛樂、旅宿等中小企業和新創。他指出三年來已累積漲66.27%，業者會有預期心理和預防性轉嫁，經濟部只估0.03%是低估，且只算今年沒估明年。他也提9月核心通膨1.82%、總體約2.5%，主張統合估算講清楚，並把社區藥局納入凍漲。","demands":["請經濟部密切注意電價調漲帶來的預期心理與預防性轉嫁","請經濟部估算電價調漲對明年物價的影響","請經濟部與國發會統合估算，確定電價對CPI影響有多少","請國發會與農委會討論颱風災損後的物價穩定措施","請經濟部把社區藥局納入電價凍漲範圍"],"faults":["經濟部估0.03%只算今年，對明年物價影響目前沒有估算","經濟部說法與主計總處、央行的估算模型不一致，落差大","經濟部未正視三年累積漲66.27%造成的預期心理"],"reply":"次長何晉滄說對物價影響有限、明年會再估算；主委劉鏡清說模型跑出約0.18，是認定基準不同；次長轉述台電，藥局是表單用電應不受影響。","quotes":["我覺得這個0.03%應該是低估了","是不是這個真正的通膨怪獸在10月份之後才會來呢？"],"fixed":false,"chars":1753,"followups":[]},{"gz":"GZ-1137701_00013","date":"2024-09-30","committee":"交通委員會","agenda":"交通委員會第3次會議邀請行政院公共工程委員會主任委員陳金德列席報告業務概況，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/77/LCIDC01_1137701.pdf","pages":"293-350","target":["行政院公共工程委員會主任委員陳金德"],"title":"臺中捷運藍線審查拖太久，要求年底前完成基本設計","topics":["臺中捷運藍線","重大公共工程","工程發包","預算編列"],"summary":"廖偉翔關心臺中捷運藍線進度。他指出藍線總工程經費高達一千六百多億、工期長達十年，希望2034年完工，越早動工越能省經費。他要求工程會一個月內完成基本設計核定、年底以前完成審查，並協調交通部明年編列預算、成立專門工作小組定期開會，另要求寬列物調費與預備費，避免物價變動造成經費不足或流標。","demands":["工程會一個月內完成捷運藍線基本設計核定","確保年底以前完成基本設計審查，接著細部設計","協調交通部明年預算編列充分考慮藍線需求","成立專門工作小組定期開會，建立溝通機制","寬列物調費與預備費，並協助土建、機電發包"],"faults":["審查一來一回、回去又要修正，時程已拖非常久","招標未因應原物料大幅變動，經費不足、廠商不願投標"],"reply":"陳金德說補正後一個月內可完成基本設計核定，年底前沒問題；會跟交通部等部會討論預算，重大公建列管開督導會報，物調部分核實編列。","quotes":["越晚動工，經費的變動性就越高","拜託你在藍線捷運上繼續幫我們盯緊進度"],"fixed":false,"chars":1801,"followups":[]},{"gz":"GZ-1136801_00002","date":"2024-07-01","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第23次會議邀請衛生福利部部長就「有關健保合理支付、保障醫護人員收入、設置百億癌症基金及健康投資等事項」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/68/LCIDC01_1136801.pdf","pages":"45-118","target":["衛生福利部部長邱泰源","署長吳昭軍"],"title":"大腸癌篩檢下修到40歲，健保專款與點值都要補","topics":["癌症篩檢","大腸癌","健保點值","癌症新藥基金"],"summary":"廖偉翔關心癌症篩檢與健保點值。他指出大腸癌死亡年齡下探，現行50歲才能做糞便潛血篩檢，美國癌症醫學會2021年已下修到45歲，主張我國研議降到40歲；也點出追陽率僅八成，篩出來卻沒回診。健保部分，他要求癌症治療品質改善專款從5.17億再提高，並建議用特別條例、特別預算短期補點值。","demands":["請衛福部研議大腸癌篩檢年齡從50歲下修到40歲","3個月內把下修篩檢年齡的研議報告提供給委員","明年總額裡的癌症治療品質改善專款要比今年5.17億提高","第二、三季點值掉到0.9以下時，今年要比照去年額外補點值","用特別條例、特別預算在三年內先補健保，不要只等長期改革"],"faults":["衛福部對下修篩檢年齡只說還在討論，沒有提出時程","癌症篩檢追陽率僅八成，陽性個案跑掉沒有回診追蹤","癌症新藥給付與國際治療指引對照，多數項目仍未給付","健保改革全是長期作法，對已經哀鴻遍野的醫界緩不濟急"],"reply":"邱泰源說會儘速研議，3個月內提出研議報告；點值比照去年爭取補助；癌症新藥基金明年以公務預算擴充到60億，第三年到100億。","quotes":["既然在討論，那是不是要有一個時程？不然一直在討論，對不對？","明年總額裡面這部分的專款是否要再提高？"],"fixed":false,"chars":4573,"followups":[]},{"gz":"GZ-1136601_00013","date":"2024-06-27","committee":"社會福利及衛生環境委員會","agenda":"一、社會福利及衛生環境委員會報告併案審查委員林德福等19人、委員楊瓊瓔等16人、委員馬文君等25人、委員黃建賓等20人、委員盧縣一等17人、委員鄭正鈐等17人、委員王育敏等17人、委員張嘉郡等30人、委員王鴻薇等22人、委員鄭天財SraKa","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/66/LCIDC01_1136601.pdf","pages":"333-354","target":["勞動部"],"title":"開放家庭聘僱移工與長照應分開看，要求部會拿數據","topics":["外籍看護移工","巴氏量表","長照","女性勞參率"],"summary":"廖偉翔認為家庭想聘外籍看護照顧長者是真實的民意需求，不該和長照綁在一起。他說巴氏量表是家庭有能力就自費請人，反而可能減輕長照壓力，讓真正需要的人用得到；移工人力不夠是勞動部要解決的事。他也質疑五十幾萬人不見得都會申請，要求部會協商前做調查、研究甚至民調，提出具體數據。","demands":["要求部會在協商前做調查、研究甚至民調，提出具體數據","要求勞動部解決移工人力不足，別和開放需求混為一談","要求執政黨檢討長照制度，讓真正需要的人接得住","要求部會說明勞動部到底什麼時間點可以真正做到"],"faults":["部會把開放移工和衝擊國內勞動市場綁在一起，找理由不想過","次長舉日本、韓國都開放，卻又拿衝擊勞動市場當反對理由","部會沒掌握到底多少比例的人會自費申請，缺乏調查數據","國人不健康餘命遠長於歐美，長照未能接住真正需要的人"],"reply":"","quotes":["勞動部要去解決的，但是有這個需求就應該要為我們人民來推動","可是為什麼他們還是要這樣做？很簡單，就是有這個需求。"],"fixed":false,"chars":1254,"followups":[]},{"gz":"GZ-1136401_00014","date":"2024-06-19","committee":"社會福利及衛生環境委員會","agenda":"一、社會福利及衛生環境、司法及法制兩委員會報告併案審查「兒童及少年性剝削防制條例部分條文修正草案」等36案；二、逕付二讀：委員張嘉郡等23人、委員李彥秀等16人、委員羅廷瑋等16人、委員翁曉玲等22人、委員洪孟楷等19人、台灣民眾黨黨團、委","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/64/LCIDC01_1136401.pdf","pages":"359-392","target":["衛生福利部","衛福部部長邱泰源"],"title":"健保改革拖太久，要求衛福部儘速提具體方案","topics":["健保","醫療點值","血汗醫護","醫療體系"],"summary":"廖偉翔說健保已經到了不得不改的時候，卻一直拖著沒動，血汗醫護和醫療體系的問題大家都看得到。他在會期初提過健全醫療發展特別條例，用特別預算保障0.95、為期三年，當時行政單位有各種問題甚至攻擊，卻沒提出相應解方。他要求衛福部儘速協商，拿出大家可以滿意的具體方案。","demands":["要求衛福部儘速來協商，提出解決醫療體系問題的具體方案","要求行政院、衛福部提出可以解決現在問題的相應方案"],"faults":["衛福部：健保說要改拖了很久，至今拿不出具體方案","行政院、衛福部：對在野黨提的解方有各種問題甚至攻擊","保障1點1元茲事體大，不是修一條法條就能解決"],"reply":"部長邱泰源說行政部門一直在研究可行性；署長石崇良說總額內公衛支出改由公務預算支應、爭取癌症新藥基金，下半年先保障偏鄉燈塔型醫院。","quotes":["健保已經到了不得不改的時候，可是其實已經拖了很久","這些醫護、醫療體系先倒，最終其實倒楣的是人民啦"],"fixed":false,"chars":5392,"followups":[]},{"gz":"GZ-1136001_00003","date":"2024-06-06","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第20次會議邀請環境部部長就「廢棄物暫存量逐年攀升，廢棄物處理政策短中長程規劃」進行專題報告，並備質詢（113年6月5日、113年6月6日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/60/LCIDC01_1136001.pdf","pages":"131-218","target":["環境部","部長彭啓明","署長賴瑩瑩"],"title":"營建廢棄物黑數失控　要求環境部查清真實流向","topics":["營建廢棄物","棧仔場","廢棄物流向追蹤","違法棄置"],"summary":"廖偉翔聚焦營建廢棄物的黑數。官方統計全臺一年約214萬公噸，但媒體追蹤新北的棧仔場，一年就進了126萬噸，臺中加新北合計239萬公噸，已大於官方全臺數字；經濟部網站的數字更高達7,000萬噸，兩邊兜不起來。他認為環境部沒有真正掌握流向，要求跨部會查清楚，會後給辦公室報告。","demands":["要求環境部跨部會釐清營建廢棄物真實數量，會後給辦公室一份報告","要求環境部把黑數、流向不明與違法傾倒的詳細資料整理給辦公室","要求棧仔場2026年全面落日轉型的進度如期達成","要求新上線的營建及裝潢廢棄物流向管理平台真能掌握流向、不被作假","要求環境部說明環評細目及範圍認定標準修正何時預告，納管地面型光電"],"faults":["環境部宣稱已掌握流向，但家戶裝修廢棄物從產生源就沒掌握","未合法登記的棧仔場沒有廢棄物統計，形成大量黑數","環境部與經濟部公布的營建廢棄物數量落差極大，未跨部會勾稽","台61線臺中彰化雲林嘉義段周邊超過300個棄置點，65%在農業與養殖用地","今年查獲亂倒並上新聞的已有15件，查獲不該被當成績效"],"reply":"彭啓明承認數量對不上是個問題，答應提供報告；賴瑩瑩說正推動棧仔場合法化納管，並以產生源證明文件管制清運業者；光電環評標準預計6月底公告。","quotes":["其實我要跟你說，完全錯誤，你們這裡有非常大的漏洞","你有辦法有效地掌握廢棄物的流向嗎？能夠保證未來不會被作假"],"fixed":false,"chars":3909,"followups":[]},{"gz":"GZ-1136001_00002","date":"2024-06-05","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第20次會議邀請衛生福利部部長、外交部就「2024年我國參與世界衛生大會（WHA）之經過、檢討與展望」進行專題報告，並備質詢（113年6月5日、113年6月6日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/60/LCIDC01_1136001.pdf","pages":"61-130","target":["衛生福利部部長邱泰源","署長石崇良"],"title":"新藥給付限縮又醫院關床　要衛福部面對數據提解方","topics":["健保新藥給付","臨床試驗","醫院關床","護理人力"],"summary":"廖偉翔關心健保為了控制藥費限縮新藥給付，讓給付條件和國際臨床指引脫節，病人被迫自費、醫師難開藥，臺灣也逐漸被國際新藥開發市場忽視。他也點出醫院關床，有區域醫院關了三成病床，病人塞在急診，衛福部卻只拿總床數和護理人員增加來回應。他要求給付拉齊國際指引，並查清關床原因提出解方。","demands":["要衛福部評估推動新藥給付條件與國際醫療指引一致","要健保制度評估如何支持鼓勵蒐集真實世界數據與證據","要部長盡速找出醫院關床原因並提出怎麼解","要衛福部研究占床率資料後提供解決方案給委員","要部長儘速提出健保改革願景與召開健保國是會議時程"],"faults":["健保限縮新藥給付範圍與療程，不符國際臨床指引","醫學中心占床率從108年近八成五，掉到111年七成五","112年第一季占床率平均掉到四成八，平均掉了22%","衛福部只呈現總床數與護理人員增加，無法反映關床實況","照護司長反問關床的醫院是哪幾家，回應不恰當"],"reply":"邱泰源說符合國際醫療指引給付是國家該做的方向，今年新藥比去年多一倍；關床一定要面對，會分別了解醫中、區域、地區醫院，充實護理人力最急迫。","quotes":["限縮給付雖然省錢，但是也造成剛剛所提到的問題","這個數據明明也清清楚楚的，為什麼你們就不願意面對"],"fixed":true,"chars":4822,"followups":[]},{"gz":"GZ-1135501_00002","date":"2024-05-30","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第19次會議審查一、委員許宇甄等22人擬具「老人福利法增訂第二十二條之一條文草案」案；二、委員馬文君等16人擬具「老人福利法第二十五條條文修正草案」案；三、委員張嘉郡等20人擬具「老人福利法第二十二條條文修正草案」案","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/55/LCIDC01_1135501.pdf","pages":"149-212","target":["衛生福利部次長呂建德"],"title":"追究再生醫療法停滯10年 要求管制陳抗噪音","topics":["再生醫療法","立法進度","陳抗噪音","病患權益"],"summary":"廖偉翔追問再生醫療法為何卡了10年。他整理資料指出，2019年到2023年多次有機會三讀都沒過，是當時的邱泰源、林靜儀委員反對與另提版本所致，不是在野黨在擋。他也點出立法院附近4場陳抗吵到12點，臺大兒童醫院病童無法休息，要求衛福部代表醫療機構跟警政署協調，10點後控制音量。","demands":["衛福部代表醫療機構與警政署協調，陳抗10點後控制音量","邱泰源部長、林靜儀次長回席後，說明對再生醫療法的態度"],"faults":["衛福部把陳抗噪音推給臺北市政府，不正面回答有沒有影響病患權益","再生醫療法拖10年，邱泰源、林靜儀當立委時的立場是主因","2020年邱泰源另提版本與院版互槓，導致法案無疾而終","邱泰源堅持製劑改製品，恐使主管機關變成經濟部"],"reply":"呂建德說再生醫療法確實維護患者權益，衛福部希望加速推動；陳抗噪音屬臺北市政府權責，會轉請市府妥善處理。","quotes":["屬於它的權責，可是醫院歸你們衛福部管不是嗎？","過了10點以後能夠控制音量，以照顧病患的身心健康"],"fixed":true,"chars":3368,"followups":[]},{"gz":"GZ-1135201_00006","date":"2024-05-29","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第18次會議一、審查(一)委員林德福等19人擬具「就業服務法第四十六條條文修正草案」案、(二)委員楊瓊瓔等16人擬具「就業服務法第四十六條條文修正草案」案、(三)委員馬文君等25人擬具「就業服務法第四十六條條文修正草","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/52/LCIDC01_1135201.pdf","pages":"461-528","target":["勞動部"],"title":"就業服務法修法 要往女性權益方向前進","topics":["就業服務法修法","女性權益","勞動部","產業配套"],"summary":"審查就業服務法第四十六條修正草案，廖偉翔認同萬美玲委員的方向。他說勞動部報告寫修法可能造成針對女性歧視的問題，但他認為這和修法方向是兩回事，如果拿這個理由推託、說方向不妥適或不往這邊修法，那很奇怪。他反問其他國家標準也是這樣，難道就會出問題。他主張要往女性權益的方向前進，同時做好配套、跟各產業溝通。","demands":["勞動部：修法方向要往女性權益的方向前進。","勞動部：同步把月琴委員提到的配套做好。","勞動部：就修法內容跟各個產業溝通清楚。","勞動部長：在勞資雙方之間做好溝通橋梁。"],"faults":["勞動部報告寫修法可能造成針對女性歧視的問題，廖偉翔認為不該拿這個理由去推託修法方向。","廖偉翔認為歧視疑慮和修法方向是兩回事，不應該混在一起談。"],"reply":"","quotes":["你用這個理由去推託說你覺得這個方向是不妥適或是不往這邊修法的話","因為如果跟其他世界國家比，他們的標準是這樣，難道他們不會也造成這樣的問題嗎？"],"fixed":true,"chars":322,"followups":[]},{"gz":"GZ-1135201_00005","date":"2024-05-27","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第18次會議一、審查(一)委員林德福等19人擬具「就業服務法第四十六條條文修正草案」案、(二)委員楊瓊瓔等16人擬具「就業服務法第四十六條條文修正草案」案、(三)委員馬文君等25人擬具「就業服務法第四十六條條文修正草","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/52/LCIDC01_1135201.pdf","pages":"397-460","target":["勞動部長何佩珊"],"title":"放寬免巴氏量表、正視產假不足，勞動部別替資方講話","topics":["巴氏量表","外籍看護","產假","照顧離職"],"summary":"他要求放寬80歲以上、70到79歲癌症二期以上者免巴氏量表，點出醫界叫它功德量表，醫師開單沒有一毛錢還可能挨揍。他引勞動部統計每年13萬人因照顧離職，要跨部會加快。產假部分，勞動部自己的調查有56%認為8周不足，他要求研議延長，也批報告怕雇主不僱用育齡女性的寫法是站在資方立場。","demands":["要求勞動部跨部會儘速動起來，推動放寬免巴氏量表的法案","要求勞動部與衛福部一起加強降低照顧離職人數","要求勞動部充分研議產假不足的部分，討論多久才夠","要求勞動部回去檢討報告用語，站在勞工權益立場"],"faults":["勞動部今天的說明只有簡單4行字，看不到積極作為","去年14天就能跨部會開諮詢會議，法案一讀後卻不見效率","報告只留研議、建議評估考量，像在敷衍和推辭","報告稱延長產假恐間接影響僱用育齡女性，是幫資方講話"],"reply":"部長何佩珊說支持提案精神，去年已推多元認定，周三逐條可討論放寬條件；產假會更積極評估，用語以後會修改。","quotes":["所以我覺得開放免評才是真正的做功德，不是嗎？","你用這個說法，是不是要改名為「資」動部？"],"fixed":false,"chars":3484,"followups":[]},{"gz":"GZ-1135001_00005","date":"2024-05-23","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第17次會議邀請勞動部部長列席報告業務概況，並備質詢（113年5月22日、113年5月23日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/50/LCIDC01_1135001.pdf","pages":"383-464","target":["勞動部","勞動部部長何佩珊"],"title":"外送員每單只剩67元　要求訂外送專法保收入","topics":["外送員","平台經濟","外送專法","勞動權益"],"summary":"他從一張外送員在寒流期間的收入截圖切入，三天跑下來平均每單只有67元，還沒扣掉油資、設備攤提和罰單。外送員工會估算每單不應低於61元，他認為連這個數字都算低。兩大外送平台併購案還在公平會，外送員議價能力只會更弱。他要求中央為近15萬名外送員訂統一專法，並要部長當場表態支持。","demands":["要求勞動部長明確表態，支持訂定全國統一的外送員專法","要求專法保障外送員基本收入，並健全平台計費機制","要求部長明白宣示立場，讓專法可以往上推動跨部會的整合","要求勞動部現在就介入外送費計價，不必等併購案結果","要求專法做到平台、商家、外送員三贏"],"faults":["勞動部：平台演算法不透明，部長答不出每單多少才合理","勞動部：外送員報酬沒有中央專法，只靠地方自治條例各吹各的調","勞動部：跨區外送受不同自治條例約束，臺北新北標準不一","勞動部：Uber去年差點把外送費改為0元，主管機關沒先介入","部長被問支不支持專法反覆迴避，只說支持討論方向"],"reply":"部長何佩珊說已要求公平會在合併過程徵詢勞動部意見，會親自帶隊反映；專法要跨部會整合才有效，最後表示態度支持推動外送員專法。","quotes":["我只要問Yes or No，你要不要支持推動外送員專法？","部長，你不能用這句話一直打太極啊"],"fixed":true,"chars":3372,"followups":[]},{"gz":"GZ-1135001_00004","date":"2024-05-22","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第17次會議邀請環境部部長列席報告業務概況，並備質詢（113年5月22日、113年5月23日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/50/LCIDC01_1135001.pdf","pages":"217-382","target":["環境部部長彭啓明","環境部循環署署長賴瑩瑩"],"title":"空品12微克只是願景？資源循環促進法別再拖","topics":["空氣品質","PM2.5","塑膠公約","資源循環促進法"],"summary":"廖偉翔關心塑膠公約和空氣品質。他發現環境部業務報告沒提11月在南韓開會的塑膠公約，追問是疏漏還是刻意；資源循環促進法喊很久，仍卡在溝通階段，官員無法保證這個會期送進立法院。空品標準把PM2.5年均值從15微克降到12微克，但中期113年到116年只寫13微克，自訂的標準卻達不到。","demands":["要求環境部在本會期結束前，把資源循環促進法草案送到立法院","要求循環署提出送案的具體時程目標，事後回報委員","要求環境部今年啟動因應塑膠公約的國家計畫","要求空品標準持續往WHO年均值5微克靠近，別停在12微克"],"faults":["環境部業務報告漏掉11月南韓登場的塑膠公約，未見因應規劃","資源循環促進法喊很久，一直停在說的階段、了解的階段","循環署無法保證這個會期把草案送進立法院","標準訂12微克，中期113年到116年卻只做到13微克，形同訂好玩","口頭報告第12頁稱邁向WHO標準，12微克仍比5微克高出兩倍半"],"reply":"彭啓明說台灣背景值高、要到WHO標準很困難，會請團隊持續模擬更低選項；循環署說要先預告草案、送行政院審查，只能儘快，無法保證會期內。","quotes":["部長可不可以宣示，在本會期結束前將草案送到立法院？","我看到願景，是不是代表你做不到就叫做願景？"],"fixed":false,"chars":3547,"followups":[]},{"gz":"GZ-1134603_00002","date":"2024-05-13","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第16次會議一、審查(一)委員王育敏等21人擬具「工會法第四條及第六條條文修正草案」案、(二)國民黨黨團擬具「工會法第四條及第六條條文修正草案」案、(三)委員陳菁徽等18人擬具「工會法第四條及第六條條文修正草案」案、","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/46/LCIDC01_1134603.pdf","pages":"189-270","target":["勞動部長許銘春","銓敘部政務次長朱楠賢"],"title":"消防員團結權與勞保改革別再拖 交接要列優先","topics":["消防員工會","公務人員協會法","勞保年金改革","勞保撥補"],"summary":"廖偉翔從「火神的眼淚」切入，問勞動部長是否支持消防員為自己發聲、組工會。他發現銓敘部的公務人員協會法版本因屆期不連續被退回，到今年3月7號還在徵詢各單位意見，整個任期都在研議。他也點出勞保改革拖了8年，只靠公務預算撥補撐住現金流，要求交接時把這兩件事都列為優先，誠實面對。","demands":["要求勞動部與銓敘部把消防員團結權修法列為下任內閣優先事項","要求銓敘部說清楚下次把公務人員協會法版本送進立法院的時間","要求部長向新部長與行政院建議，勞保撥補金額要編足","要求勞動部提出法定調高退休年齡以外的鼓勵延退機制","要求交接時請下一任誠實面對勞保年金改革，不要再拖"],"faults":["銓敘部版本被退回後，到今年3月7號還在問各單位意見","勞動部拖了8年沒推勞保改革，只用公務預算撥補穩住現金流","勞動部拿帳面投資獲利對外宣傳，沒回答變現與現金流問題","部長對是否支持消防員組工會不給明確答案"],"reply":"許銘春說消防員身分特殊，組工會有侷限，傾向修公協法擴大團結權；撥補立場不變，金額看財政狀況。朱楠賢說資料交下一屆，朝放寬協商、降門檻。","quotes":["整個任期都在研議，意見不是大家早就知道了嗎？","勞保的年金改革應該刻不容緩，你們都認同對不對？"],"fixed":false,"chars":3715,"followups":[]},{"gz":"GZ-1133901_00003","date":"2024-05-02","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第14次會議審查一、委員王育敏等18人擬具「全民健康保險法第六十二條條文修正草案」案；二、委員蘇清泉等27人擬具「全民健康保險法第六十二條條文修正草案」案；三、國民黨黨團擬具「全民健康保險法第六十二條條文修正草案」案","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/39/LCIDC01_1133901.pdf","pages":"167-242","target":["衛生福利部部長薛瑞元","疾管署"],"title":"疫苗救濟審議黑箱，健保點值修法要有版本","topics":["新冠疫苗受害救濟","VICP審議程序","健保點值","健保法修法"],"summary":"廖偉翔追疫苗受害救濟。他4月初發文問VICP審議辦法，回覆是沒有另訂議事規範、沒有留錄音檔。他再查疾管署第219次會議，135分鐘審162件，平均一案約50秒，線上專家有人只參加20分鐘。他要衛福部別再上訴、重審有問題的案件；健保則要執政黨端出修法版本、保障點值。","demands":["衛福部對臺北高等行政法院112年訴字第454號判決不要再上訴","重審過去程序有問題的疫苗受害救濟案件","重新訂定VICP審議小組的議事程序與規範","衛福部提出健保法修法版本，保障醫療點值","衛福部從寬協助疫苗受害者找到救濟管道，含跨國訴訟"],"faults":["VICP審議小組沒有議事規範，也沒有保留會議錄音檔","疾管署第219次會議135分鐘審162件，平均一案約50秒","線上與會的專家學者未全程參與，有人只參加20分鐘","鑑定委員抄法醫解剖報告，就認定死因與疫苗無關","疾管署拿還沒完成的先導研究當引用依據"],"reply":"薛瑞元說大會前都有預審，因果關係是科學問題；幾千案不可能重審，還是會上訴。健保要全盤修法，只改單一條文風險很大，財源與配套得一起處理。","quotes":["我要請教部長，臺北高等行政法院的這個判決，你們還有臉上訴嗎？","你們講全盤討論已經很久了，所以就是執政黨長期沒有作為。"],"fixed":false,"chars":3782,"followups":[]},{"gz":"GZ-1133401_00003","date":"2024-04-24","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第13次會議一、邀請衛生福利部部長就「家暴零容忍─檢討112年家庭暴力防治法修正施行概況」進行專題報告，並備質詢；二、邀請衛生福利部部長、國家通訊傳播委員會、數位發展部、內政部警政署、法務部、文化部、金融監督管理委員","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/34/LCIDC01_1133401.pdf","pages":"253-346","target":["國家通訊傳播委員會","數位發展部","內政部警政署","法務部"],"title":"免實名黑莓卡照樣買得到　要求NCC源頭管制","topics":["打詐","黑莓卡實名制","電信門號管理","警示帳戶通報系統"],"summary":"廖偉翔在衛環委員會把打詐國家隊找來問。NCC去年7月宣示未實名的黑莓卡不能在臺上網，他卻在網路上買到一張，網路賣家還在首頁公告宣稱實名制政策已撤銷、網卡隨插即用。他也轉述基層員警的抱怨：警示帳戶通報子系統證號規定不一無法併案，一案要傳真8家銀行，也沒跟165連動。他要求源頭管制到位，系統確實檢討。","demands":["要求NCC說明二類電信向一類買門號的上限與年初至今總量","要求NCC強力執法，把免實名的黑莓卡管到源頭","要求數發部、警政署檢討警示帳戶聯防通報子系統","要求統一外籍人士證號輸入規定，讓同一案可以併案","要求打詐國家隊五個部會確實檢討報案流程"],"faults":["NCC消極不作為，去年7月的黑莓卡實名制宣示沒落實","NCC不掌握二類電信買門號的上限與總量","通報系統要傳真給銀行，一案設8家銀行得逐一溝通","系統沒跟165連動，被害人資料要下載再上傳，卷宗一頁頁傳","報案流程還在傳真、系統會當機，車手早把錢領走"],"reply":"NCC說廠商說法不是事實，會強力執法，並派員到委員辦公室瞭解黑莓卡怎麼買到；數發部說四十幾家業者將串接通報平臺。","quotes":["打詐國家隊中的 NCC 消極不作為，你們就是打詐的豬隊友","打詐國家隊搞到現在，整個報案流程還在搞傳真，系統還會當機"],"fixed":true,"chars":3023,"followups":[]},{"gz":"GZ-1133401_00002","date":"2024-04-22","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第13次會議邀請環境部部長、交通部、經濟部、內政部警政署就「噪音管制與加速推動排氣管噪音認證」進行專題報告，並備質詢（113年4月22日、113年4月24日、113年4月25日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/34/LCIDC01_1133401.pdf","pages":"161-252","target":["環境部部長薛富盛","環境部大氣環境司司長張順欽"],"title":"排氣管認證只管機車　聲音照相採購球員兼裁判","topics":["噪音管制","排氣管認證","政府採購","利益衝突"],"summary":"廖偉翔指出，環境部專報談排氣管噪音認證，通過認證的225組排氣管全是機車用，汽車改裝排氣管和排氣閥門卻沒納管。他接著追查移動式聲音照相採購案，得標的歐怡科技與負責儀器比測的凱鉅科技共用網站、地址相同、董監事是同一家族，等於自己的產品自己檢測。他要求環境部查清楚，並改善委外比例偏高的問題。","demands":["要環境部加速把汽車改裝排氣管、排氣閥門也納入認證管理","要環境部查明歐怡與凱鉅是否為同一批人，有不法就送檢調","要環境部說明採購文件有無明文禁止得標廠商自己協助自己","要環境部檢討核心業務大量委外、任由廠商予取予求的問題"],"faults":["環境部專報只做機車排氣管認證，汽車改裝與排氣閥門沒納管","環境部到質詢當下才知道歐怡與凱鉅的關聯，事前完全沒查","儀器比測至少有6家公司可做，卻由與得標廠商同集團的凱鉅承作","環境部政風處未察覺接案、驗收一條龍的利益衝突","環境部委外經費在各部會排第一，預算中心已點名過"],"reply":"薛富盛說下一階段汽車也應納管，噪音超標不分汽機車都會裁罰；強調絕不護短，歡迎舉發，會再瞭解情況。張順欽說採購案尚未驗收，先前不清楚兩家公司的關聯。","quotes":["這就是球員兼裁判啊","我希望貴部儘快調查，如果有任何不法，也請檢調來儘速調查"],"fixed":false,"chars":3294,"followups":[]},{"gz":"GZ-1132901_00006","date":"2024-04-17","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第12次會議邀請環境部部長、經濟部、行政院國家永續發展委員會就「限塑政策執行成效，及家戶與一般事業廢棄物減量之檢討與策進作為」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/29/LCIDC01_1132901.pdf","pages":"341-422","target":["環境部部長薛富盛"],"title":"汰用電池不該只當廢棄物，要環境部給再利用身分","topics":["電池回收","資源循環","電動車","限塑與減廢"],"summary":"廖偉翔關心電池回收與資源循環。他指出環境部書面報告中，電池廢棄循環法規和測試標準都還在訂定，用詞只有促進、加強，也答不出電池回收率的政策目標。車用電池衰退後在國內被直接當廢棄物做成黑粉，法令管制讓想研究的人連素材都拿不到。他要求環境部給汰用電池可再利用的法令身分。","demands":["要環境部給汰用電池明確的再利用法令身分，並說明時間","要環境部提出電池回收率的政策目標與具體作法","要環境部趕在2025年大量報廢期前推動資源循環","要薛部長把這屆經驗和重要的事交接給下一任"],"faults":["環境部電池廢棄循環法規與測試標準至今仍在訂定","環境部書面報告只寫促進、加強，沒有具體方向","環境部答不出電池回收率目標，英國目標是95%可回收","法令把汰用車用電池當廢棄物，創新研究拿不到素材"],"reply":"薛富盛說電池另有回收分類、不能丟一般垃圾，目前約有6家合法電池回收業者，規模與法制還要更健全，並請支持資源循環促進法。","quotes":["我想要講的事情是人家是把廢物變黃金，可是我們現在因為法令的關係","部長，有沒有什麼具體的目標？比如說人家是95%的電池可以被回收，我們有沒有？"],"fixed":false,"chars":2829,"followups":[]},{"gz":"GZ-1133001_00003","date":"2024-04-17","committee":"教育及文化委員會","agenda":"教育及文化委員會第8次會議邀請教育部部長潘文忠列席就「教改30年廣設大學及技專升格如今面臨整併退場之問題及對策」進行專題報告，並備質詢（113年4月17日、113年4月18日為一次會）","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/30/LCIDC01_1133001.pdf","pages":"99-166","target":["教育部","教育部部長潘文忠"],"title":"學習歷程紀錄搞到天怒人怨 要求教育部研議廢除","topics":["108課綱","學習歷程檔案","升學制度","學生壓力"],"summary":"廖偉翔關心108課綱學習歷程紀錄造成的學生壓力。他自做問卷、樣本都是高中生：84%覺得很困難、幫助程度平均只有1.2分、痛苦程度4.45分，78.3%支持廢除。他說檔案變成升學工具，補習班當賣點，網路上還有10萬到20萬的代寫。他要教育部檢討，研議廢除或提出替代方案。","demands":["請教育部研議廢除學習歷程紀錄，或研擬替代方案、修正方法","請教育部把研議與檢討的結果提供給委員","請教育部正視備審資料加上學習歷程的雙重壓力，回去思考研議"],"faults":["教育部沒對校方、教師、學生做過學習歷程滿意度調查","學習歷程變成升學工具，補習班拿來當賣點","只呼籲抓到代寫就取消資格，代寫仍是盛行的產業","多一個升學管道等於多一個壓力來源，壓力加倍"],"reply":"潘文忠說推甄本來就有備審資料，性質一樣；過程也不斷在簡化，委員提的可以再做研議、檢討，讓學生真正扣合學習。","quotes":["學習歷程紀錄算是一個搞到天怒人怨","請問部長可不可以回去研議廢除學習歷程紀錄"],"fixed":false,"chars":3829,"followups":[]},{"gz":"GZ-1132901_00005","date":"2024-04-15","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第12次會議邀請衛生福利部部長、內政部、法務部、教育部、數位發展部、國家通訊傳播委員會、文化部就「數位技術普及造成兒少性剝削案件增加之因應作為與現行政策檢討」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/29/LCIDC01_1132901.pdf","pages":"227-340","target":["衛生福利部部長薛瑞元","法務部","數位發展部"],"title":"封網拖八百多天 要求組織犯罪加重刑、輔導延長三年","topics":["兒少性剝削","封網","護理人力","AI規範"],"summary":"廖偉翔先問護理人力，指出護理人員月薪四萬七千多、平均年薪不到70萬，要求政府拉到70萬起跳，也追問夜班獎勵費何時入帳。主軸則打兒少性剝削網站案，痛批衛福部拖八百多天才要求封網，主張修法對組織形式犯罪加重二分之一、被害人輔導從一年提高到三年，並要數發部趕快規範AI。","demands":["要求衛福部在4月底前答復護理夜班獎勵費何時入帳","要求衛福部作政策性宣示，讓護理人員薪資達70萬起跳","主張增訂第四十一條之一，以組織形式犯本條例之罪加重二分之一","要求把被害人輔導協助的一年地板提高到三年","要求數發部加緊規範AI，避免AI變成性犯罪工具"],"faults":["衛福部拖八百多天才發文要數發部封網，消極不作為","衛福部沒做過年輕女性自殺率與兒少性剝削相關性研究","數發部、衛福部、內政部缺橫向溝通，受害者被偷拍6年沒下文","護理夜班獎勵費卡在行政院，公告實施時間仍不確定","數發部現在才要研議用AI偵測，落後歐盟與美國"],"reply":"薛瑞元說行政處分須先送達、有法律風險；夜班費在等行政院核定，4月底答復有機會；加重刑度須法務部評估，輔導延長為三年可以再思考。","quotes":["衛福部是能有所作為，但是毫無作為","結果平均年薪不到 70 萬，這樣請得到人嗎？"],"fixed":false,"chars":5166,"followups":[]},{"gz":"GZ-1132301_00004","date":"2024-04-01","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第10次會議邀請衛生福利部部長、環境部、行政院食品安全辦公室、行政院消費者保護會、臺灣菸酒股份有限公司就「蘇丹紅、小林製藥紅麴原料以及寶林茶室食物中毒案等重大食安事件之檢討與策進作為」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/23/LCIDC01_1132301.pdf","pages":"203-300","target":["衛生福利部部長薛瑞元","環境部化學署署長謝燕儒"],"title":"日本草莓農藥標準鬆綁 食安不該當談判籌碼","topics":["食安","進口農藥殘留","寶林茶室食物中毒","毒化物管理基金"],"summary":"廖偉翔指出食藥署1月24日預告放寬日本草莓農藥標準，3月29日公告、4月1日實施，但克凡派、滅達樂在CODEX是不得檢出，質疑放行的科學依據。他要求面對外國貿易施壓不能讓步。另指臺北稽查科36%人員離職，2019年修法要設的毒化物管理基金拖了五年多還沒成立。","demands":["要求食藥署說明放寬克凡派、滅達樂殘留標準的科學依據","要求政府面對外國貿易施壓不讓步，以國人健康做最嚴格把關","要求衛福部針對小林製藥案出面當統籌單位","要求環境部化學署盡快成立毒物及化學物質管理基金","要求政治人物不要散布食安謠言，別打擊基層稽查人員士氣"],"faults":["食藥署1月24日預告、3月29日公告，4月1日就實施，過程匆促","克凡派、滅達樂在CODEX是不得檢出，我方卻在申請後放寬","一邊開放日本農藥殘留標準、一邊說加強邊境查驗，邏輯矛盾","臺北市稽查科36%人員離職，食安稽查人力流失","毒物及化學物質管理基金2019年修法明定，拖五年多未成立"],"reply":"薛瑞元說米酵菌酸檢驗與培養正在做；小林製藥部分，日方已透過IHR聯繫，要求我方蒐集可能的案例情況回報，目前正在做；草莓是日、台用藥不同才無殘留標準，廠商依法申請、經專家會議審過，CODEX不是唯一參考標準。","quotes":["食藥署究竟應該要幫我們國人保障健康，還是要幫日本賣草莓","國人的健康不應該變成政治利益的談判籌碼"],"fixed":true,"chars":4132,"followups":[]},{"gz":"GZ-1132102_00002","date":"2024-03-28","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議一、邀請衛生福利部部長就「社會安全網缺失檢討及具體改進作法」進行專題報告，並備質詢；二、邀請衛生福利部部長、教育部次長就「出養童遭虐致死事件檢討會議要求新北市政府、臺北市政府及兒童福利聯盟所提供之檢討報告」","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/21/LCIDC01_1132102.pdf","pages":"355-526","target":["衛生福利部部長薛瑞元"],"title":"電價漲衝擊近貧　要求社救法降門檻補破洞","topics":["社會救助法","近貧族群","電價調漲","自殺防治"],"summary":"他關心四月電價平均調漲11%後，物價房租跟著漲，弱勢更難撐。他指社會救助法門檻太高，一群拿不到救助資格的貧窮人口被擋在外面，約占人口6%、近150萬人，救助網的洞越破越大。他要衛福部儘速提修法版本、降低門檻，也要正視年輕族群自殺率攀升，趕快訂出延宕五年多的全國自殺防治綱領。","demands":["要衛福部儘速提出社會救助法修法版本，把申請門檻降下來","要衛福部一個禮拜內提供社救法修法進度與預計期程","電價調漲前要先評估弱勢族群衝擊，520前不要調漲電費","要衛福部擴充年輕族群心理衛生諮詢量能，並落實到校園","要衛福部與教育部合作，儘速訂出全國自殺防治綱領報院"],"faults":["衛福部社救法門檻高，約6%、近150萬近貧人口拿不到資格","衛福部沒有評估電價調漲11%對弱勢族群的衝擊","社福邊緣戶從早期約兩成升到三成多，救助網接不住人","年輕族群心理衛生諮詢方案量能不足，校園覆蓋也不夠","自殺防治法108年就通過，全國自殺防治綱領拖到113年還在草案"],"reply":"部長薛瑞元說社救法修法討論中會有新版本，社福機構電費排除調漲，已推年輕族群心理衛生方案並將與教育部合作；司長說綱領下個月報院。","quotes":["今天這一題我就是想要告訴你，這個事情是真實存在，我想替他們發聲。","現在已經都113年了，為什麼要拖這麼久？"],"fixed":true,"chars":3196,"followups":[]},{"gz":"GZ-1132102_00001","date":"2024-03-27","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第9次會議一、邀請環境部部長就「邁向碳有價時代，碳費擬定時程表及碳費審議委員會之相關內容」進行專題報告，並備質詢；二、處理或審查中華民國113年度中央政府總預算有關環境部主管預算凍結案49案（含報告事項45案及討論事","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/21/LCIDC01_1132102.pdf","pages":"1-354","target":["環境部","環境部部長薛富盛"],"title":"碳費時程一再跳票 廖偉翔要環境部別拖過520","topics":["碳費","綠色通膨","食安化學物質","CBAM"],"summary":"廖偉翔先提臺北市信義A13疑似食物中毒事件，9起案例、1人死亡、2人命危，要求環境部緊盯57種食安風險化學物質。主軸質疑碳費時程延宕：審議委員會3月15日才首次開會，兩次都沒結論，本季承諾跳票，企業算不出成本、連明年預算都編不了。他要求加快時程，把CPI與綠色通膨納入評估。","demands":["環境部持續追蹤57種食安風險化學物質流向，必要時主動提供數據給檢調","碳費費率審議委員會加快時程，不要拖到520之後才掀底牌","費率審議要實際估算開徵後CPI會漲多少、連續漲幾年","規劃把部分碳費收益返還社會大眾，減輕低收入家庭負擔","經濟衝擊評估不該只由環境部主導，要拉高層級做跨部會協調"],"faults":["環境部碳費費率審議委員會3月15日才開第一次會，時程太晚","審議兩次都沒有結論，原本這一季的承諾已經跳票","4月要再開一場，時間到現在都還沒確定","進度落後讓企業無法估算成本，連明年預算都不知道怎麼編","碳費喬不定，衝擊碳交易量、CBAM協商並帶來碳洩漏疑慮"],"reply":"薛富盛說57種化學物質運作須環境部核可、每月登記化學雲；碳費審議已有共識但費率未定，不以520為時間點，會請委員會把CPI納入考量。","quotes":["所以已經審議兩次都沒有結論，本來這一季說要承諾，也已經確定跳票","企業完全沒有辦法估算成本，連明年的預算要怎麼編都不知道"],"fixed":false,"chars":3003,"followups":[]},{"gz":"GZ-1131901_00001","date":"2024-03-25","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第8次會議一、邀請勞動部部長就「事業單位應加強安全衛生管理制度、作業流程及必要教育訓練，並落實職場防災管理」進行專題報告，並備質詢；二、處理中華民國113年度中央政府總預算有關勞動部主管預算凍結案21案（含報告事項2","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/19/LCIDC01_1131901.pdf","pages":"1-148","target":["勞動部部長許銘春","勞動部職業安全衛生署","勞動及職業安全衛生研究所"],"title":"職災重建之家疊床架屋 工安警訊淪為紙上宣導","topics":["職業安全","職災重建","工安警訊","政策性貸款"],"summary":"廖偉翔質疑勞動部在高雄設職業健康及重建之家是疊床架屋：現有36家專責醫院、20家強化訓練機構、22個縣市個案管理都在，高雄專責醫院更有5家，部長卻說不出要花多少錢、服務多少人。他並指勞研所2022年10月已發布水蒸汽爆炸工安警訊，高雄市政府的專頁卻從2022年開始停擺至今，質疑高雄市政府在佳豐鋁業2死6傷的悲劇中，是不是有該宣導而未宣導的行政責任。","demands":["要求勞動部會後提供重建之家與現有機制差異的分析報告","要求勞動部專案督導高雄市政府的工安警訊宣導與勞檢","要求職安署針對中央預警的產業加強勞檢頻率與內容","要求把三項勞工政策性貸款納入政府全額補貼升息利息","若不補貼，要求勞動部自辦因應升息衝擊的還款展延"],"faults":["勞動部講不清重建之家能補足現有機制哪些不足","勞動部答不出重建之家要花多少錢、服務多少人","高雄市政府工安警訊專頁自2022年開始停擺至今","高雄市政府連最基本的轉知、宣導責任都沒有落實，勞動部沒有盡到督導之責","質疑高雄市政府在佳豐鋁業2死6傷的悲劇中，是不是有該宣導而未宣導的行政責任"],"reply":"許銘春說原址是歷史建築、已另覓新址，數據會後補；高雄市部分要再瞭解；升息5次已補貼4次，鳳凰創業貸款一年只增896元。","quotes":["為什麼要浪費公帑去蓋一個蚊子館","現在要去瞭解就代表你平常沒有盡到督導之責"],"fixed":true,"chars":4287,"followups":[]},{"gz":"GZ-1131801_00015","date":"2024-03-21","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議邀請環境部部長、經濟部、農業部、國家發展委員會、行政院國家永續發展委員會就「加速推動再生能源對國土環境之影響及環境影響評估認定標準修訂進度」進行專題報告，並備質詢（113年3月20日、113年3月21日為一","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/18/LCIDC01_1131801.pdf","pages":"325-404","target":["環境部部長薛富盛"],"title":"光電環評只管1.1%國土 要求環境部限期修法","topics":["再生能源","環境影響評估","太陽光電","SRF"],"summary":"他關心太陽光電大量進駐農漁地的環境衝擊。現行認定標準只有重要濕地才要做環評，環境部管得到的只有1.1%國土，其餘98.9%推給經濟部；台南七股光電已達3,500公頃、占七股面積三成，氣溫飆到43.7度。他主張環境部把光電環評收回來自己管，限期提出修法進度與草案預告。","demands":["環境部1個月內提出光電環評的具體修法進度","環境部3個月內把認定標準修正草案預告","管制一定範圍內的光電板總量，不要讓密度高到衝擊環境","環境部主動協助地方政府認定並拆除廢棄光電板","SRF儘速修法"],"faults":["部長沒實地看過任何光電案場，就認定影響較少","現行標準只有重要濕地要環評，僅涵蓋1.1%國土","環境部把近99%陸地面積的環境把關讓給經濟部","環評委員連署要求修法滿一年，草案仍未預告","廢棄光電板沒有法規認定，地方只敢裁罰不敢拆"],"reply":"部長說修法方向是對單一開發案超過一定面積或發電量管制，並納入國家公園、保護區等敏感地區；SRF已在修法，改從源頭做產品分類。","quotes":["你沒看過怎麼會做出這樣的結論呢？","看起來今天環境部不是不管，而是刻意不管"],"fixed":true,"chars":3568,"followups":[]},{"gz":"GZ-1131801_00014","date":"2024-03-20","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第7次會議一、邀請勞動部部長、衛生福利部、教育部就「落實職場性別平等及性平三法上路如何落實雇主責任」進行專題報告，並備質詢；二、邀請衛生福利部、勞動部、教育部就「完善職場育兒環境及托育人員專業職能、工作倫理及職業道德","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/18/LCIDC01_1131801.pdf","pages":"237-324","target":["勞動部長許銘春"],"title":"產假56天遠低國際標準　電價漲要先評估失業衝擊","topics":["電價調漲","產假","性別平等","勞動節放假"],"summary":"廖偉翔關心電價調漲對勞工的衝擊：今年電價可能漲超過11%、工業用電超過15%，高耗能和低轉嫁能力產業首當其衝，他要勞動部先評估失業影響。他也點出女性產假只有56天，休完只能靠傷病假安胎，遠低於國際勞工組織建議的14週，要求儘速向國際標準靠攏，人才庫也要訂門檻和淘汰機制。","demands":["勞動部說明51勞動節全國一致放假的研議情形和預計完成時程，他擔心放假不一致，幼兒園老師放假但家長沒放假，小孩沒人顧","勞動部評估電價漲幅對高耗能、低轉嫁能力產業的衝擊並啟動保護措施","勞動部儘速研議產假向國際勞工組織建議的14週靠攏","性別平等人才庫訂具體門檻、定期檢視資格、建立淘汰不適任者機制","1到2個月內提出彈性上班、獎勵友善企業的研議報告"],"faults":["勞動部沒針對電價漲幅對失業率的影響做過專業評估","產假56天休完，女性只能再扣自己的傷病假安胎，並不平等","性別平等人才庫只有16到24小時授課時間，門檻不夠具體","勞動部對51勞動節放假研議時程說不清楚，稱是內政部主管"],"reply":"許銘春說行政院朝肯定方向研議放假一致；電價與失業關聯初步不直接，但將列入基本工資參酌；產假與人才庫會研議、滾動檢討。","quotes":["只有女性才能生小孩，但把 8 週的產假用完後，就只剩下以傷病假的名義來讓自己能夠安胎休養","因為我國的產假規定遠低於國際勞工組織建議的 14 週"],"fixed":true,"chars":2696,"followups":[]},{"gz":"GZ-1131501_00002","date":"2024-03-18","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第6次會議邀請衛生福利部部長、教育部、法務部、內政部警政署就「社會安全網推動情形及策進作為」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/15/LCIDC01_1131501.pdf","pages":"61-206","target":["衛生福利部部長薛瑞元","教育部"],"title":"社安網正在瓦解：要衛福部設兒少保護基金並留住社工","topics":["社會安全網","社工人力","兒少保護","青少年心理健康"],"summary":"廖偉翔說社安網正在瓦解中，靠全國1萬8,600多名社工才撐得住，但社工高風險、高案量、高壓力，又缺督導、缺合作、缺資源，薪資偏低，留任困難已是結構性問題。他指出衛福部對虐童致死案的檢討報告太模糊、沒有配套，兒少保護經費也偏少，主張提高社工薪資與專業認同，並成立中央兒少保護基金。","demands":["要求衛福部儘速研議，把兒少保護業務獨立，成立中央兒少保護基金","要求衛福部調高社工薪點折合率，並提出提升專業認同的具體行動方案","要求衛福部把提高訪視率的作業準則和地方人力配套訂細，下次重提報告","要求衛福部評估114年心理諮商次數，從每人3次增加到至少6次","要求衛福部把中部、南部的少家專業法院需求帶回行政院和司法院"],"faults":["衛福部檢討報告太模糊、沒有配套，廖偉翔主張予以退回","社工團體發聲明譴責衛福部未在重大兒虐案30天內完成調查報告","衛福部前一天才提供虐童案時序表，資料晚到","社家署收養資訊中心業務計畫每年約127萬，兒少保護經費不足","大專院校每1,200名學生只配1名專業輔導人員，學生要等約1個月"],"reply":"薛瑞元說社工上銬不妥、薪資調升要看財政，出養改由地方評估，成立基金須向行政院請示。教育部說修正案擬把大專1,200比1降為900比1。","quotes":["我們應好好檢討並解決問題，不要讓個案變通案、通案變系統性的危機","我認為我們應該要想辦法來重振社工的士氣"],"fixed":false,"chars":5752,"followups":[]},{"gz":"GZ-1130901_00002","date":"2024-03-07","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第4次會議邀請衛生福利部部長、中央健康保險署、食品藥物管理署就「健保藥價調整，藥廠停產慢性病用藥之因應作為」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/09/LCIDC01_1130901.pdf","pages":"133-210","target":["衛生福利部部長薛瑞元","中央健康保險署署長石崇良","食品藥物管理署"],"title":"掛號費上限取消未評估，蘇丹紅擴大要中央擔責","topics":["健保點值","缺藥","食安","蘇丹紅"],"summary":"廖偉翔質疑衛福部無預警取消掛號費上限，事前沒評估也沒溝通，還把責任推給地方，真正該解決的是健保點值長期不公。他追問缺藥，要求食藥署從製造端和輸入端常態掌握未來1年供應。談蘇丹紅時他指出，112年進口辣椒製品276萬公斤，查獲量已從二萬多公斤增至6.4萬公斤，要中央擔起責任。","demands":["要求衛福部提出完整的健保總額制度改革方案，不要急就章","要求食藥署從製造端和輸入端常態掌握未來1年的藥品供應","要求健保署盡快讓健保藥品政策改革方案定案並進行預告","要求評估三條件排除藥價調整：醫學會認證、在地製造、三張以下藥證","要求中央建議縣市營養午餐先不要用辣椒粉，別全推給地方"],"faults":["衛福部取消掛號費上限前沒做評估，也沒和各界溝通","衛福部只動掛號費，沒處理健保點值長期不公的核心問題","食藥署只在缺藥時控藥，沒針對缺藥原因預先因應","食安會報原訂1月召開，因選舉因素拖到現在還沒定日期","部長說重視食安，卻缺席下午3點召開的食安會報"],"reply":"部長薛瑞元說倒是沒有這樣大規模地去做這種溝通研議，掛號費本來就是行政費用，健保的改革是健保的改革，並說缺藥的品項都有替代的或者是同成分的品牌；健保署署長石崇良說快的話大概在4月份就會進行支付標準的預告。","quotes":["政策是不能隨性的，我覺得很多政策你們必須要經過審慎的評估才可以","現在我們遇到系統性的食安問題，你用這種硬拗的態度是沒有辦法幫助我們的"],"fixed":true,"chars":5896,"followups":[]},{"gz":"GZ-1130701_00003","date":"2024-03-06","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第3次會議邀請勞動部部長、外交部、勞動力發展署、衛生福利部、內政部、國家安全局就「我國開放印度移工對本國勞工就業市場之衝擊」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/07/LCIDC01_1130701.pdf","pages":"125-214","target":["勞動部部長許銘春","勞動力發展署署長蔡孟良"],"title":"疑慮沒解就簽印度移工MOU　失聯移工飆到八萬多","topics":["印度移工","MOU","失聯移工","缺工"],"summary":"廖偉翔質疑政府開放印度移工太急。勞動部去年11月16號還說社會有疑慮、MOU尚在草擬，約3個月後就簽了，也沒做新評估報告，最新只有106年那份。他指出部長2018年就任至今，失聯移工從五萬多人增到八萬多人，缺工仍在23萬高檔。他主張移工與勞動力政策要通盤檢討，從產業結構解決。","demands":["勞動部要先把社會對印度移工的疑慮講清楚，不要急著往前推","移工與勞動力政策要通盤檢討，配合產業需求解決結構性問題","部長在520之前要大破大立，把該做的事做好","談引進要小心種族、區域的說法，不要變成人權笑話","勞動部後續要做什麼，會後書面補充給委員"],"faults":["勞動部自己也知道疑慮沒解除，卻約3個月就把MOU簽了","這次開放沒做新評估報告，最新只有106年那份官方評估","報告提到要看哪個種族適合臺灣，勞動部答詢說並未評估","部長2018年就任至今，失聯移工從五萬多人變成八萬多人","報告只強調新增人數比上一年少九千多，迴避總數持續上升"],"reply":"部長許銘春說失聯人數暴增主因是三年疫情，勞動部會繼續努力；家庭看護工薪資已從1萬7,000調到2萬，未來會加重非法僱用、非法仲介罰則。","quotes":["我要提醒部長要小心，不要變成人權笑話","這是一個結構性的問題，你應該要從整個大結構配合產業的需求去通盤地考量"],"fixed":false,"chars":4664,"followups":[]},{"gz":"GZ-1130601_00008","date":"2024-03-04","committee":"社會福利及衛生環境委員會","agenda":"社會福利及衛生環境委員會第2次會議邀請行政院食品安全辦公室、衛生福利部部長、食品藥物管理署就「食安五環執行狀況及蘇丹紅事件處理之檢討」進行專題報告，並備質詢","pdf":"https://ppg.ly.gov.tw/ppg/PublicationBulletinDetail/download/communique1/final/pdf/113/06/LCIDC01_1130601.pdf","pages":"209-296","target":["衛生福利部部長薛瑞元","行政院食品安全辦公室主任許輔","食品藥物管理署"],"title":"蘇丹紅辣椒食品流向不明　批食安五環破功","topics":["食安","蘇丹紅","邊境查驗","食安會報"],"summary":"廖偉翔盯食安會報和蘇丹紅。食安會報沒依規定每3個月開會，身兼執行長的衛福部長已343天沒參加。蘇丹紅方面，2批流入市面的辣椒粉合計2萬8,903公斤，流向沒公開；他算出兩年來蘇丹紅辣椒食品有12件、10萬8,178公斤，專案報告卻只寫9件、5萬5,275公斤，要求交代差額並道歉。","demands":["要求衛福部長一個禮拜內就問題食品與差異數額提出報告","要求公開2萬8,903公斤蘇丹紅辣椒粉的下架回收與流向","要求交代差額5萬2,903公斤蘇丹紅辣椒食品現在在哪裡","要求行政院儘快排定食安會報日期並把蘇丹紅列入檢討","要求部長承認食安五環破功並向國人道歉"],"faults":["行政院食安會報沒有依規定每3個月定期開會","衛福部長身兼食安會報執行長，343天沒有參加會議","專案報告只寫9件、5萬5,275公斤，隻字不提10萬8,178公斤","衛福部避重就輕，把辣椒食品縮成辣椒粉來講","行政院食安辦沒有科學證據就對外打臉衛福部"],"reply":"部長說已對不合格廠商辣椒粉做後市場監察，共查59批，42批合格、11批不合格、6批仍在檢驗，結果出來會提供委員。","quotes":["整整 2 萬 8,903 公斤的流向，何以至今沒有公開？這豈不是食安五環破功嗎？","我認為衛福部在避重就輕，因為所有辣椒食品當中，有碰到蘇丹紅的"],"fixed":false,"chars":3500,"followups":[]}]};
